rows["20:976092793"]="케잔, 트롤들!"
rows["20:98455276"]="피가 있을 것 이다!"
rows["20:986140031"]="센라리우스는 쓰러졌어!"
rows["20:988817034"]="미안해 아빠"
rows["20:989203233"]="자, 고통을 느껴봐라..."
rows["20:98978303"]="넌 그렇게 강하지 않아!"
rows["20:99033210"]="하지만 그의 아들은 죽었어"
rows["20:993546581"]="저주받아라, 영원히!"
rows["20:995730289"]="삐걱거리는, 작은 해충."
rows["20:998158711"]="%s 스카이프 공격!"
rows["210:1019782355"]="성당의 방역을 무장하면 더 빨리 확보할 수 있어 레지옹과 케일에 대한 대규모 공격을 해낼 때 어떤 비참자가 방해를 받지 않길 바랍니다$B$B우리는 $3244w 퍼센트로 목표에 도달했습니다."
rows["210:1055282324"]="추모 상자 안에 있는 보상의 양과 질은 위대한 십자군 재판에서 얼마나 많은 실패한 시도를 했느냐에 달려 있습니다. 실패한 시도가 적을수록 더 좋은 보상입니다."
rows["210:1158252581"]="드래곤하크는 제대로 키우면 아주 매료합니다. 당신은 그것이 매력적이라고 생각하지 않습니까?"
rows["210:126101250"]="이 성전 은 단지 이름 이 아니었기 때문 이다. 세계 기둥 은 이 성전 의 무게 를 더 많이 지지 하였다. 그것 은 재건 해야 하며 그렇지 않으면 디폴름 전체 는 아제로스로 붕괴 될 것 이며, 이 두 세계 도 에 재앙적 인 결과 가 있을 것 이다."
rows["210:1287600694"]="저는 전투에서 아이들을 죽이는 것을 보았습니다. 그들은 피에 갈망했습니다. 나는 그것을 용납할 수 없었지만 어떻게 일어날 수 있는지 알 수 있었습니다. 하지만 확실히 그들은 이 방어하지 않는 포로로부터 의식적인 희생을 하지 않을 것입니다."
rows["210:1637679800"]="오, '나는 내 집착을 깨달은 슬픈 날이었다. 나는 깨어 났고 내가 맥주 첫 tankard 전에 '타닌' 자신을 발견. 거의 심지어 존경받는 홍수!"
rows["210:1645732905"]="아라티 계곡의 전투는 자원과의 싸움입니다. 목재, 광석, 식량...$B$B적들의 물품을 거부하는 것은 전투장에서 그들을 죽이는 것과 같다."
rows["210:1762203108"]="이 시간에는 대화가 필요없어요! 스컬지 군대가 우리의 전쟁선을 압박하고 있습니다. 선택의 무기를 들고 그 배를 보호하십시오!"
rows["210:1805578025"]="내가 이 길을 다 왔는데, 유명한 \"드래곤마우의 시야자\"와 대화를 나누고 싶었어요.$B$B하지만 그녀는 내게 쓸모없어 수수께끼와 시가 많아서"
rows["210:1959913961"]="최근까지 이 곳은 안개 속에서 사라져 버렸던 곳이었으며, 그 몇 명 정도인 주민들은 시간 왜곡에 면제 없이 자신의 화폐를 만들어야 했습니다."
rows["210:2000757888"]="라그나로스의 신체적 형태가 파괴되어야 합니다. 그 잔해에서 그의 본질이 나오게 됩니다. 이 약화된 상태에서, 라그나로스의 포로가 풀려납니다. 본질 자체가 열쇠로 작용합니다."
rows["210:2067724261"]="실버문의 파스트라이더 광장 내에 발견된 피 엘프의 이레다는 한 손으로 쓰이는 검과 두 손으로 쓰이는 검을 모두 훈련시킵니다. 언더시티의 무기 마스터 아치발드는 또한 당신을 훈련시킬 수 있습니다. 그는 전쟁 구역에 있습니다."
rows["210:2129003344"]="내 동생이 이 괴물들을 다 죽여야 한다고 생각하네$B$B너무 늦기 전에 모두 없애야 합니다!"
rows["210:237725962"]="여자들이여, 오늘이 여러분의 가장 위대한 날일 수 있습니다. 왜냐하면 오늘은 Stormpike의 영광을 위해 싸우고 있기 때문입니다."
rows["210:346352971"]="에메랄드 드레이크 는 완전한 힘 을 가지고 있는 도래  ⁇ 을 수행 할 수 있으며, 그 도래크 의 생명 에너지를 친근 한 목표 로 전달 하여 치료 할 수 있다."
rows["210:348831525"]="마그니 왕의 운명은 내 책임과 부끄러움입니다. 저는 그를 격려하기 보다는 인내심을 조언해야 했습니다. 의식을 완성하는 그의 급행은 그에게 목숨을 걸고 우리에게 아무런 도움이 되지 않았다는 것을 깨닫지 못하고"
rows["210:375444713"]="듀로탄의 아들이여, 당신은 내가 알지 못했던 절대적인 신뢰가 어떤 것인지를 보여 주었소. 당신과 당신의 동맹은 어떠한 값어치로도 매길 수 없는 구원이라는 선물을 내게 주었소이다. 마그하르의 구세주 스랄이여, 당신은 그 누구도 내게 주지 못했던 명예를 가르쳐 주었소..."
rows["210:662351921"]="내가 당신을 위해 할 수 있는 것은 무엇이라고 생각하십니까?$B$B빨리 일을 해봐, 아니면 내가 널 때릴 거야!"
rows["210:748415987"]="몇 밤 전 샬트라스에서 왔고 그 이후로 계속 논쟁하고 있습니다.$B$B내가 당신을 거절하지 않았다는 것을 보고 기쁘는데, 그들은 잠재 고객을 겁에 질렸다고 생각하기 시작했습니다."
rows["210:770637873"]="지형 반지는 제펠린 타워 북쪽의 절벽에 세계 각 지역에 포털을 설치했습니다.\010헬스크림의 대표들도 있고, 톨 바라드에 교통을 제공하고 있습니다."
rows["211:1094098418"]="무슨 뜻인지 알겠네$b$b저는 단지 제 지평을 조금 넓히고 세상을 보고 싶어서 이 자리에 있습니다.$b$b다른 사람들의 일에 대해 별로 신경쓰지 않아요.$b$b만나서 반갑습니다\010"
rows["211:1140472698"]="그러니까... 어느날 밤에 훌쩍 남쪽으로 여행을 떠나는 건 어떨까요?! 국경에서 벌어지는 전투를 구경할 수도 있겠죠. 어때요, 살데릴 경? 정말 재미있을 것 같지 않나요?"
rows["211:1169378505"]="여기 있는 거들, 우리가 필요한 모든 것을 수집했다는 겁니다. 이제 모든 것이 호드 그들이 물건을 가져갈 때 우리는 모든 물건을 실리투스로 보낼 수 있고 전쟁이 시작될 수 있습니다."
rows["211:1220015425"]="저쪽으로 향하고 있는데, 전 왕비 경비대에 머물렀어요.$b$b내가 당신에게 거래를 해 줄게요. 길을 정리해줘요. 그리고 네, 네, 네 그룹에 합류할게요."
rows["211:1238077023"]="필멸의 영웅들이여, 오늘 이 승리는 오래전에 예견되었다네. 내 형제가 고통스럽게 내뱉은 패배의 울부짖음은 온 우주에 울려 퍼질 걸세. 그리고 불타는 성전에 맞서 싸우는 이들에게 새로운 희망을 전파하겠지."
rows["211:1265176606"]="이 일은 약한 심장이 없는 낯선 사람이 아니라면, 당신이 우리를 도와줄 수 있다면 볼진이 당신을 신뢰하게 될 수도 있습니다. 얼라이언스 할 수 있어?"
rows["211:1366116407"]="그리틴의... 그리고, 아... 안녕하세요, 전요.$b$b미안해, 무슨 말을 해야 할지 모르겠지만, 여기 있는 사람들은 별로 안 어울리는데 익숙하지 않아.$b$b물론 제 맥주 좀 사러 온다면요"
rows["211:13934235"]="뭔가 이상한 냄새가 나는군요! 제가 아닌 건 분명하다고요. 노움은 모름지기 버터와 햇살 냄새를 풍기니까요. 트로그 겨드랑이에서 태어난 것 같은 냄새를 풍기는 드워프와는 다르다고요! 여기에 드워프가 있는 건 아니겠죠?"
rows["211:1440096468"]="그 후 일어난 비극적인 사건들은 아티시와 접촉한 모든 키린 토르 마가의 죽음을 초래했습니다.$B$B보시다시피, 그것은 감각이 있는 유물이었죠."
rows["211:1661048168"]="시간이 없어, 친구들! 내가 최근에 만든 기막힌 발명품을 시험하게 도와 주겠지? 자, 마음 바꿀 생각은 말라고. XT-002를 그 꼬락서니로 만들었으니, 너흰 나한테 빚진 셈이란 걸 잊지 마!"
rows["211:176124064"]="Quel'thalas의 물은 물고기로 가득합니다; 나는 그들이 당신의 눈을 사로 잡았을 것을? Drathen는 낚시 무역의 트릭을 꽤 경험하고 있으며, 왕립 거래소 근처에 노인 행보에서 찾을 수 있습니다."
rows["211:1819870944"]="장군들은 우리가 앞으로의 아안키라지 전쟁에 필요한 모든 것을 수집했다고 말합니다. 이제 우리는 호드의 저장량을 완료하고 전쟁 재물의 운송이 시작될 때까지 기다리고 있습니다."
rows["211:1833936920"]="지난 몇 년 동안 마녀 네크로스 스켈러크러셔가 강력한 유물을 남용하여 알렉스스트라사와 붉은 용 비행의 많은 부분을 노예로 삼았다."
rows["211:1841926293"]="우린 여기 온갖 똥구리들로 둘러싸여 있지만 적어도 우리는 열린 바다를 넘어서고 있습니다.$B$B하지만 그건 날려버린 것을 볼 수 없어"
rows["211:1951263118"]="스톰윈드 시민들과 손님들 우리 도시가 공격당하고 있습니다! 무기를 들고 우리 수도를 방어하세요! 전투의 부르짖음을 대답하기를 원하지 않는다면 모래 봉투를 잡고 홍수를 막기 위해 거리를 정렬하십시오."
rows["211:2059964107"]="마취된 작물은 잡초가 들어오고 있습니다!$B$B토양의 잔디에 거친 잡초를 대하는 것처럼 그들을 대할 수 있어"
rows["211:254903704"]="아직 배울 거 많아요. 내가 할 수 있다면 다 가르쳐 주겠는데, 저도 계속 배우고 있어요. 왜 트릭시 퀴크스위치와 아이언포지에 얘기하지 않는가?"
rows["211:379116299"]="이쪽은 좀 조심해$b$b이제 북서쪽으로 드라크 아탈의 통로로 가서 그 기둥에 있는 에릭시어를 마셔보세요. $b$b다시 만나면 더 많은 정보를 알려드리겠습니다"
rows["211:38566786"]="네가 내게 도움을 주었으니 내가 이 땅과 그 곳의 모든 것을 알고 있는 것을 네게 알려 주리라 나의 지식이 크지 아니하나"
rows["211:481625119"]="안녕하세요! 우리는 해상에서 그 쓸모없는 해적들에 의해 봉쇄되고 있습니다! 당신은 그들에게 몇 개의 폭탄을 던지면서 우리를 도울 수 있다고 생각합니까?!$B$B훔친 제펠린이 왔어, 배가 떠나는 전에 배에 뛰어들!"
rows["211:482385789"]="전 어둠을 환영했습니다. 밤의 자매였기 때문입니다. 지금은 밤이 낮에도 계속 어두워지고 숲이 식량을 요구합니다. 우리가 빨리 행동하지 않으면, 이 확산적인 재앙은 세계를 덮을 것입니다."
rows["211:507762073"]="- 갈 필요가 있어 오그리마 라저힐에서 북쪽으로 가는 길을 따라가면 캐니온을 통과해"
rows["211:648129634"]="영세계를 여행하는 것은 |cFFFF0000|Hspell:117723|h[Frail 영혼]|h|r 만약 당신이 다시 영혼 세계로 여행하려고 한다면,"
rows["211:684457964"]="진정한 전문가는 자신의 한계를 알고 있고, 당신의 능력이 내보다 더 뛰어나다는 것을 인정하는 것을 부끄러워하지 않습니다. 아조라 타워의 키타 파이어윈드를 방문해 보시기 바랍니다. 그녀는 잘 알려져 있고, 좋은 이유도 있습니다."
rows["211:75128580"]="제 첫 번째 바다 모험은 더 평화롭고 깨달음을 주는 것 같았어요. 자연과 함께하는 것 같았죠.$B$B자연스러운 것은 거의 없습니다. 우리 주변의 요소들은 복수를 요구합니다."
rows["212:1053061355"]="우리 수석요리사가 식사를 준비할 때까지 이 문제는 잠시 접어 두는 게 어떻겠소? 이런 말해서 좀 미안한데 당신 화가 난 것 같군. 기분이 좀 나아지면 회의를 계속하도록 합시다."
rows["212:1098314793"]="진주 장군인 어들러에게 말해주세요. 그는 장관된 왕좌를 사용하여 진주 발전률을 지속적으로 높일 것입니다! $B$B|TInterface\\Icons\\INV_STAFF_2H_PANDARIATRADESKILL_C_05.blp:64|t"
rows["212:1255573149"]="친절한 얼굴을 보는 게 좋지만 요약사 조하안은 뭐라도 원하지 않는 이상 얘기하지 않습니다. 그는 무덤에서 너무 오래 지났어요. 언젠가 그런 사람이 될 것 같아서, 무서운 것 같아서, 그 때엔 신경 쓰지 않을지도 모릅니다."
rows["212:1318862247"]="우리 군 의 병사 들 은 적 들 에게 철 을 씌우지만, 그러한 공격 의 실제 효과 는 의심 할 여지 가 있다. 가장 좋은 경우 이기는 것 이다."
rows["212:1326705119"]="가건 을 사용 하는 방법 을 아직 배우지 않은 사람 들 은 창조 와 적용 의 기본 을 알려 주기에 기쁘다. 생명 과 죽음 의 차이 는 종종 제대로 가건 을 하는 상처 로 줄 수 있다."
rows["212:1349668007"]="저는 리더십은 힘에 관한 것이라고 생각했었는데 지금은 좀 더 명확하게 볼 수 있습니다. 조금은 주는 것, 조금은 받는 것, 사람들을 묶는 것, 막대기가 쉽게 깨지지 않는 것"
rows["212:136846079"]="고마워요 더 오래 견딜 수 없었어요\010아쉽게도, 계속할 수 있는 조건은 없어요.\010만약 우리가 가진 그린스톤 브루가 훔쳐지지 않았다면..."
rows["212:1619538594"]="마지막 순위는 여기 있습니다!$B$B ⁇ : $2200w$B$B카에른: $2201w$B$B실바나스: $2202w$B$B전체 호드: $2207w$B$B$B볼바르: $2203w$B$B마그니: $2204w$B$B타이란데: $2205w$B$B전체 얼라이언스: $2206w$B$B호드와 얼라이언스의 투표는 전체 투표로 같았습니다!"
rows["212:1626578854"]="에스코다르 라이더들은 막대한 강력한 전투가 있어 가까운 거리에서 무서운 놈들이죠$B$B방어력을 파괴하는 추진력 범위를 벗어나서 보호대를 해체해 보전부리기를 이용해서"
rows["212:1642772773"]="레벨 15에서 첫 번째 재능을 선택할 것입니다.\010나중에 다른 재능들을 선택하기로 결정하면, 당신은 이전에 선택한 것을 다시 설정할 수 있습니다.\010이렇게 하면 추가로 더 비싸게 될 것입니다."
rows["212:1671709452"]="에테레르 기술자 세 명이 동부 드래그를 따라 오그리마에 창업했습니다.\010이상한 기계와 보라색 조명을 찾아봐\010그들이 원하는 서비스를 제공합니다."
rows["212:1681786192"]="모든 물고기와 다른 모든 것들이 실리투스로 가는 길이고, 하루도 안 돼야 합니다. 그 후에 누군가가 이 둥지를 울려보며"
rows["212:1704632548"]="첫 번째 도움은 항상 좋은 기술입니다. 전투 중에 많은 시간을 내 피부를 구했습니다. 정신 상승에서 영적 치유를 방문하십시오. 판드 스톤베인더는 당신의 피부를 구하기 위해 알아야 할 모든 것을 가르쳐 줄 수 있습니다."
rows["212:1746792834"]="\"이종들이 우리 집 에 공격 을 당했을 때 모든 것 은 사라졌다고 생각 했 다. 하지만, 늙은 수도사들은 \"하나가 문을 닫으면 다른 하나는 열린다\"고 말 하는 데는 옳다.$b$b그런 것 같았어요. 그들의 가르침에 너무 큰 게 아니었어요."
rows["212:1948864444"]="하지만 우리가 무슨 일이 일어나고 있는지 확실하지 않죠. 우리는 이 종파를 붙잡고 그들의 침묵을 강요해야 할까요?"
rows["212:2069082991"]="블랙록의 암흑 아이언들은 나랑 아무 상관이 없어 토리움 포인트도 안 돼$b$b내가 독립적이면서 그렇게 좋아하니까, 물론, 적절한 가격에,"
rows["212:2075124945"]="난 프로스트울프 클랜의 모집을 담당하고 프로스트울프의 군인으로서$B$B이 추운 현장에서 존엄과 존경심을 얻습니다."
rows["212:2085646781"]="<고르무난의 목소리는 깊은 곳에서 울고 귀가 아프고 발 아래의 땅에서도 울고 있습니다.>$B$B안녕,  ⁇ 아$B$B당신같은 사람들은 항상 뛰고 멈추지 않고 돌아다니고 있어"
rows["212:2088648904"]="우리는 그의 맹세한 종들이 그의 명령을 따르고 그의 철규칙을 집행합니다. 그의 불타는 영역의 에너지로부터 분리되어, 라그나로스는 그의 진정한 자아의 그림자입니다. 그러나 그는 당신의 끝이 될 수 있는 충분한 힘을 가지고 있습니다.      \010"
rows["212:210384443"]="전투 후 내 상처를 치유한 판다렌의 빗물 파는 사람이 없었다면 제드 숲에서 죽었을 것이다.$b$b이 판다레인은 좋은 사람들이고, 얼라이언스의 지배로부터 우리의 보호를 받을 자격이 있습니다."
rows["212:226295606"]="나는 수많은 제국의 흥망을 지켜보았다... 모든 종의 발생과 멸종을 목격했다... 아무리 강산이 바뀌어도, 필멸의 존재들은 항상 멍청했지. 너희가 여기 나타난 게 그 증거다."
rows["212:253511802"]="그랩햄러는 내가 뭘 해야 할지 알고 난 항구를 건너게 하고 싶어$B$B내 헬리콥터 중 하나를 자동 조종사에 올릴게요$B$B내 보호소에서 있을 거야"
rows["212:338305771"]="그 동상이 가진 다른 특징들과 비교해, 어깨는 매우 매력적 으로 보입니다.$b$b어쩌면 좋은 자연의 종일지도 모릅니다. 아니면 그렇지 않다면, 아마도 멸종한 것일지도 모릅니다.$b$b희망이 있을 수 있습니다."
rows["212:381964286"]="톱니멧돼지 농장에 가 본 적 있나? 잡을 수 있을 만큼 돼지가 자랐을 때... 바로 그 소리 말일세. 돼지 멱 따는 그 소리... 엄청나게 큰 소리로 울려 퍼지는 걸세. 우리같이 나이 든 전사들에게는 정말이지 힘든 시기였지."
rows["212:444785859"]=" ⁇ 도파인은 벽이 필요하기 때문에 여기 있지 않습니다. 그 ⁇ 들은 그 ⁇ 에게 많은 재산을 빚어집니다. 만약 그 ⁇ 가 그 ⁇ 을 방어할 수 없다면 그 ⁇ 은 위험에 처해 있고, 그 ⁇ 은 지금 어느 때보다 더 필요합니다."
rows["212:514079858"]="저  ⁇ 은 함정이 보이시죠? 오그레들은 어떻게 고칠 수 있는지 알아내기엔 너무 멍청해요. 분명히 조금만 조작이 필요하죠!"
rows["212:538922314"]="그렇습니다. 창조주들은 기생체를 제압한 다음, 숙주 안에 그대로 남겨 두었습니다. 또한 의지의 용광로를 비롯한 여러 시스템으로 새 토석인을 만드는 작업을 시작했습니다. 보호 대책이 마련되었으며, 수호자가 지정되었습니다."
rows["212:556017930"]="<나린은  ⁇ 에 열린 봉투를 들고 있다.>$B$B뭐야?$B$B내가 옳았어?$B$B만약 당신이 여기 와서 재학에 대한 기술을 배우려고 한다면, 저 책으로...$B$B<나라인은 \"두미들을 위한 예언\"을 지적한다."
rows["212:563543292"]="우리의 폭풍 까마귀는 이 고밀도 공기 속에서 비행하기 위해 고군분투하지만 그 언덕에 있는 불어마뱀은 쉽게 날아가기 마련입니다.$B$B그들은 불의 모든 동물들과 같지만 그들의 모습은 아름다워"
rows["212:623162871"]="흠, 이상하군요... 여기서 갑자기 끝나 버리네요. 타나리스에서 청동용군단과 마주친 퀴라지 문서... 이 부분에서 내용이 많이 빠진 것 같은데... 정보를 더 찾아야 해요! 그들이 다시 한 번 칼림도어를 침공할 계획을 세우고 있는 것이 분명해요!"
rows["212:653770347"]="팔라딘, 당신은 약사의 조화나 그 같은 것을 먹었습니까? 언더시티아마 그들 중 한 명이 알지도 모릅니다."
rows["212:703980545"]="이제 우리 둘은 이웃이니까 솔직히 말해서 돼지 두 마리도 농장에서 안 있어서는 안 되겠네"
rows["212:729456901"]="내 능력은 너보다 더 낫다. 언더시티그는 당신을 더 훈련시킬 능력이 있고, 당신은 그의 사람들의 곤경에 직접 목격할 수 있습니다."
rows["212:752900474"]="난 죽었어$B$B왜 아직도 여기 있소? 내가 올라갈 수 있는 큰 사냥터도 없나요?$B$B내 임무는 먼저 완료해야 돼 이 세상을 떠나기 전에"
rows["212:80278483"]="테스트, 테스트 1, 2, 7내 말 들어봐 $p전 현장에서 스카우트 미터를 배치해서 Siege-o-Matic에 대한 데이터를 수집했습니다."
rows["213:1101359312"]="브레엔나 플린트크래그, 마법의 손이 있잖아  \010경북으로 가야해 아이언포지의 문에서 미스터리 홀까지"
rows["213:1140447492"]="만약 그게 충분히 미친 짓이 아니었더라면, 그들은 아이스크림 사업을 그만두고 모험가가 되기로 결정했을 겁니다. 그들은 곳곳을 여행하고 마침내 어떤 포털에 사라지게 됩니다."
rows["213:1215691240"]="갈반가르 대장 (Drek'Thar) 의 신뢰받는 도움으로 전투장의 남쪽 부분에서 있는 아이스블러드 가리소에서 호드군을 이끌고 있다.$B$B갈반가르 대장은 현재 얼음혈 군대에 있습니다."
rows["213:1251052312"]="그럼 텐뮬 파르마운틴은 당신이 방문해야 할 사람이야. 그는 다른 누구도 못지않은 트릭을 가르쳐 줄 것입니다.  \010아이언포지의 문에서 남쪽으로 가서 그를 찾으세요."
rows["213:135680571"]="공원?$B$B큰 용인 죽음의 날개가 스톰윈드를 날아다니며 파괴했습니다.$B$B솔직히 왜 모든 것을 정평하지 않았는지 모르겠지만, 우리는 모두 빛에게 감사합니다."
rows["213:1545203282"]="카드가 님을 다시 찾아가십시오. 샤타르를 섬기려면 알도르 사제회 또는 점술가 길드 중 한 편과 동맹을 맺어야 한다는 사실을 기억하십시오. 참고로, 둘 중 한 편과 뜻을 함께하기로 결정하면 다른 편은 적이 될 겁니다."
rows["213:1608826484"]="똑똑히 들어, 순찰대원 발란나! 원정대 거주지로 돌아가면 네 행동을 전부 따져 물을 거야! 이번 피해는 전적으로 네 책임이고, 대장도 분명 내 말에 동의할 거야."
rows["213:1672915079"]="넌 잘 키운 바락 토롤 산양 양 양 양의 왕권을 잡기 전까지는 똥도 먹지 못해"
rows["213:1741192161"]="드렉타르는 얼스트울프 클랜의 군사적, 영적 지도자이며 얼스트울프 킵에서 형제들을 이끌고 있습니다.$B$B만약 그가 패배한다면 알테락의 호드 세력은 붕괴될 것입니다.$B$B드렉 타르가 죽었어"
rows["213:1799237576"]="많은 유물들이 여기 놓여있으며, 겉으로 보기에 버려져 있다. 대부분 가로쉬가 영원 꽃의 계곡에서 발굴한 장소에서 온 것 같다. 그가 찾으려 하는 것은 무엇이든, 그 유물들은 잊혀진 유물 중 하나인 것 같지 않다."
rows["213:184840449"]="다음으로 낙스라마스 죽음의 기사단 전당에 대해 설명해 주지. 이 타락한 전당에서는 훌륭한 우리 전사들이 타락하고 변질되어 스컬지의 전사로 다시 태어나, 밤낮으로 그들이 기술을 연마하는 소리가 울려 퍼진다고 한다."
rows["213:1850245409"]="오래 전에 여기 왔어요 저주받은 형제들을 연구하기 위해 그들의 고통을 치료하는 방법을 찾고$B$B마그투르는 날 환영했고, 여기 살고 있어 가장 친한 친구가 됐어요.$B$B그리고 지금, 내 눈앞에서, 그는 죽어가고 있습니다..."
rows["213:1927733937"]="이 장치의 다양한 메커니즘을 어떻게 작동해야 할지 전혀 모릅니다. 하지만 여러분은 익숙한 느낌으로 가득 차 있습니다.$B$B그냥 그냥 그냥 가만히 두면 좋을 것 같아요"
rows["213:1929546989"]="만약 언더라이트 광석이 이렇게 적시에 전달되지 않았다면 우리의 연구는 실패했을 것입니다.$B$B샤타리아가 다시 머리를 보여준 때까지 기다려줘요"
rows["213:324504196"]="아무도 실제로 Darkmoon 카드를 만든 사람이나 그들의 진정한 목적은 무엇인지 모릅니다. 하지만 저는 그들이 곳곳에서 발견되었음을 말할 수 있습니다. 아제로스보통 악당이 그들의 비밀을 풀려고 하는 손에"
rows["213:338906473"]="살테릴 경이 매일 저녁 파티를 주는데 정말 다행이야 특히 남쪽에서 일어나는 모든 악행이"
rows["213:444430352"]="저는 여러분 엔지니어들에게 금을 너무 많이 지불하지 않습니다. \"아니요\" 또는 \"내용할 수 없습니다\"라는 단어를 들을 수 있도록 말이죠. 그 장벽을 내려놓으세요. 아니면 여러분은 X-17에서 에너지 재배 라인을 작업하는 것을 발견하게 될 것입니다."
rows["213:450220913"]="에메랄드 서클은 펠우드의 상처받은 땅을 치유하려고 노력합니다. 그 땅은 그것을 손상시킨 것 자체로 이름이 붙었음에도 불구하고, 우리는 언젠가 이 땅에서 부패를 근절시킬 수 있기를 바랍니다."
rows["213:457591732"]="아가씨, 마음을 열어봐. 이 나무가 영양을 주는 땅에서 찢어졌을 때 겪었던 고통과 고통을 느끼지 못해?"
rows["213:541908913"]="이 책은 용들이 더 강력한 용인인 죽음의 날개에 맞서 연합하는 이야기를 담고 있습니다.\010"
rows["213:585423301"]="아웃랜드의 악마적 존재는 우리가 구 세계에서 본 것보다 훨씬 강력합니다.$B$B큰 힘이 오는 사람은 그 힘을 배워서 그것을 극복하는 법을 배우게 될 것이다."
rows["213:659496755"]="우리는 먼 아즈하라로 항해할 것입니다. 거기서 새로운 무역 제국을 건설할 것입니다. 스팀위들 카르텔을 파괴할 것입니다. 그리고 그 먼 나라의 산에 나의 모습을 조각하겠습니다. 모든 사람들이 나에게 추모를 드리겠습니다."
rows["213:742513993"]="마리엘 트루하르트 부스티카는 대회의 필요를 충족시켜주기를 요청했습니다. 챔피언으로서의 권리를 얻은 사람들이 우리의 눈에 자신을 증명한 사람들은 이러한 의무에 도움을 요청합니다."
rows["213:822809631"]="믿을 수 없는 사이트를 찾았어요!$b$b이 지역은 고대 건축의 붐으로 울려 퍼져 있습니다.$b$b낮이 늦지 않았다면, 저는 즉시 방을 조사했을 것입니다!$b$b오늘 밤 잠을 자는 것은 힘든 일이 될 거야"
rows["213:859247583"]="어른들은 항상 우리에게 제이드 마녀가 숲속의 노인여성이라고 말했지만 남편이 죽었기에 슬퍼했지$b$b난 어른들에게 말하지 않았어 난 곤경에 빠지길 원하지 않아"
rows["214:1019764620"]="레뮬루스의 성당은 무롱라드에서 있는 센라리온 서클에서 우리에게 신성한 장소입니다. 그래서 방문객에게 적합한 방식으로 행동하세요.$B$B내 시미타를 묻지 않으려는 방문자"
rows["214:1055948357"]="아웃랜드로 이동하고? 네더스톰의 지역에 있는 비스트론 핀치위슬을 방문하십시오 52. 스팀위들 전투 회로의 공식 아레나 판매자로서, 충분한 아레나 포인트를 가진 사람들에게 판매 할 수있는 모든 종류의 놀라운 아이템이 있습니다."
rows["214:1168594774"]="순찰자 발란나, 원정순찰대 초소로 돌아가면 그대의 행동에 대해 상세하게 보고하겠습니다! 우리 패배는 전적으로 그대의 책임이며 순찰대장님도 저와 같은 생각일 것입니다."
rows["214:1202099328"]="<이 록풀의 아기 무르록들은 여기 버려진 것 같네요. 당신은 그들이 곤경에 처해 있다고 의심하고 있습니다. 그리고 네프톨은 그들이 나가로부터 탈출할 기회를 가진 바다로 데려오기를 원할 것입니다.>"
rows["214:1210607320"]="안젤라가 주면$B$B죽음 이후, 여섯은 최고의 행동으로 막대기를 마법의 불가침한 장벽 뒤에 봉쇄하고 감시자를 임명하기로 결정했습니다. 수호자 직원들 중... 내가 그 감시자가 될 거야"
rows["214:1388817873"]="<마개 달걀을 둘러싸고 있는 둥지에 위축 조각들을 넣으면, 그 덩어리가  ⁇ 기 시작합니다. 몇 분 후 거친 껍데기에 균열이 나타나고, 검은 마 Dragon가 어미를 위해  ⁇ 기 시작합니다.>"
rows["214:1420900677"]="안녕하세요, 무슨 일이죠?$B$B이것은 아웃랜드의 자녀들을 위한 고아집입니다. 부모를 잃은 사람들이고 그들을 돌볼 수 있는 다른 사람이 없습니다.$B$B입양을 고려하고 있기 때문에 여기 온거 아닐까요?"
rows["214:1511027933"]="드래곤플라이트에서의 오해로 인해 우리는 이 망할 성으로 시설을 옮길 수밖에 없었다$B$B하지만, 우리는 이제 다양한 새롭고 아름다운 제품들을 개발할 충분한 시간과 공간을 가지고 있습니다."
rows["214:1591384482"]="이 방이 있는 태블릿을 봤어요. 이것은 빛의 보물입니다!"
rows["214:1769281358"]="그래, 내가 어서나 어서 만나게 될지도 몰라요 하지만 난 그냥 누구에게도 대담하지 않고 먼저 필요한 걸 얻어야 해요"
rows["214:1771078130"]="울팡은 우는 소리, 냄새를 맡고 있어 그가 말하는 것을 이해할 수 있어$B$B북부의 이상한 백악마인 가르왈이 제 무리를 빼앗아갔어요"
rows["214:1805804766"]="네 잿빛혓바닥 결사단을 폭풍우 요새로 보내서 캘타스 놈이 애지중지하는 생물을 없애라. 알라르라는 불사조 말이다! 너도 놈의 편이 아니라는 걸 확인해야겠다. 배신할 생각은 꿈에도 말아라."
rows["214:1814652363"]="이쪽은 좀 조심해$b$b이제 북쪽으로 Zeb'Halak로 가서 기둥 근처에서 마시세요!$b$b예언자의 눈을 먼저 지구르타의 머리에서 가져가라"
rows["214:21392929"]="원수들... 검을 든 형제자매들이여. 수천 군대보다 너희와 나란히 싸우는 편이 낫다. 우리는 사자다! 저 악마들과 어둠의 문 너머에 무엇이 기다리는지 아나? 불멸이다! 쟁취해라! "
rows["214:443087867"]="잘됐어, 말푸리온은 불지방에 진입할 거야, 우린 거기서 그를 처리할 거야$b$b<레야라의 눈은 빛난다.>$b$b하지만 타우렌 아크 드루이드는 그렇게 운이 좋지 않을 것입니다."
rows["214:506689272"]="학생들은 양처럼 조금이나마 유용하고 심지어 사랑스러운 사람들이죠. 여러분이 그들을 지도하고, 주의를 기울이면 말이죠.$B$B한 분 동안 그들을 혼자 두면 절벽에서 떨어지거나  ⁇ 은 강에 익사하게 됩니다."
rows["214:547994248"]="골드엔드래프트와 결혼하는 웬더브루?$b$b적어도 내 아들을 행복하게 해줬어 $p."
rows["214:552502674"]="이 릴랜드는 하루 종일 무역 구역 밖에서 항구에 앉아 낚시만 하고 낚시하는 거야 낚시하는 동안 잘 할 수 있었으면 좋겠어"
rows["214:563048483"]="이론적으로 요그사론이라는 존재 내부에는 사로나이트를 액체로 변환하는 강력한 산성 물질이 수용되어 있습니다. 티탄이 만든 합금을 그 안에 담그면 금속 조직을 재결합할 수 있습니다."
rows["214:615955094"]="<고르무난은 좋은 성향의 콧물을 내린다.>$B$B해어럼, 내 개인적인 습관을 이렇게 심도 있게 조사한 적이 없어. 당신 같은 사람들은 항상 놀라게 해줍니다."
rows["214:679046376"]="마음을 굳게 먹어라, 용사여. 그대가 왜 여기로 왔는지, 무얼 찾고 있는지 알고 있다. 에라니쿠스는 절대 홀 조각을 포기하지 않을 것이다. 그는 타락했다... 그대가 파괴하려는 바로 그 힘에 의해서."
rows["214:688644634"]="일단 아훈이 완전히 준비되면 갈퀴송곳니 저수지에서 의식을 벌여 구해낼 거예요. 그러면 불의 군주와 서리 군주 사이에 충돌이 일어나 이 세계를 뿌리째 갈라놓겠지요. 저희의 궁극적인 목표가 마침내 눈앞에 있어요..."
rows["214:756644084"]="<마개 달걀을 둘러싼 둥지에 위축 조각들을 넣으면, 그 새들이  ⁇ 기 시작합니다. 몇 분 후 막강한 상자 안에 균열이 나타나고, 검은 마개는 아버지에게 애를 하고 나서서 나오게 됩니다.>"
rows["215:1109679540"]="요리 능력을 키우려는 게 관심 있는 거요?$B$B아이언파와 얘기해봐요, 네 바람의 골짜기 하프힐 시장에서 찾을 수 있어요$B$B지도에 위치 표시를 해볼게요"
rows["215:1131235506"]="그럼 브론즈 케틀에 가서 그레이트 포지의 북동쪽에 있는 데릴 리크누스슨이 당신에게 생명을 되찾을 수 있는 훌륭한 요리를 가르쳐 줄 것입니다."
rows["215:1143402353"]="소그리가 우리 원래의 지향에서 멀어졌는데, 그는 우리를 빨리 공격할 수 있다고 생각했어요.$B$B솔직히, 우리 모두 그가 시도한 것에 기뻐요. 우리 중 누구도 \"일간 일\"이 쉬운 사람이 아닙니다."
rows["215:1271948303"]="우리가 이상한 사람들이죠. 판다레네들이 이 벽에 사는 건 별로 없습니다.$b$b한마디로, 우리는 맥주 만들죠. 그냥 어떤 맥주를 만드는 게 아니라..."
rows["215:145396077"]="음식, 이제 내가 내 매개관들을  ⁇  수 있는 주제가 있습니다! $2095w 이 중 $2096w 얇은 늑대 스테이크, $2102w 이 중 $2103w 얼룩진 노란색 꼬리, 그리고 $2105w 이 중 $2106w 얼음 위에 굽은 살몬을 보관하고"
rows["215:1466155531"]="역병지대에서 켈투자드는 은빛 여명회의 요원들에게 또다시 패하고 말았지. 하지만 그의 성물함은 가짜 결사단 요원에게 넘어가 버렸다. 우린 아직도 누가, 무슨 목적으로 그 성물함을 훔쳐갔는지 밝혀내지 못했다."
rows["215:147594752"]="와이트레어치 포스트는 제가 의도하지 않은 정류가 되었는데, 제 고객들은 제가 상품을 배달할 수 있도록 기대하고 있고, 저는 모든 지연과 함께 제가 시간 내에 도착할 수 있을지 궁금해하기 시작했습니다."
rows["215:1479418273"]="항구만 점령했고 이 배는 좋은 보너스입니다.$B$B그 동안, 저는 그린길 해안의 나가 파멸을 감시하도록 지시되었습니다.$B$B도와줄 수 있을거니?"
rows["215:1663525175"]="[영화 촬영을 기다리고 있다] 지는 아이사에게 상처를 입히지 않으려 하고, 싸우고 소리치고,  ⁇ 진 수가 회복될까봐 두려워하고, 지가 그녀를 상의하지 않고 그렇게 급하게 행동할 것이라고 화가 났어요."
rows["215:1730137654"]="형제들아 준비하라,  ⁇ 을 따라 방어할 곳을 세우라, 차량들을 지나게 하라. 우리는 흙에서 태어났으며 흙으로 돌아가리라. 창조자의 힘이 너희 안에 깊이 불어오게 하소서."
rows["215:1822033898"]="매 세대마다, 마티드는 뱀의 척추 벽을 무대적으로 몰아내고 많은 판다레인을 죽이고 있습니다. 그래서 우리는 그들의 숫자를 수 배로 죽입니다. 그럼에도 불구하고, 매 세대는 다시 한번 공격합니다. 왜 그들은 이것을합니까?"
rows["215:1865090500"]="남동쪽 크라사랑 야생지대의 어너스 바프에는 파다리아의 이쪽에서 가장 열렬한 낚시꾼이 살고 있습니다.$B$B만약 당신이 바다에서 하루를 보내는 보상을 좋아한다면,"
rows["215:1876808561"]="켄-켄은 그의 시대에 몇 명의 판다렌을 만났고, 그는 당신에게 어떤 것을 말해줍니다.$B$B여기 슬픈, 모피 도피들이 곳곳에  ⁇ 돌고 있어요$B$B노래와 춤은 어디 있어?$B$B보즈 어디 있어?"
rows["215:1883454045"]="왜 이런 짓을 하는 거야? 진주? 전쟁? 고대 네스피라가 나가들이 생각하는 것보다 훨씬 더 강력해."
rows["215:208704087"]="전력으로  ⁇ 버 드레크는 시간적 균열을 수행할 수 있어 적을 둘러싸고 압축된 시간의 거품을 생성한다. 거품을 통과하는 마술은 두 배의 피해를 발생시키고 목표에 충격을 줄 수 있다."
rows["215:2127526482"]="다리아나는 약속도 하고 있지만, 너무 많은 에너지가 있어 가만히 서서 듣기 힘들다. 그녀의 힘과 민첩성, 나는 그녀가 전투에 부름을 받기까지는 오래 걸릴지 모른다고 두려워한다. 우리는 빨리 그녀를 가르쳐야 한다."
rows["215:419965943"]="호드의 은행과 보물을 지키는 것은 철의 구석에서 동전을 분배하고 상품을 거래하는 것보다 훨씬 더 만족스러운 일입니다.$B$B ⁇ 을 밀어내는 괴물들 중 한 명이나 자리를 교환하지 않을 거예요"
rows["215:43821697"]="호수에 충돌하지 못했다고 해도 좋겠지만, 호수에는 4개의 호수들이 있습니다."
rows["215:6911109"]="사령관들이여, 함께 칼을 든 형제자매들이여, 수천 명의 병사를 보내기보다 내가 몸소 그대들과 함께 싸우겠다. 우리는 전장의 호랑이들이다! 저 악마들과 어둠의 문 너머 무엇이 기다리고 있는지 그대들도 알 것이다. 영생이 우리 것이다!"
rows["215:736590887"]="다라란의 유일한 강좌 훈련자들은 마법사들이야 다른 사람들을 위해$B$B그들은 달라란의 얼라이언스 및 호드 방에서 발견 될 수 있습니다: 은 엔클라브 및 선리어버의 성당."
rows["215:941083764"]="그래, 항상 클라이드 켈런이 브릴 동쪽 브라이트워터 호수에서 낚시를 하고 있어 마스크를 입은 정신병자 조심해"
rows["216:1011584078"]="당신은 당신의 이익을 위해 얼라이언스 군대에 필요한 보병과 추적자, 그리고 금으로 지불하는 것은 바로 왕의 재화로부터 전달될 것입니다."
rows["216:1469773444"]="조상님들은 적을 혼란에 빠트리는 방법을 알고 계셨어요. 그 지혜를 사용한다면 스컬지의 약점을 찾거나 적의 지휘관을 쓰러트릴 수 있을 겁니다. 지도자 없는 스컬지는 곧 우리 용사들 앞에 무너져 내리겠지요."
rows["216:1549903975"]="켈투자드는 무시무시한 리치다. 리치 왕에게 무조건 복종하는 그는 살아있을 적에도 강력한 강령술사로 이름을 떨쳤지만, 죽어서 다시 태어난 이후로는 강령술에서 그를 따라올 자가 없게 되었지. 켈투자드는 리치 왕의 가장 충성스러운 신하라고 한다."
rows["216:1673460309"]="뭐라고, 펜구스 녀석이 나보고 놀의 애인이라고 했다고?! 어서 포로들 왕에게 데려가. 녀석들 위험하다는 걸 보여주려고 무기를 들린 채 데려오다니 제법 영리하군. 난 가서 펜구스 녀석 혼내줘야겠다. 그때도 계속 그딴 소리를 지껄이나 보자! 흥!"
rows["216:1818890320"]="말도 안 되는 소리! 고드프리, 내가 무슨 바보인 줄 아는가? 스컬지들의 선전 문구를 빛을 섬기는 자에게 늘어놓다니! 지금 말하지 않으면 하인들을 시켜 이가 들끓는 개처럼 성수로 목욕을 시켜주마!"
rows["216:1839650207"]="태양이 이미 뜨고 있냐? 밤에는 결코 충분한 시간도 없다! 잘, 세일린은 당신을 잘 돌볼 것입니다. 당신은 그녀를 찾을 수 있습니다 다르나서스."
rows["216:1848033234"]="샤도-판은 영원한 경비를 하고 있습니다. 오래 전에 지구에 봉인된 어두운 샤 에너지들을 감시합니다.$B$B불행히도, 샤는 감옥에서 탈출했고 이제 우리는 그들을 다시 한번 물리쳐야 합니다."
rows["216:1854170807"]="말씀 잘 들었소, 마브렌! 하지만 최종 결정은 내 권한이지. 당신의 지원은 고맙지만 전선에 나간 대다수는 우리 블러드 엘프요. 그릇된 판단으로 그들의 목숨을 헛되이 버릴 수는 없소!"
rows["216:19223127"]="아! 영웅들... 아주 끈질긴 족속이지. 바로 이곳에서 너희 동료가 내게 도전했다가 그 대가를 치렀다. 이제 녀석은 날 섬기지."
rows["216:1978964436"]="넌 아무 이유 없이 산을 걷어다니는 거야?$b$b엄마가 다리가 바쁘고 뇌가 뒤집어졌다고 하지만, 어쩌면 그녀가 모든 것을 뒤집은 것 같군."
rows["216:205900996"]="주인님! 오해하시는 겁니다. 정보에 의하면 주인님을 배신하려는 자가 내부에 있습니다. 바로 그 오만한 캘타스 놈 말입니다! 놈은 킬제덴과 손을 잡고 아웃랜드의 권좌에서 주인님을 몰아내려고 합니다!"
rows["216:2061233367"]="자, 한 번도 본 적이 없다면 잘 봐 두라고. 전장 안팎에서 모두 아주 유용한 녀석이니까 말이야. 다음은 남성들이라면 모두 기대하고 있을 서큐버스를 소환해 보지."
rows["216:247726502"]="잠깐, 뭔가 방금 나왔어봐요. 네, 여기 이 종이 위에요. 당신은 남동쪽으로 아저렐로드 광산으로 가서 케이튼 대장에게 보고해야 합니다. 동남은 그쪽입니다."
rows["216:268752791"]="내가 지금 보기에, 헤드라인들은 \"아르헨트 십자군 영웅이 치명적인 증기 탱크 사고로 사망했다\""
rows["216:415705368"]="폭풍 카드의 덱을 완성할 수 있다면 더 큰 분노의 암흑달 카드로 보상이 될 것입니다. 이것은 당신이 한 번 달성하기 전까지 마법이나 물리적 공격으로 중요한 타격을 받을 확률을 높일 것입니다."
rows["216:471982338"]="이 룬스톤은 \"생명의 비단\"이라고 합니다. 타이탄들이 새로운 생물들을 창조할 수 있는 곳이죠. 오, 물론 - 영원한 꽃의 계곡!"
rows["216:473758422"]="이제 가서 배운 것을 사용해봐요. 만약 당신이 펠의 에너지를 제거하고, 혹은 카너타드의 에너지를 다시 흡수하기를 원한다면, 나와 이야기해 주세요."
rows["216:603269352"]="또 흥미로운 내용이 있군요. 피로 얼룩진 전투와 까마귀 신의 몰락에 대한 설명이 끝나고 예언이 나와요. 내용인즉슨, 안주가 자신의 재림을 저지하려는 적들의 꿈속에 나타나 괴롭힐 거라네요."
rows["216:740485691"]="내가 방금 새로운 차원 임플로더를 완성했는데, 그 차원 임플로더는 내가 꿈꾸는 괴짜 괴짜보다 더 부유해 줄 거야 \010"
rows["216:780940611"]="우리는 모구에 의해 창조되었습니다. 그것을 믿지 않을 이유가 없습니다. 그것을 부정하는 사람은 무지, 또는 환상 속에서 살고 있습니다.$b$b난 악마사우로 변명하기를 거부한다 내가 누군지 알고 있어 내 힘이 어디서 왔는지"
rows["216:961634999"]="사실 저는 전통적인 약물을 선호합니다. 양수, 벌레, 뼈가루, 그런 것들이죠. 각각 그 자체로요."
rows["217:1009157897"]="세진 라이더들은 그들의 민첩함과 무선에 의존합니다.$B$B그들은 당신의 충격을 피하기 위해 빠르고 현명한, 그래서 가까운 범위의  ⁇ 스 및 때때로 방패-브레이커를 혼합하여 그들을 물리치도록 시도하십시오."
rows["217:1049317848"]="온 기지에 공포심이 가득한 걸 느낄 수 있다... 리치 왕의 군대가 스톰윈드를, 아이언포지를 점령한대도 제군들이 두려움을 느낄 것 같나? 아니! 그렇지 않을 것이다. 왜냐고? 그때쯤이면 이미 제군들은 시체가 되어 있을 테니까."
rows["217:1088347545"]="이 연래 목에 스모키우드 패서즈 로고와 \"메텐\"라는 이름이 붙여진 태그가 있습니다.$B$B메츠엔은 슬픔과 절망의 눈으로 당신을 바라보고 있습니다. 마치 보이지 않는 힘으로 연어들이 움직이지 못했던 것처럼요."
rows["217:1120668990"]="판다리아 사람들은 수천 년 전에 천황을 바라보고 오전 천국의 도전을 보게 되었습니다.\010당신은 영웅이 될 수 있는 신자들이 천상의 시험에 응할 것을 보고 계십니까?\010아니면 스스로 용기를 내어주었나?"
rows["217:118812534"]="만나면 부두술사 토르가시, 그의 조화와 매력은 효과가 없다고 말해줘!$B$B이 가짜 부두술사가 말해주는 것을 믿지 말아요!"
rows["217:1365603724"]="레지온, 악마, 그들이 당신을 사냥해?$B$B<코우런은 눈물을 지우죠>$B$B그래서 내가 가족들을 이리로 이끈지... 몇 년 전"
rows["217:1380171119"]="내가 포로야, 어떻게 생겼나? 이 드레네이 쓰레기는 태양 게이트를 빠져나오면서 저를 잡았어요. 그들은 우리의 포털 컨트롤러를 죽이고 게이트를 파괴했습니다."
rows["217:157818191"]="내가 내 슈퍼 적응형 변형형 변화선으로 당신을 바꿀 수 있는 모든 것들을 목록을 만들고 있습니다."
rows["217:1599248628"]="포털 카드 팩을 완성 할 수 있다면 더 큰 뒤틀린 황천의 암흑 달 카드가 주어질 것입니다. 이 카드는 때때로 당신의 영혼을 죽음 후 다시 몸으로 끌어내고 당신을 회복시킬 것입니다."
rows["217:1718232265"]="시간이 지나면, 우리는 다시 필사자들의 도움을 필요로 할 것입니다. 이 세상 모든 우리의 출생권이 파괴되었습니다."
rows["217:185852279"]="카엘타스와 그의 동료들은 망할 거야 우리가 노력한 모든 것이 사라졌지만, 그들은 우리가 반전을 하지 않을 것이라고 생각하는 바보들이야 이미 레이디 리아드린은 우리 계급에 새로운 힘을 찾고 있어"
rows["217:1883890708"]="아제로스에 걸쳐 있는 원자체를 묶는 연결고리가 크게 약화되었다. 그러한 원자체 중 하나인 아쿠멘타스는 더 이상 감옥에 있지 않습니다. 그는 사우스시 밴드에 큰 문제를 일으키고 있다고 들었습니다!"
rows["217:2034286133"]="벨가리스트라스는 진실을 말하고 있습니다. 시간이 지워지고 있습니다.\010내가 당신에게 청동기 비행에서 드레이크를 불러줄 힘을 줄 수 있어"
rows["217:2065259187"]="절 자유롭게 해주셔서 감사합니다, 필멸의 존재여. 명심하십시오. 푸른용군단은 그대의 존재를 경계하고 있습니다. 지금 이 순간에도 말리고스는 마력의 눈을 보호하려고 바로스 클라우드스트라이더와 고리 수호자들을 보내지요. 이에 맞서려면 저희 도움이 필요하리라 생각합니다."
rows["217:2077809764"]="나루가 나타나자 보렌살은 무릎을 꿇고 이렇게 말했습니다. \"나루여, 환영 속에서 당신을 보았습니다. 당신은 우리 종족이 살아남을 수 있는 유일한 희망입니다. 저와 부하들은 당신을 따르고자 이곳에 왔습니다.\""
rows["217:277219885"]="당신은 안전하고 '음악'하고 싶은 새로운 보물을 가지고 있습니까? 당신은 스톤맨틀과 함께 Vault에서 저장하고 싶어 할 것입니다. 당신은 아이언포지 입구에서 해마르 던진 북동에서만 Vault 찾을 것입니다."
rows["217:279047471"]="알터랙 밸리, 좋은 추억이 있어. <sigh> 나랑 같이 갈 수는 없지만 자랑스럽게 해줘! 아이언포지."
rows["217:289289380"]="파스트라이더들의 체크리스트와 다른 정보를 담은 여러 조각의 문장 가운데 하나는, 끔찍한 트롤의 그림입니다. 아마도 여러분이 본 가장 무서운 생물일지도 모릅니다."
rows["217:41099337"]="비참한 거미들이 하늘로부터 떨어지고 모든 것을 불태워버렸어\010이제 공장 전체가 불에 탔고, 주요 얼라이언스 세력은 언제든 기지에 진출할 것입니다!\010우린 그들을 막기 위한 숫자가 없어요"
rows["217:422228580"]="배탕, 항독물 등은 평야에서 살기 위해 필수적인 것들이다. 비라 영하프가 이 지식을 가르쳐 줄 수 있습니다."
rows["217:462083289"]="저는 제 형제가 순서에 가입하고 우리 관계의 영구적인 침해를 가하는 것에 반대합니다. 그는 자신과 주변 사람들에게 위험할 것입니다."
rows["217:566790164"]="호드 오르기마르 형제 자매 여러분, 공격 당하고 있습니다! 무기를 들고 우리 수도를 방어하세요! 침입자들에 대항하여 전쟁을 벌일 수 없다면, 우리의 도시를 강화하기 위해 바리케드를 설치하는 데 도움을 주세요!"
rows["217:616503977"]="우핑의 체력은 단순히 놀라운 것입니다. 그는 무기를 기술을 연습을 수 시간 동안 계속 지켜보고, 나는 연습 도미니에 대해 미안했다. 난 무장 전투에서 당신을 훈련하기에 더 적합한 사람을 생각할 수 없습니다."
rows["217:764667329"]="술에 대한 지식은 내보다 더 많지만 아직 배울 게 많다. 남동쪽으로 계단을 올라가 마쉬 박사님께 가세요. 그는 당신에게 진정한 고통을 가르쳐 줄 것입니다. 포세이큰 당신을 더 훈련시킬 것입니다."
rows["217:858054505"]="피부, 아름다운 피부. 내 안을 안고 있어. 내 피부가 그렇게 좋지 않다는 걸 알 수 있겠죠. 전 피부에 대해 걱정하던 것 같아서. 요즘은 걱정할 수 있는 피부는 거의 없습니다."
rows["218:126257690"]="지형 반지는 스톰윈드  ⁇ 의 북서쪽에 있는 작은 호수 섬에 세계 각 지역으로 포털을 설치했습니다.\010바라딘 경호원들 또한 그곳에 있으며, 톨 바라드에 교통을 제공하고 있습니다."
rows["218:1299805341"]="스노우드리프 마스터는 |cFFFF0000|Hspell:118961|h[Chasing]|h|r 당신을 잡으면 그는 그의 |cFFFF0000|Hspell:106352|h[Tornado Slam]|h|r 기술을 사용하게 될 것입니다! Chase Down 만료될 때까지 스노우드립 마스터에서 도망치십시오!"
rows["218:1331411268"]="만약 내가 하루하루 여기 갇혀 있지 않았다면, 당신 같은 사람들을 훈련시키는 데 필요한 숙련을 얻었을 것이다. 불행히도 그렇지 않다. 스톤탈론 산맥의 태양암 피난처에서 Hgarth에 가서 이야기 해봐."
rows["218:1370091250"]="보아, 우리가 이미 필요한 가죽을 모두 수집한 것 같네요. 그건 정말 빨리 지나갔어요."
rows["218:1568402691"]="내가 이 곳의 건축가이고, 마지막 설계를 결정한다. 만약 내 계획에 문제가 있다면, 하이 ⁇ 로드 포드링에게 불만을 제기할 수 있어.\010"
rows["218:1608840756"]="우리는 천문병입니다. 우리가 훈련받은 것은 이것입니다. 우리는 물러나지 않습니다. 우리는 항복하지 않습니다. 우리는 우리의 임무를 통과 할 것입니다. 심지어는 죽음이 의미합니다!"
rows["218:1970298667"]="짧은 칼의 미묘함과 두손의 거리의 뼈를 깨는 쪼개기력을 가르칠 수도 있고, 아니면 우리가 미친듯이 놀 수 있고 둘 다 가르쳐 줄 수도 있습니다."
rows["218:2050643323"]="은빛십자군과 칠흑의 기사단은 얼음왕관 성채 관문을 습격했고 스컬지에 대규모 공격을 퍼부으려 준비 중이다. 우리 임무는 좀 더 까다롭지만, 중요하기는 마찬가지다."
rows["218:2087518488"]="부티 베이 어업 대회에 오신 것을 환영합니다. 이 대회에서 매주 아제로스의 최고의 어업자들에게 상을 수여합니다.\010낚시 토너먼트가 시작되면 스트랑글스톤의 모든 낚시 노드에서 맛있는 물고기를 잡을 수 있습니다."
rows["218:265545383"]="모든 물고기와 다른 모든 것들이 실리투스로 가는 길이고, $2113w일 이내에 그곳에 도착해야 합니다. 그 후에 누군가가 이 콩을  ⁇ 는  ⁇ 은 모래의 왕자와 함께 전쟁을 시작해야 합니다."
rows["218:338881843"]="마을에 사는 이쁜 마을 사람들은 그들이 모든 일에 더 나은 헬멧을 만든다고 주장합니다. 제가 회의적인 반면, 헬멧은 해를 끼치지 않을 수 없습니다."
rows["218:391632837"]="혼란에 빠진 형제들아, 밤이 다가왔다. 죽음은 이 세상을 찢어 버렸으니"
rows["218:407031845"]="말싸움이 하고 싶나 보군. 그래. 지원 병력이 더 있으면 좋겠지. 하지만, 트롤을 상대로 무의미한 충돌이나 일삼고 있는 원정순찰대들을 데려오는 편이 더 빠를 텐데..."
rows["218:472986709"]="잘 봐라, 역병술사 노스이다. 살아 있는 자의 영혼을 뽑아내어 언데드라는 감옥에 가두는 방법을 창조한 장본인이지. 노스는 지금도 이 과정을 개량하고 있다고 한다."
rows["218:511821714"]="망할 거미, 끝없는 소리치는 박쥐, 그리고 그 망할 악마 짐승들은 모두 종의 사방에 거주하고 있어 더 이상 걷기가 안전하지 않습니다. 특히 큰 놈들이 숨기기기 시작하면"
rows["218:65656339"]="브랜은 지금 이 순간 태블릿을 보내고 있습니다. 탐험가들의 리그의 사전 보고서는 지진이 무슨 일이 일어나고 있는지 이해하는데 도움이 될 수 있다고 합니다."
rows["218:724829693"]="사랑하는 친구, 당신은 당신의 경호를 통해 그들을 존경합니다. 당신은 당신의 충성심에 굳건히 서 있습니다. 나는 한 순간도 의심하지 않습니다. 당신은 당신의 백성들을 위해 당신이 지탱하는 영웅들 중 어느 누구도만큼 큰 희생을 하지 않을 것입니다."
rows["218:781225862"]="안녕하세요, $p!$b$b전직 권력을 되찾기 전에 Thunder King을 직접 막는 기회가 있습니다.$b$b심지어는 방황하는 섬에서도 그의 증오스러운 이름은 기억되고 파다레네 어린이들이 두려워하는 번둥의 소리가 들려온다."
