rows["219:1202278290"]="우리 사업은 12세대 동안 지속되어 왔고, 그 후 수백 개의 신선하고 깨끗하고 냄새가 나가는 야크를 구부러주었습니다.$b$b홍수, 기근, 모가와 마주쳤어 이  ⁇ 돌들이 우리를 쫓아내면 난  ⁇ 골의 삼촌이 될 거야"
rows["219:1294318012"]="죽음의 날개의 미쳤다는 것은 그를 이겨내고, 우리는 붉은 용들이 이 기회를 이용해 그의 검은 드래곤들을 훔쳐갈 필요가 있습니다."
rows["219:1297477425"]="네 ⁇ 스 왕자로부터 아직 소식이 없습니다. 네더스토밍에서 클라이언트와의 분쟁에 대한 소문이 퍼지기 시작했습니다. 우리의 소다라미 후원자들은 파산에 대해 이야기합니다."
rows["219:1430522744"]="마리엘 트루하르트 부지사는 토너먼트를 관리하고 방어하도록 요청했습니다. 콜리세움이 완성된 후, 우리는 그 쓸모없는 은 계약의 저주자들과 함께 일하기를 원합니다."
rows["219:1627397187"]="나 더 이상 부드럽지 않고 겸손하지 않았다는 걸 두려워합니다. 나이와 수많은 전투는 내 피부와 영혼을 굳혔습니다. 아마도 이 때문에 카이른은 나를 태양 돌 퇴원소에 임명했습니다."
rows["219:1778513719"]="전쟁에 필요한 미트릴 바를 모두 가지고 있는 것 같지만 아직은 많은 사람들이 있어"
rows["219:1854114094"]="노스렌드에서 성공했음에도 불구하고, 우리는 단순히 도끼와 검으로 해결될 수 없는 심각한 문제들을 직면하고 있습니다. 지진은 모든 지역을 흔들고 있습니다. 원자재는 시골을 황폐화합니다. 우리 땅 아제로스이 고통으로 외치는 소리를 들을 수 있습니다."
rows["219:1885136038"]="이 드루이드들은 엄청난 힘을 얻었습니다. 그들은 동물로 변할 수 있습니다. 번개와 강렬한 달빛을 투영합니다.$B$B아마 그 옷 밑에 배터리가 있을지도 몰라"
rows["219:1900365949"]="썬더 블러프 라이더들은 막대한 강력한 전투가 되고 가까운 거리에서 무서운 전투가 된다.$B$B방어력을 파괴하는 추진력 범위를 벗어나서 보호대를 해체해 보전부리기를 이용해서"
rows["219:2008272535"]=" ⁇ 의 마지막 조각은, 번개왕이 라덴의 힘을 차지하고, 타이탄의 본질을 가지고, 모그를 제국으로 통합하여 타이탄들의 일을 계속하려고 노력했습니다. 물론 그는 자신을 신으로 보았다."
rows["219:2079260476"]="다르나서스 라이더들은 그들의 민첩함과 원격에서 능률을 기대한다.$B$B그들은 당신의 충격을 피하기 위해 빠르고 현명한, 그래서 가까운 범위의  ⁇ 스 및 때때로 방패-브레이커를 혼합하여 그들을 물리치도록 시도하십시오."
rows["219:2087910810"]="사우스 시 해적들이 조차 항구에 도착했다고 들었어요$B$B여자 해적도 있잖아 내가 직접 가서 확인해봐야겠어"
rows["219:253786122"]="만약 더 많은 지원이 불타는 스텝으로 곧 보내지지 않는다면, 저는 스컬지이 그곳에서 기지를 구축할 것이라고 두려워합니다. 만약 당신이 할 수 있다면, 당신은 수호자들에게 도움을 줄 수 있어야 합니다.$B$B남아있는 네크로폴리스의 수는: $2281W"
rows["219:272499379"]="분노, 이렇게 이 모든 혼란에 대한 감정을 정리할 수 있습니다. 우리는 숲을 통해 해변으로 이동하려고 손가락을  ⁇ 고 노력했지만 너무 늦었습니다."
rows["219:414266956"]="키드라스는 상황을 과장적으로 극화하는 경향이 있다. 예를 들어, \"가로나: 스텔스 및 배신에 대한 연구\"는 400 번 이상 도난되었다.$B$B아테네움의 표시는 도미를 보호하여 허가되지 않은 관람을 방지합니다."
