rows["220:1086228450"]="아, 여기 있어. 난 좀 미묘하게 이 일을 해낼 수 있었지, 하지만 직접적인 대결이 불가피한 것 같았어요."
rows["220:1162671076"]="서릿결 부족의 전사를 임명하는 가장 치열한 시험의 하나처럼, 우리는 우리 자신보다도 더 거대한 생명체와 맞서도록 만들어졌습니다. 바로 거인, 용, 요르문가르와 같은 생명체지요. 크기 따위는 절대 우리의 약점이 되지 않을 거란 사실을 입증하는 거랍니다."
rows["220:1211000680"]="썬더 블러프를 둘러싼 날씨 차단기를 설치하여 도시를 보호하십시오!$B$B도시 곳곳에서 풍력 틈을 찾아내$B$B그리고 빨간색 화살표 |TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t로 표시된 위치에 배치한다."
rows["220:1378499200"]="난 이제까지 그런 총을 본 적이 없어 다시 함께 타는 것이 좋겠지만 카드락은 더 중요한 일을 해줬어"
rows["220:1447876497"]="타렌 밀은 나무 너머에 위치해 있습니다. 다른홀드에서의 혼란은 마을 전체가 인간 군인들로 가득 차기 전에 타레타를 찾기 위해 약간의 시간을 줄 수 있습니다."
rows["220:1792715666"]="내 사람들이 부패한...\010시 후, 지역 전사, 오염된 물을 처음 마셨다.\010예수 께서는 자신 을 강하게 하고 격려 하셨으며 다른 사람 들 이도 그렇게 하도록 권유 하셨습니다.\010위험과 부패를 감지했습니다."
rows["220:1985102475"]="보아라, 비루클족은 전쟁과 파괴를 미술의 형태로 완성한 인종입니다. 그들은 이미 리치 왕와 함께 그들의 운명을 던졌습니다! 그들의 주거지는 당신을 둘러싸고 있고 그들의 숫자는 당신의 다섯 배 더 쉽습니다."
rows["220:48540190"]="여기 온 걸 보니 악의 무리를 소환하여 부리는 법을 공부할 준비가 됐나 보군. 자네가 부를 수 있을 만한 가장 저급한 생물부터 시작하지. 자, 시작해 볼까?"
rows["220:527293202"]="영국 왕립 약학회 언더시티 오크 동맹군들을 도와줄 수 있는 아웃랜드우리의 유대관계를 강화하고 새로운 샘플과 연구용 화합물을 찾는 기회입니다.$B$B화합물... 독물 같은 것"
rows["220:588692507"]="네가 전에 자신을 구하러 왔어 빛아니면 여기 온 건 성예술을 배우러야지?$b$b베네딕토 대주교와 대화하러 온다면, 그가 임무로 떠났다는 것을 알려드리기 위해 죄송합니다."
rows["220:599937412"]="너들 다 똑똑한 놈들이야? 너들은 나보다 더 잘 알고 있어! 스톰윈드- 그는  ⁇ 을 잘 알고 있다고!"
rows["220:60204934"]="내 열정이야, 내 삶이나 죽음에서, 전무공은 내가 좋아하는 것인데, 제발, 날 살아있는 드레네이, 낯선 사람처럼 대해줘"
rows["220:617047515"]="사실, 바로 그런 해묵은 감정 때문에 그들은 나루를 돕고자 떠나는 영광스러운 임무를 맡으려고 경쟁을 벌입니다. 매일 이 도시의 아달이 그 결정을 내리죠. 군대는 어둠달 골짜기로 출정하기 전에 아달의 축복을 받으려고 이곳에서 집결합니다."
rows["220:648872915"]="우리가 싸우는 생물들의 영이나 \"무이스\"에서 놀라운 힘이 발견될 수 있습니다.$B$B당신 자신 을 들여다보며 당신 자신 의 영 의 힘 을 활용 하는 것 을 배우십시오. 그러면 당신 은 상상 한 것 보다 더 강력 할 것 입니다."
rows["220:675357792"]="그 드워프는 자기가 어디서 왔는지 이름이 뭔지조차 기억하지 못하는 듯 정신이 나간 것 같았습니다. 눈밭에서 같은 드워프가 죽도록 내버려둘 수 없었던 우리 아버님의 부대는 그 드워프를 데려와 서리요새로 발길을 돌렸습니다."
rows["220:683272552"]="예, 내가 찾는 사람을 알아... 오크 아버지...$b$b내가 그를 가까이에서 감지하고 있어 자신의 두려움의 폭풍 속에서 분노하고 있어"
rows["220:744833752"]="바람은 마을에 새로 온 사람들을 이야기했습니다. 우리의 마음이 열려 있고 정신이 순수하다면 서로 많은 것을 배울 수 있을 것 같습니다.$B$B아마도 당신의 사람들은 내 사람들보다 더 존경할 것입니다 호드 그랬어요"
rows["220:874209750"]="이 동물이 얼마나 빨리 성장하는지 보고 놀랐습니다. 처음에는 치즈 식단은 짐승을 자극하는 것 뿐이었습니다.$b$b하지만 우리는 그 마을의 염소를 먹여서 크기가 급증하기 시작했습니다.$b$b확실히 맹렬한 존재야"
rows["221:1143502161"]="당신의 행동은 도시를 성공적으로 되찾는데 핵심적이었다. 리벤다레의 죽음은 Plaguelands에 새로운 시대가 시작되는 것을 의미합니다. 남은 몇 명 스컬지는 쉽게 떨어질 것이고 땅이 마침내 되살아난 자 될 것입니다."
rows["221:1247572034"]="이리다리 악마들은 고대 드레네이 결정과 유물들에 대한 지식을 가지고 있어$B$B그들은 내 많은 사람들을 노예로 삼아왔고, 우리를 이용해 강력한 크리스탈을 찾았습니다. 아마도 여기조차 존재하지 않을 것입니다."
rows["221:1250231840"]="잘 말했어요, 지. 안구 너머의 낯선 사람들은 열정이 부족하진 않지만 그들이 실제로 그들을 통제하는지 보자. 분노는 증오와 모든 불행의 근원이 있습니다. 이것이 무엇입니까?"
rows["221:134263986"]="여기 다 적혀 있군요... 어떻게 까마귀 신의 추종자들이 까마귀 신에 저항하는 정령들을 사로잡아서 돌로 된 제단 안에 영원히 가뒀는지 이제 알겠어요! 이 경전에는 까마귀 신의 이름도 나와 있어요! '안주'로군요! 그 신의 이름은 역사 속에 묻혀 사라졌다고 생각했는데..."
rows["221:1389069417"]="이건 새로운 도구입니다. 이 도구들은 가젯잔 파워입니다. 그리고 여러분에게는 금입니다. 그리고 여러분은 그것을 얻지 못합니다. 왜냐하면 그것들을 여러분에게 주는 것은 쓰레기 덩어리에 던져버리는 것과 같습니다. 그들은 공예인들에 대한 것입니다. 공예인들만!"
rows["221:1738331654"]="우리 적들이 우리를 둘러싸고 있어 모크나탈족의 삶을 더 좋게 해줬으면 좋겠다 하지만 우리가 싸우고 있는 세력은 다른 방법을 택해줬어$B$B모크나탈에게 가치가 있는 사람이라면 그들을 제거하는 데 도움이 되세요"
rows["221:1768115984"]="제목에 따르면 저는 붉은십자군의 암살자입니다. 저는 하루를 보내고 고위 우선순위 목표물을 멸하고 밤은 가젯잔 디스코테이크에서요. 춤은 저의 진정한 직업입니다. 암살은 단지 계산을 지불합니다."
rows["221:1798247959"]="|TInterface\\Icons\\inv_enchant_voidsphere.blp:20|t가라'갈은 |cFFFF0000|Hspell:116727|h[배포]|h|r 당신은 당신의 동맹들과 함께 모든 영혼의 절단자를 물리치고 현실 세계로 돌아가야 합니다."
rows["221:193572308"]="레물로스... 넌 네 애비가 아니다, 벌레 같은 놈. 날 자극한다면 이 발톱으로 단숨에 숨통을 끊어 놓아주마. 샨도 스톰레이지를 넘겨라. 그러면 네 부하들과 함께 구차한 목숨을 연명할 수 있을 것이다."
rows["221:2003455496"]="저는 다른 사람들이 어디에 있는지 더 이상 기억하지 않습니다. 사실 우리는 서로를 마지막으로 본 지 너무 오래 되었지만, 다른 사람들은 죽거나 제자들로 대체될 수도 있습니다."
rows["221:2051105301"]="형제자매 여러분 아이언포지 무기를 들고 우리 수도를 지키고 전투의 소리에 응하지 않으려면 요새와 경계선을 잡아"
rows["221:259731690"]="네파리안의 유적에 대해 마스터가 큰 관심을 갖고 있습니다. 만약 누군가가 용과 그의 하역들을 물리치고 왕자에게 이야기를 다시 말해준다면, 왕자의 입술이 느슨해질 것입니다."
rows["221:400436341"]="버디한테 신경쓰지 마, 그는 널 해치지 않을거야.$B$B그는 단지 크고 사랑스러운 고양이일 뿐이야$B$B아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨, 아뇨"
rows["221:437256072"]="돌에서 울리는 거침없는 목소리...$B$B난 당신의 역의 메달리온을 감지하고 이교도당신은 정말 Twilight's Hammer의 지휘자입니까 아니면 단지 더 나은 사람들을 위해 일하러 다니나요?"
rows["221:535859720"]="\"일간 낚시하기 쉬웠던 일이 야생한 불행으로 변해서 대륙에서 가장 위험한 곳에 갇혀 거의 우리 모두를 죽였죠. 왜냐하면 당신은 당신의 직관들을 쫓는 것을 멈출 수 없었기 때문입니다\"."
rows["221:617182882"]="모고는 권위적이고 자존심이 강하고 가로쉬가 도착할 때 분노하게 만들 수 있는 특징입니다. \010그래서 우리가 이 모구들의 지도자를 체포하고 기소하는 것이 매우 중요합니다."
rows["221:717844239"]="왜 내 아들이 그렇게 작지?$B$B어렸을 때 문자를 안 열어줄게 했잖아$B$B뭐하는 거야? 그는 항상  ⁇ 을 가지고 놀고 있어! 내 안에 있어!"
rows["221:737210113"]="저는 친척들을 방문하고 있었습니다 로데론 떨어지고... 다시 돌아오지 않을 것 같네요 서부 몰락지대지금 당장$B$B우리 가 아직 살아있는지 궁금 할 때도 종종 왜 더 이상 신경 쓰지 않는지 궁금 합니다."
rows["221:822488655"]="아, $p숨겨진 마스터를 찾고 있었는데, 안에는 작은 보라색 물건이 있는 큰 보라색 물건이 있었어요.$b$b오래된 마법을 만드는 함정처럼 보이는데, 다행스럽게도 더 이상 이런 걸 만들지 못해"
rows["221:834537631"]="붉은용군단은 아제로스를 할퀴고 지나간 파괴의 흔적을 치유할 것이다. 동료와 함께 고향으로 돌아가 쉬어라. 내일은 새로운 도전이 기다리고, 그대들은 그에 맞서야만 하노라. 삶은... 계속된다."
rows["222:1097886261"]="새 보물이 있다면, 돌보장관에서 보관하고 싶어  \010아이언포지로 입구에서 동북쪽으로 한 해마트 던지기 거리만 있는"
rows["222:1114305391"]="야구!\010그들은 제 농장을 공격했고, 인근 마을인 이스트윈드 레스트는 우리 중 일부를 죽였고, 그들이 죽이지 않은 사람들을 쫓아냈어요!\010우리들 중 몇 명을 모아서 왔어요"
rows["222:1138562504"]="마지스퀘어에서 숨겨진 작은 가게는 알케미 니즈라고 합니다. 마지스퀘어를 지나가면서 모든 종류의 이상한 가게를 보게 될 겁니다. 하지만 바깥쪽 면에 붙어 있으면 찾을 수 있을 겁니다."
rows["222:1172502656"]="약사를 찾고 있어요. 그는 정말 멋진 술과  ⁇ 을 만들어서$B$B빅터 피어스는 장관실에서 물건을 팔고,"
rows["222:1205054306"]="판다렌이 웃었지, 하지만 류랑은 생각보다 똑똑했고 해조리가 태어난 해변으로 돌아왔고"
rows["222:1225759315"]="아이언포지의 어두운 부분 보다 더 나은 곳 은 어디 에서 더 나은 것 이다. 적절 히 '포론 캐버른'이라고 불리우는 곳 은."
rows["222:1504805381"]="오해하지 마세요, 저는 매일 매일 silithid로 가득한 터널에 있지 않기를 바랍니다. 하지만 여기서 숨어서 이 생물들의 움직임을 지켜보는 것이 전쟁을 이길 수 있도록 도와준다면,"
rows["222:1521023454"]="의기양양하고 기품 있는 전사였던 발스탄은 판드랄 스태그헬름의 오른팔로서 굽힐 줄 모르는 강직한 성품의 아버지를 존경하고 닮고 싶어 했답니다. 쌍둥이 제왕은 그의 이런 성격이 약점이 될 수 있다는 것을 간파했습니다."
rows["222:1553287931"]="\"그렇게 빛나는 칼이 파다리아로 갔고, 그 마지막 목적지가 알려지지 않은 곳으로 떠났다\".$B$B우리 민족의 전통은 풍부한 이야기들의 엮인 가구입니다."
rows["222:1586233092"]="이 이상한 새 땅은 모든 코너에서 위험으로 가득 차 있고, 괴물이 모든 구멍에서 튀어나오고 있으며, 흙만큼 오래된 짐승들이 두려움 없이 살아가고 있습니다.$b$b사냥 시즌이 됐어!"
rows["222:1605820656"]="믿으세요? 드디어 이 곳을 열어주셔서 제펠린을 날릴 수 있었습니다. 비행 구역이 없어졌어요. 시험에서 제펠린을 절벽에 떨어뜨렸어요. 왜 그렇게 걱정했는지 모르겠어요."
rows["222:172713747"]="왜 내가 더 많은 지옥의 것들을 원하겠다고 생각하겠지? 9천여개가 있고, 팔지 않아! 왜 내가 왜 누군가가 지나친 뱀의 동상을 원한다고 생각했을까?"
rows["222:1898685388"]="일단 자기 행동 을 통제 할 수 있게 되면, 상대 를 통제 하는 것 을 배워야 합니다. 상대 가 더 느리게 공격 하기 위해 더 많은 시간을 가질 수 있게 해 줍니다. 이 점 은 승리 와 패배 사이 의 차이점 을 의미 할 수 있습니다."
rows["222:1975490111"]="빛 네 배의 중심에 있는 나라루가 우리가 포획하고 노예로 만들 때처럼 내 말은 너를 놀라게 해, 파란 피?"
rows["222:2037248711"]="하로우의 끝에서 우리는 바시 여왕이 직접 우리를 리치 왕와 스컬지의 손잡기에서 구출한 날을 축하합니다. 매일 저녁 언더시티 밖에서 열리는 위커먼 페스티벌에 참석하는 것을 확인하십시오."
rows["222:2098802165"]="어떻게 하는지 모르겠지만, 그 우편 상자는 마법의 포털이거나 그런 거 같네요. 왜 전 하루 종일 은행 옆에 있는 우편 상자 주변에 모여있는 사람들을 보고 있는데요."
rows["222:2109347013"]="야구!\010그들은 제 농장을 공격했고, 근처 마을인 웨스트윈드 레스트는 우리 중 일부를 죽였고, 그들이 죽이지 않은 사람들을 쫓아냈어요!\010우리들 중 몇 명을 모아서 왔어요"
rows["222:21262293"]="저는 젊은 판다레들이 이 지형 안에서 그들의 잠재력을 탐구하는데 도움을 주는 것을 무엇보다 추구합니다. 진정한 숙달은 많은 시간과 연습과 함께 이루어집니다. 하지만 적절한 경로의 첫 시작을 찾는 것조차 가치가 있습니다."
rows["222:254820523"]="여기 제가 가진 것인데요, 여러분이 보시다시피, 상황은 우리가 예상했던 것과는 다릅니다.$b$b이 사람들은 도움이 필요하고, 저는 계속 머물고 그들을 도울 계획입니다.$b$b만약 당신이 또한 머물고 싶다면, 당신의 도움으로 더 좋은 기회가 있을 것입니다."
rows["222:302634468"]="다라란에서 가장 인기있는 숙소는 도시 중심부 북쪽에 있는 레거데임인 라운지입니다.$B$B얼라이언스와 호드 구간은 각각 숙소가 있고, 도시 아래로, 하천에 또 하나 있다고 들었습니다."
rows["222:463188972"]="이봐, 저한테는 그 어린 소년이 떠올랐어요. 어느 날 나처럼 되고 싶어한다고 말했어요. 자넨 금의 집 위에 앉아있었지. 너무 귀여워요."
rows["222:533360167"]="형제자매들이여, 나는 약속의 땅에 다녀왔소. 그곳에서 엄청난 힘을 경험했고 더없는 행복을 느꼈소. 너무나 행복하고 황홀한 나머지 신의 꿈을 발견한 것은 아닌가 하는 생각이 들 정도였다오."
rows["222:698242605"]="난 당신 경험에 대해 가르쳐 줄 게 없어 하지만 아직 길을 끝내지 않았어"
rows["222:705086819"]="여길로 들어간 여행자, 혹시 산림에서 대나무를 가져왔나요? 하루 종일 쳐다보고, 배설하고, 배고프며,"
rows["222:82220843"]="절대 실패하지 않을 거라 확신합니다, 주인님. 제가 직접 폭탄 제작을 감독하고 있으며 최종 접근암호도 제가 보관하고 있습니다. 하루 안에 이 근처의 벌레들을 폭탄으로 날려버리겠습니다."
rows["222:967129165"]="절대로 난 동의 못 해. 다르칸은 결국 궁지에 몰려 어떤 지원도 받지 못 할 거요. 데솔름으로 드나드는 길은 하나뿐이지. 당신을 배신한 그놈은 스스로 막다른 곳으로 들어갈 만큼 바보였소. 바로 그 약점 때문에 놈은 내 손에 죽을 거요!"
rows["223:1058613586"]="우리 마을은 작지만 우리 가족은 여러 세대에 걸쳐 이 언덕 위에 파다리아의 최고의 사이더를 생산해 왔습니다.$B$B평화가 돌아오길 바라며 우리 농사를 모으고 아이들과 함께 재결합할 수 있을 뿐이야"
rows["223:1325002547"]="컨소시엄의 대표로서, 저는 항상 제 상호작용이 우리의 비즈니스 거래에 미치는 영향에 대해 알고 있습니다.$B$B유감스럽게도 피 엘프는 그들의 파트너십을 그렇게 존중하지 않습니다."
rows["223:1350529536"]="더 좋아지고 더 강하고 더 빨리 되고 싶으면, 이 미술품들은 내가 말하는 대로 할 수 있게 되어"
rows["223:1426091094"]="봐라, 패치워크이다. 그의 존재가 처음 빛의 결사단에게 알려졌을 때만 해도 그토록 엄청난 힘과 속도를 지닌 누더기골렘이 정말 있다고 믿는 사람은 아무도 없었다. 그래서 패치워크가 쓰러졌다는 소식 또한 믿는 사람이 드물었지..."
rows["223:1464367817"]="안녕하세요, 낯선 사람, 그리고 무장한 언고로 크레이터의 영광에 오신 것을 환영합니다!$B$B내 이름은 윌리든 마셜입니다. 제 여동생과 저는 마샬 탐험을 구성합니다. 아제로스야생하고 큰 알려지지 않은."
rows["223:151561726"]="인간들은... 윈터가드 마을 지하에 묘지를 만들어 놓았지! 낙스라마스가 왜 그곳을 공격했는지 모르겠나? 텔잔 님은 너희의 납골당에 숨은 채로 너희에게 수천 구의 시체를 올려 보내고 계신다! 너희는 패하게 돼 있어..."
rows["223:1612016711"]="제가 해야 할 일들은 더 작은 일이거나, 아니면 다시 제 말을 듣게 될 것입니다. 그리고 저는 여러분께 공론 포럼에 대한 저의 논평이 매우 불쾌할 것이라고 확신합니다."
rows["223:1686447371"]="샤트트라트의 전투장들은 종종 상부와 하부 도시 사이의 계단벽에 모여있다. 얼라이언스 전투장들은 한 곳에서, 호드 전투장들은 다른 곳에서 모여 있으며, 그 사이에 그리고 그 반대편에 경기장 전투장들이 있다."
rows["223:1712817962"]="트롤이 탈출을 도와줘서 고마워요, 친구들. 이제 여러분도 저를 도울 수 있기를 바랍니다. 저는 오늘 아침 일어나서 이 마법의 감옥에서 갇혀있다는 것을 발견했습니다. 이상한 마법사가 제게 잠시 동안 여기 머물게 될 것이라고 말했습니다."
rows["223:1761711996"]="네 바람의 계곡에 갔어?$B$B우리는 농부들이 밸리 위기에 대해 듣고 있고, 티러들은 난민들을 위한 먹거리를 재배하는 데 열심히 일하고 있습니다.$B$B야외에 좀 가보고 싶다면 하프힐에서 찾아와!"
rows["223:1952414088"]="블랙록 오크와 계약이 쉽지 않아 블랙록 오크들, 애그라마르보다 더 많은 전투를 해왔고,"
rows["223:365146073"]="당신은 능력 있고 재능을 발휘했고, 우리가 할 수 없는 자리 벌레에 맞서 싸울 수 있는 사람이 될 것 같아요."
rows["223:497847642"]="당신은 손잡이 동물에 대해 몇 가지 알고 있을지도 모르지만, 당신은 하늘을 탔을 수 있습니까? 우리는 와일드햄버러가 바람을 타고 가장 좋은 것을 알고 있습니다. 작은 수수료에, 당신이 용기를 가지고 있다면, 나는 당신을 잘 훈련 할 것입니다."
rows["223:808392313"]="무기를 사용하는 데는 안세흐와만큼 능숙한 사람은 아무도 없습니다. 그는 우리의 존경받는 조상들의 최고의 전사들의 정신에 의해 인도된다는 것입니다."
rows["223:980376143"]="바락에서 이 \"샤\"의 소음들을 들었어요$B$B우리 군대를 가진 미친 이야기 들었을 텐데?$B$B이 셰는 나나 여동생들이 감당할 수 없는 일이 아닙니다."
rows["224:1166392221"]="슈는 우리에게 소중한 존재입니다. 우리는 그를 찾아야 합니다. 하지만 그는 어린 아이처럼 성향을 가지고 있습니다. 그래서 우리가 접근하는 데 그를 겁내지 말아야 합니다.$B$B내가 그가 어디에 있는지, 그리고 어떻게 그를 가장 잘 찾아낼 수 있는지 생각해볼게요"
rows["224:1185400521"]="'젊은 형제'라고 말 할 때, 우리 는 쌍둥이라고 언급 하지 않습니다. 사실, 그는 몇 분 정도 더 나이가 들어 있습니다.$B$B그 '어림하는 별'의 속임수가 당신을 속이지 못하게 해"
rows["224:1335835878"]="<고등검찰 페어뱅크스 주관합니다>$B$B아, 저자 모그라인, 스카르렛 지휘관으로 알려진 그는, 내가 의심하는 것 처럼, 대 십자군의 대행을 통해"
rows["224:1409811575"]="여기 피크닉을 약속했었는데 위험한 곳이야$b$b그리고... 거북이한테서 온 사람.$b$b난 항상 거북이 전설이라고 생각했지"
rows["224:1614197913"]="로가 제 학생인 시라와 함께 동쪽으로 향하고 있는 것을 보고 있지 않아요$b$b부모들이 이 사실을 알게 되면 잘 되지 않을 겁니다."
rows["224:17007284"]="그리고 당신의 원정순찰대가 우리를 지원하기 위해 여기 온 것이라면 받아들이겠소. 하지만, 그들은 동쪽 국경의 그림자소나무 트롤 때문에 바쁘다고 알고 있소. 기다리는 시간이 길어질수록 스컬지는 점점 강해질 것이오."
rows["224:1747902909"]="당신의 가장 큰 도전은 앞으로 있습니다. 레이-수호자 에레고스는 엄청난 힘을 가진 파란 용입니다. 당신은 그를 가장 높은 반지의 위를 날아가는 것을 찾을 것입니다. \010드레이크의 전력은 풀려났어 에레고스를 물리치기 위해 그들의 힘을 사용하라"
rows["224:1753487222"]="네싱워리 마스터가 큰 사냥을 앞두고 있습니다. 난 그를 정글에서 하루를 준비하는 데 도움이 되는 것이 전투에 준비하는 것보다 훨씬 더 편안하다고 생각합니다. 비록 나는 전투장에서 그 영광스러운 순간을 그리워합니다."
rows["224:1839566715"]="이 퍼즐의 또 다른 조각은 모고가 세운 것입니다. 그들은 그들의 주인으로부터 명령 없이 천 년 동안 좌절했습니다. 그리고 그들의 몸은 육신으로 변했습니다. 모고는 서로 논쟁하기 시작했습니다."
rows["224:2030311111"]="내가 그랬다고 해도, 바보야, 네가 내게서 빼앗길 수 있게 해 줄거라고 생각하니?$B$B내 작은 친구, 그것은 곧 일어나지 않을 것입니다."
rows["224:2041539299"]="여가시간에 다양한 맥주를 실험해봤어요$B$B스톰스타우트 맥주 공장 바로 그 반대편에 있어 가끔 영감을 받아$B$B하지만 이 제품은 저곳에서 만든 것만큼 좋은게 아니에요"
rows["224:20558965"]="다른 시간과 장소에서 나라는 어린 아이일 뿐이었을 겁니다. 나라루의 영광을 위해 살기 위해 준비된 경험이 있는 전투자입니다.$B$B우리 10명이 마나포르지 아라에 갔고 나머지는 레지온에 속했다"
rows["224:210401463"]=" ⁇ 을 이용해 인간 씨발의 머리를 찢어내세요.|TInterface\\Icons\\INV_MISC_SHOVEL_01.BLP:24|t$B$B또는$B$B[오른 클릭] 인간 씨를 흙으로부터 해방시키기 위해.|TInterface\\Cursor\\SKINALLIANCE.BLP:24|t$B$B옳은 일을 해"
rows["224:2129641434"]="걱정 마, 젊은여. 우리 협정이 일시적일 줄 알았어. 괜찮아$B$B하지만 넌 여기 있지 않아 아직 네 시간이 아니야 내가 살아 있는 세상으로 돌아가는 데 도움이 될거야$B$B이건 내 몫이야"
rows["224:229011283"]="로드 앤 릴의 마스터를 만나세요! 만약 여러분이 이 나라의 최고의 어업인들과의 경쟁을 하려면, 이 일요일, 스탠글스톤에서 어업의 마스터가 선출될 경연이 있습니다!\010"
rows["224:296171313"]="빛의 결사단에서 가장 강한 자의 영혼조차 산산이 부서졌을 법한 시련을 켈투자드는 견뎌냈다. 계획에 따라 자신의 목숨을 아서스에게 선뜻 내주고는, 후에 태양샘의 힘으로 다시 태어났지."
rows["224:3689772"]="수백 년 동안 알래스린은 사냥꾼들이 친숙하게 사는 동물들을 돌보아왔고, 사냥꾼들이 그의 동물들을 많이 찾고 있습니다."
rows["224:383017469"]="자기 이기적 의 목적 을 위해 시간 에 개입 하는 사람 들 은 종종 위험 합니다.\010그래서 워든에 합류했어요. 타임워커의 강력한 수호자죠.\010우리는 수비자와 수직자를 보호하며 그들이 그들의 일을 수행하는 동안"
rows["224:46766181"]="거의 못 됐어!$B$B저는 쿼그미란의 존재를 증명하기 위해 왔어요.$B$B내가 당신에게 콰그미란을 처리하는 것을 도울 수 있는 상을 주겠다"
rows["224:485973491"]="요리사야? 그건 사실일 것 같네요. 바메이드는 가끔 부엌에서 일해야 합니다. 그리고 저는 몇 년 동안 몇 가지 레시피를 배웠어요."
rows["224:674656715"]="퀴라지 군대에게 퇴각하여 사막의 모래 속에 매복해 있으라는 명령이 내려졌지요. 그리고 그중 일부는 스태그헬름의 군대가 최전선에서 교전 중일 때 마파람 마을을 공격하라는 명령을 받았습니다."
rows["224:837725281"]="스톰파이크는 지뢰로 전지를 뒤덮고 있어"
rows["224:947551400"]="오크와 타우렌은 서로 만나게 된 행운이 있습니다. 왜냐하면 각 민족의 강점은 다른 민족을 칭찬하기 때문입니다.$B$B심지어 포세이큰 참여, 하지만 어떤 목적을 위해 나는 확실하지 않습니다 ..."
rows["225:1049056498"]="기억나지? 우리는 한때 인간이었는데 로데론 그 스컬지- 당신의 변신 스컬지 좀비들은 제 후에도 왔고 그 후에도 우리의 정신은 암흑의 여인이 해방시켰습니다."
rows["225:1092484784"]="Twilight's Hammer는 우리가 가진 힘으로, 죽음의 날개가 자유로울 수 있습니다.$B$B우리에게 무엇을 제공해야 한다고 생각하십니까?"
rows["225:1146224063"]="불행 히, 발나사르는 아직 끝마치지 않았습니다. 필사적 차원 에서 한 공포 스승 을 물리치는 것 은 그 를 뒤틀린 황천 로 돌려보내게 합니다. 그는 언젠가 다시 돌아오고, 아마도 그의 형제 들인 바리마트라스와 데테로크 와 함께 일 할 것 이다. "
rows["225:114917900"]="치 지는 남쪽으로 붉은 크레인의 사원을 감시합니다.$B$B그녀는 폭발이 전국에서 혼란을 일으킨 후 질서를 회복하려고 노력하고 있습니다.$B$B만약 당신이 그녀를 돕고 싶다면, 크라사랑 야생지방의 치 지의 자람으로 이동해 보세요."
rows["225:1516291235"]="너희는 천지의 자손들이 지혜와 힘과 기운과 희망을 가진 진솔한 얼굴들을 마주하게 되나니 그들에는 세대가 넘도록 보이지 않는 능력과 능력이 있도다"
rows["225:1545815192"]="단편적인 놈이 강해질 수 있는 방법이 있어 내가 원한다면 내 부족의 비하에서 벗어날 수 있을거야$b$b방법이 있지만 너무 무서워요 너무 약해요$b$b그들은 나를 이해하지 못해 평생은 내가 단편적인 존재가 될 거야"
rows["225:156807034"]="이 사람에 대해 몇 가지 불만이 제기됐는데, 그는 좀 더 유연한 성격이라고 전해졌어요."
rows["225:1617632247"]="나약한 정신은 조종하기 아주 쉽지... 난 시간과 운명조차 건드릴 수 없는 강력한 분께 충성을 맹세했느니라. 이 세계와 저 너머 세계의 어느 누구도 우리를 꺾지 못해... 저 잘난 불타는 군단조차도!"
rows["225:1686155926"]="폭풍을 일으키는 악행은 멈추고, 포가워드는 언덕을 공격하고 프로스트맨과 잔다라리 모두를 없애버릴 것입니다.$B$B내 산악인들과 트롤들이 잡은 포로들을 이용해서 길을 안내해"
rows["225:1719271175"]="제 터보타조가 돌진할 때 창을 정확한 각도로 들고, 주어진 시간 안에 방어를 최적화하기 위해 방패를 정확한 위치에 들고 있는 데 필요한 수학 공식을 정확하게 낼 수가 없어요!"
rows["225:1768116523"]="몇 년 동안 저는 우리가 옳은 일을 하고 있다고 확신했습니다 실버문 - 도달하기 위해 노력 아웃랜드 그래서 케일과 다시 만날 수 있게 됐어요$B$B케일타스가 우리에게 무엇을 준비하고 있는지 알았다면, 나는 바로  ⁇ 클링 스퀘어에 머물렀을 것이다."
rows["225:1771633717"]="토림은 이 하피들처럼 아니라 신처럼 높고,$B$B그는 툴두어와 메이커의 테라스의 타이탄들을 수호자로 섬겼다.$B$B그 때 까지는 그의 아내 시프가 그의 동생에 의해 겁쟁이로 살해당했습니다."
rows["225:1911003934"]="보호막이 사라졌구나. 이제 바로스는 약해졌으리라! 바로스를 처치하고 하늘빛 고리 수호자들을 도망가게 하면 상층 고리에 접근할 수 있도다. 바로스는 떠다니는 단 위에 있는데, 그 장소는 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라."
rows["225:2064660935"]="여기 있는 블랙탈론 쿼터마스터를 찾아봐요. 그는 내가 전에 준 모든 보상을 다시 공급할 수 있습니다. 당연히 가격으로."
rows["225:2129302092"]="아, 귀여운 말이지, 하지만 이미 필요한 가죽이 다 있고 네 칼은 아직 날카롭지 않은데"
rows["225:355576943"]="영웅 여러분, 잘 해 주셨어요. 발나자르는 너무 오랫동안 위협이 되었죠. 그는 스컬지와 붉은십자군에 손을 잡았어요. 우리 두 가지 가장 어려운 적들 중 하나였습니다. 부활한 사람들은 우리에게 대항해 균형을 돌렸을 수도 있습니다."
rows["225:36294454"]="얼음 늑대 보호소는 알테락밸리의 남쪽 끝에 위치하고 있으며 동명의 오크 부족의 고향인 얼음 늑대 마을을 보호합니다. 호드 알테락밸리의 영토는 이 하나의 권력으로부터 비롯되었습니다.$B$B프로스트울프 킨은 손상되지 않았습니다."
rows["225:37845772"]="대사인 다운싱거와 저는 오그리마에서 태양의 궁전을 대표합니다.$B$B대사는 민사 문제를 처리하고, 저는 트롤에게 군사 캠페인과 피 기사들의 특유의 장점을 조언합니다."
rows["225:390065905"]="이 책 에서는 아웃랜드의 식물 종 에 관한 정보 를 담고 있다. 상세 히 설명 된 식물 들 의 대부분 은 장가마르시 에 원산 이다.$B$B이 책 에서 나오는 차트 와 다이어그램 을 사용하여 여러 식물 종을 식별 할 수 있다는 확신 을 갖게 됩니다."
rows["225:447314090"]="오그리마를 둘러싸고 도시 보호를 위해 바리케이트를 설치하세요!$B$B도시 곳곳에 흩어져 있는 상자에서 바리케드를 꺼내$B$B그리고 빨간색 화살표 |TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t로 표시된 위치에 배치합니다."
rows["225:459973652"]="약사를 찾고 있어요. 그는 정말 멋진 술과  ⁇ 을 만들어서$B$B약사 그린모스는 공예실에서 물건을 팔고 있어"
rows["225:576118146"]="[PH] - 막연기가 최근에 야기한 불안정성에 대해 말리고스의 Kirin Tor와 모든 필사적인 마법 사용자들을 파괴하려는 노력에 대해"
rows["225:603144994"]="드라카리가 이렇게 스스로를 파괴하는 것을 보는 것은 우리 모두를 슬프게 만듭니다.$B$B그들이 이 땅의 자연 신들을 죽이는 힘은 일시적일 뿐이다.$B$B짧은 시간 동안 얻은 것은 영원히 사라질 것입니다."
rows["225:623294623"]="자, 너  ⁇ 디의 아보레텀을 보고 싶어. 내가 방금 말했어? 글록타르 난 피곤해야 해. 지혜의 계곡에 있는 아소란 시장 뒤에 있는 나무 계단을 따라 드래그로 올라가면  ⁇ 디가 상단층에 있을 거야."
rows["226:1052471687"]="더 두꺼운 가죽이 있다면 미안하지만 너무 늦었으니 우리가 필요한 모든 것이 있지만, 떠나기 전에 다른 사람들과 확인해 주시겠습니까?"
rows["226:1083346648"]="한때는 아버지가 완벽한 동굴 벼를 찾아 숲에서 며칠을 보냈습니다.$b$B아주 위험했고, 내가 할 수 없는 일이었습니다.$b$B스톰스타우트는 질이 아니라 양만 지불합니다"
rows["226:1162338245"]="하지만 넌 과거로 낯선 사람이 아니야. 방랑 섬의 판다렌. 나는 네 고향이 전설일 줄 알았는데,"
rows["226:1196531828"]="왜 여자들이 나쁜지 알고 싶으세요? 왜냐하면 그들이 하는 일은 죽은 자들의 영들을 부르고 있다고 생각하기 때문입니다. 하지만 그 다음에, 당신은 그들을 말하는 것 이상으로 한 걸로 잡습니다!"
rows["226:1202658427"]="여기서 뭐하는 거야?$B$B우리는 폭풍의 요새로 보내는 에너지의 양을 두 배 이상 늘렸고 아무도  ⁇ 을 수 없습니다. 우리는 여기서 또 다른 울트리스가 일어나지 않기를 원합니다."
rows["226:1212185635"]="그 모가들은 더 열심히 노력해야 할 거야!$B$B골든 로투스는 밸리를 지켜줄 거야$B$B우리가 지켜주는 비밀은 너무 귀한... 너무 강력해..."
rows["226:1501658986"]="교활한 마법사 군주 우롬이 세 번째 고리를 보호하고 있습니다. 놈은 무방비 상태로 혼자 있는 것처럼 보이지만, 겉모습에 속아서는 안 됩니다! 우롬은 실체 없는 생물 군단을 지휘하는 강력한 요술사입니다. 위쪽에서 그를 찾아보십시오."
rows["226:1529972275"]="네퍼셋 움직임은 없는데 오시스 시는 지금까지 목격한 최대 모래 폭풍이 닥치고 있다는 소식이 전해졌어요$B$B전 직접 왕에게 전하를 보내려고 했는데, 어쩌면 당신은 그 정보를 전달할 수 있을지도 몰라요"
rows["226:1637441990"]="법적으로 얻은 램을 보고 싶다고 생각했는데, 하지만 놀기 전에 일해야지$b$b이 양떼에 있어서 일과 놀이는 거의 똑같습니다."
rows["226:1776736419"]="왕  ⁇ 은 곧 우리 에게 돌아와서 또 다른 왕 이 그 의 존재 를 알려 주게 됩니다. 5 년 동안, 우리는 스컬지의 명품 을 가지고 있으며, 용감 한 영웅 들 은 가까운 곳 이나 먼 곳 에서 위협 을 받으며 정복 된 땅 을 지키고 있었습니다."
rows["226:1855402798"]="와우, 예, 정말 좋네 $P 내가 널 광산에서 내보내서 비극적이고 불가피한 죽음을 연기해줬어 포세이큰 너처럼, 멍청아"
rows["226:1857720321"]="만약 당신이 브루페스트 상권에 충분한 돈을 벌면, 브루페스트 캠프의 티켓 구상자는 당신에게 \"공예 브루어\"의 손표를 줄 수 있습니다.$b$b그 표지가 브루페스트 승마 양을 팔 수 있게 해 줄거예요"
rows["226:1966603276"]="최근 우리가 겪은 많은 사람들이, 그들이 제공하는 도움보다 더 많은 문제들이고,$B$B파스트라이더들한테 가입하고 싶지 않니?"
rows["226:2007185666"]="연습해야 돼\010 \010<수목을 들고 있는 도구로 가리키세요.>\010 \010연습하지 않으면 연습해야 해요. 계속 연습하세요. \010 \010그게 당신이 나아질 유일한 방법이야, 어떤 일에든 좋아질 거야 \010 \010연습, 연습, 연습"
rows["226:2109234305"]="<밤의 엘프는 당신이 다가오면서 당신을 향해 돌아서 당신의 손을 뻗어줍니다.>\010나에겐 너무 늦었어, 우린 자부심을 가지고 운명을 얻었어, 다른 사람들이 이겼을지도 몰라\010<생명이 빠져나갈수록 그녀의 잡힘이 느슨해진다.>"
rows["226:2141733878"]="데이터 접근이 허용됐습니다. 좋은 날 보내세요!\01001001110 01100001 01110100 01100001 01101100 01101001 01100101 00100000 01010000 01101111 01110010 01110100 01101101 01100001 01101110 00100000 01010010 01101111 01100011 01101011 01110011"
rows["226:250486524"]="네가 거짓말을 한다고 생각하진 않는다, 아카마. 캘타스 놈의 배신도 그리 놀라운 일은 아니지. 하지만, 너의 종족이 그와 연루되었다는 사실은 너의 충성심을 의심하게 하는구나."
rows["226:303602902"]="그롤다르와 암흑불 앙클라브를 찾고자 하는 분? 그 은하의 갈라진 동굴에서 찾을 수 있습니다. 그 동굴로 2개의 터널이 있습니다."
rows["226:31021022"]="날 기억하지 못하는군, 아니오? 우린 한때, 아주 오래전에 인간이었지. 로데론이 스컬지들의 손에 들어가기 전까지 말이오. 내가 스컬지 좀비가 된 후 바로 당신도 스컬지 좀비로 변했소. 그 후로 오래지 않아 우리의 정신은 어둠의 여왕님 덕분에 해방되었다오."
rows["226:401304857"]="그리프타라는 상인이 이 도시에서 사단법으로 추방됐습니다. 우리는 그가 판매하는 작은 닉스 쥬얼러를 매우 조심스럽게 검토할 계획입니다."
rows["226:426930036"]="내 몸에 돌아와서 널 죽일 거야,  ⁇ ! 아니... 내가 말하려는 건 널 포옹할거야"
rows["226:560181027"]="내가 원하는 건 다시 한 번 왕을 섬길 뿐이야$B$B대신, 저는 우리의 숫자가 이교도 스카트가 침투한 것을 발견합니다. 모든 징후들은 이 부패의 기원을 나크사나르로 가리킨다."
rows["226:711690282"]="이 모든 것이 파란 용의 성지에서 남았어요. 포세이큰 땅이 흩어져 있는 조각들을 재구성하고, 갇힌 영을 물리쳐서 계속해야 합니다."
rows["226:758810999"]="내가 말했듯이, 너희 안에 철수자의 피가 있고, 내가 옳았어. 아이언포지, 대 도형에 가서, 네 자신을  ⁇ 스 딥포르지라는 이름의 왜성 도형자를 찾아라."
rows["227:1000527174"]="만약 여러분이 빠르고 안전한 이동의 선물을 찾고 있다면, 여러분은 목적지에 도착했습니다. 올해의 새로운 메카노 스트라이더 모델은 최근에 도착했습니다. 그리고 저는 그 모델들이 제공하는 모든 것을 보여드리기 위해 준비되어 있습니다."
rows["227:1067510059"]="다시 한 번 말하지만 귀부인의 전략적 입장에는 절대 동의할 수 없소. 그 계획대로 하면 우리 병력은 너무 분산되오. 그러면 정작 데솔름을 공격할 병력은 얼마 남지 않을 것이오. 그런 전략은 도저히 수행할 수 없소."
rows["227:1154306512"]="레디 실바나스의 반응과 그녀의 목걸이를 회복하는 것에 대한 소식이 채널을 통해 내게 돌아왔습니다.$B$B이제, 당신의 일을 말해주세요."
rows["227:1207677757"]="Twilight's Hammer: 언제 어디서나 지역 악의적인 계획들을 위해 기꺼이 봉사합니다. 그리고 오늘은 예외는 아닙니다! 우리의 마지막 전투자는 그리 멀리 떨어진 twilight의 기저에서 왔습니다! 아니면 twilight의 기지가 있습니까?"
rows["227:1210515491"]="- 네 포세이큰 무기의 마스터 아치발드는 포로무기를 잘 알고 언더시티펠라다, 피의 엘프 무기 마스터 실버문네, 네, 네, 내가 네 기술을 가르쳐 줄게"
rows["227:1224760706"]="미술에 대해 연구하면서 웃음을 당했을 때, 그 냄새를 숨기려고 했었는지 믿으세요?$b$b누가 지금  ⁇ 산의 바람에 서서 웃고 있는 거야?"
rows["227:1235613840"]="잘해냈다, 용사들이여! 이 방 안에 우리 기지를 세워야겠다. 마법사들이 곧 스컬지 이동 수단을 준비할 것이다. 다음 임무를 수행할 준비가 되면 그 안으로 들어가라. 나와 그쪽에서 만나자."
rows["227:1341810736"]="바탕은 뭐라? 네, 제가 마지막으로 들은 것 처럼 기억이 잘 들어있다면, 얼라이언스는 $2076w의 $2077w의 천연 바탕을, $2082w의 $2083w의 실크 바탕을, $2088w의 $2090w의 룬클레트 바탕을 만들었다고 보인 것 같습니다."
rows["227:1497623342"]="왜 그런 기술이 필요해? 정직하지 않은 사람들만이 잠금을 뽑는 법을 배우고 싶어할 거야.\010공부를 하고 싶다면, 구시가지에서 가장 좋은 곳을 찾아볼 수 있겠죠."
rows["227:1509179518"]="네 죽음을 결코 헛되이 하지 않으마, 내 아들, 탤런. 세상을 오염시키는 악을 멸하기 위해 헌신할 준비가 된 새로운 기사단이 창설되고 있단다. 어떤 술책이나 웃음으로도 숨길 수 없는 악을 제거하기 위해서 말이야."
rows["227:1691312732"]="물론, 우리의 사유를 위해 목숨을 걸고 있는 사람들을 보상하는 것이 옳습니다.$B$B밸리를 지키는데 도움을 주면 국경을 안전하게 유지할 뿐만 아니라 강력한 보물들을 보관할 수 있게 될 것입니다."
rows["227:1887803855"]="황제 비지어  ⁇ 록의 |cFFFF0000|Hspell:123791|h[황후의 노래]|h|r. 당신은 또는 당신의 동맹 중 한 명이 황제 비지르  ⁇ 록이 탑재한 플랫폼으로 이동하고 황제 비지어를 전투에 참여하도록하십시오."
rows["227:1974289494"]="뭘 몰라도 한참 모르는군, 레브론스키! 주제넘은 소리하곤! 무쇠 드워프들은 자기들이 뭐에 당했는지도 모를 거야! 자넨 그 양탄자에 묻은 똥의 비밀이나 파헤치는 거 계속하고, 나 같은 진짜 과학자님께서 하시는 일에는 참견하지 말라고!"
rows["227:2008161370"]="힌디어와 볼리우이브 모두 덩어리 크기와 상관없이  ⁇ 을 제대로 흔들는 방법을 보여줄 수 있습니다. 볼리우이브는 아이언포지에서 Timberline Arms 안에 있습니다. 할리우이브는 자신의 하루를 엑소다르에서 트레이더의 계층에 드레네이를 훈련합니다."
rows["227:203897134"]="클라시족에 대해 아는 게 거의 없지만, 서쪽 먼 덤프 사막의 그들의 도시인 클라시시베스의 소문을 들었어요.$B$B지도에 위치를 표시해 줄게요"
rows["227:252954219"]="아, 많은 사과가 있습니다. 당신은 적어도 이 정도 높을 수 있어야 합니다.$B$B<피어렛은 오른손으로 높이 추정을 하고 무릎 길이를 따라 떠다니는 것 같다.>$B$B어른이 되면 돌아오세요"
rows["227:264314730"]="내 잘못이 아니야... 내 잘못이 아니야!!!$B$B내가 말했듯이만 했으면 모든 게 괜찮았을 거야$B$B이제 다 죽었어$B$B그냥 집에 가고 싶어요 실버문너무 피곤해"
rows["227:358476135"]="나가들이 우리를 살려주기 위해 노력하는 것은 이상하네$b$b그들은 신비한 진주로부터 감옥을 만들어 냅니다. 숨을 쉬는 세포들,$b$b그들은 죄수들을 어딘가에 보내죠$b$b다시는 못 볼 거야"
rows["227:423507418"]="짐'토르가 는 우리에게 어느 정도 보호를 제공할 수 있지만 스컬지의 존재와 드라카리의 행동으로 인해 크게 약화되었습니다.$B$B아후나와 내가 우리의 나머지 방어에 신경을 써야 한다."
rows["227:50296752"]="크툰이 그토록 기다려 온 순간이 마침내 도래했습니다. 그의 피조물들이 수천 년 동안 칼림도어 전체를 향한 복수의 일념으로 군대를 양성해 온 결실이 이제 곧 이루어지는 순간이었습니다."
rows["227:666302747"]="<강호가 당신을 쳐다보고, 거침없이, 그리고 찌그러진.>$B$BSubject Nine는 자신의 흔적을 가려하기 위해 자신의 클론을 남겨둔 것 같습니다. 똑똑한 소녀! 당신은 우주에 정확히 무엇을 풀어냈는지 생각해보세요."
rows["227:711737264"]="우리는 젊음의 수영장을 찾아가고 있습니다!$b$b전설적인 물은 아즈하라 여왕보다 훨씬 전의 신비한 잃어버린 문명의 축복이었습니다.$b$b이 물로 우리는 칼도레에 불멸의 영광을 회복할 수 있을 것이다."
rows["227:726125234"]="우리가 방금 이 불타는 군단어둠의 불에 대한 탐구, 그림자의 갈라짐으로 알려진 지하 동굴에서"
rows["227:756935068"]="알터랙밸리는 몇 년 동안 프로스트울프 클랜의 고향이 되었는데 우리는 왜자와 그들의 얼라이언스 침입을 허용하지 않을 것입니다! 그래서 우리는 싸워!$B$B알테락을 되찾기 위해  ⁇ 발다르에서 반나르 스톰파이크 장군을 물리치고$B$B호드의 경우!"
rows["227:784955270"]="말가니스는 우리를 방해하려고 스컬지 부하들을 보낼 것이다. 너희 중 강한 힘과 마력을 지닌 이가 나서서 상대해야 한다. 나는 나머지 병력을 이끌고 감염자를 처리하겠다."
rows["227:835452108"]="이 아름다운 숲은 끔찍한 저주 아래 고통 받고 있습니다. 부패한 힘은 그들의 옛 자아의 그림자로 삶을 뒤집고 있습니다. 만약 당신이 이 부패의 요인이 아니라면, 아마도 당신은 Felwood를 되찾는데 도움을 줄 수 있습니다."
rows["227:964990763"]="벨가리스트라스는 진실을 말하고 있습니다.  \010녹색 비행에서 드레이크를 불러줄 수 있는 힘을 줄 수 있어."
rows["228:1207184569"]="어떤 의문도 남지 않았다. 어떤 의심도 없다. 너희는 아제로스의 가장 위대한 용사들이다. 너희 앞에 놓아둔 모든 도전을 극복해 내었다. 가장 강력한 종들이 너희의 무자비한 살육 앞에 쓰러졌지... 너희가 억눌렀던 분노 앞에 말이다..."
rows["228:1243087383"]="내가 너무 멀리 갔다고 생각하십니까? 그런 일은 없습니다. 블랙 하베스트는 가장 강력한 악마들을 노예로 삼고, 그들의 힘을 끌어내며, 이 세상과 아제로스에서 우리를 반대하는 모든 사람들을 파괴할 것입니다!"
rows["228:1298678235"]=" ⁇ 이긴 위켓은 마켓 머리를 훔쳤고, Kunzen Hozen는 몇 년 전에 잃었습니다. 이제  ⁇ 이긴 비킷들은 그들의 유적 안에 숨어 있고, 머리가 마치 어떤 멋진  ⁇ 이긴 카로트처럼 숭배됩니다.$b$b조심해, 그 붓고 있는  ⁇ 은 입이 딱딱해요"
rows["228:1315563297"]="알 수 없었어요. 아마 뼈밀도가 낮거나 폐 용량이 평균보다 크거나.$b$b어쨌든 이 상자만이 날 표면에 발사하지 못하게 해주는 유일한 것"
rows["228:132218656"]="오, 친구!  ⁇ 을 올려 주선으로 갈라놓고 배트를 내려다보며 바다로 가요. 오늘 벤처 회사의 악어들을 파고 보내서 물고기에 먹이를 줄게 해"
rows["228:1327065278"]="정신은 아직 발견하지 못한 수많은 힘을 가지고 있습니다. 균형과 지혜로, 이러한 능력을 해제하는 것이 가능할 수 있을지도 모릅니다.$B$B꿈의 맥주가 이 모든 것을 보는 상태를 일시적으로 만들어내는 도구일 뿐이다."
rows["228:1401238474"]="우리 둘 사이에선, 저는 이 좋은 장군이 해야 할 일을 할 지경이 없다는 것을 걱정합니다.$B$B이쪽은 호드 역사에서 알 수 있듯이 평화는 결코 있을 수 없습니다.$B$B우리의 목표는... 파괴가 되어야 합니다."
rows["228:1563932969"]="솔직히 말해서, 저는 이 포세이큰 장소를 떠나기 위해 다다랑가의 한 가방 안에  ⁇ 을 기회를 가질 수 있는 적어도 네 손가락을 바쳤을 것입니다."
rows["228:169293623"]="내가 처음 잡혔을 때 테디를 싫어했는데 그는 내 피부에 깊숙이 파고들어서 나를 자유롭게 움직이지 못하게 했지"
rows["228:1717870677"]="컨트롤러를 이용해 연결된 프로토론 가속기를 활성화할 수 있어 바시르의 선보인 중 하나를 불러일으킬 수도 있고,$B$B물론, 기기를 활성화하기 위해 가속기 모듈이 있다고 가정하면"
rows["228:189084540"]="알레고르네는 수 세기 동안 요리법을 완성할 수 있는 훌륭한 요리사입니다. 그가 당신에게 가르치기로 결정한다면 자신을 축복받은 사람으로 생각해야 합니다. 당신이 가치가 있다고 믿는다면, 당신은 그를 수공 테라스에서 찾을 수 있습니다."
rows["228:1989361317"]="제가 이 일을 시간 내에 완료하도록 여기 왔습니다.$b$b부티베이도 여전히 물결에서 회복하려고 노력하고 있습니다!$b$b우리가 필요로 하는 마지막 것은 호드  ⁇ 비 트롤, 독성 뱀 또는 미친 팬더가 우리를 공격하는"
rows["228:2064562785"]="이 책 에서는 아웃랜드의 식물 종 에 관한 정보 를 담고 있다. 상세 히 설명 된 식물 들 의 대부분 은 장가마르시 에 원산 이다.$B$B차트와 다이어그램은 조금 이해가 안 되는 것 같습니다. 아마도 저자가 몇 가지 팁을 줄 수 있을 것입니다."
rows["228:2086431938"]="오케이드와 깨끗한 물 사이에 최고의  ⁇ 을 위한 레시피를 만들었을 수도 있고, 그 일을 하기 위해 브루마스터 샤도포어에게 가야 할 수도 있습니다."
rows["228:283821483"]="아, 많은 사과가 있습니다. 당신은 적어도 이 정도 높을 수 있어야 합니다.$B$B<말트레이크는 오른손으로 높이 추정을 하고 무릎 길이를 따라 떠다니고 있다.>$B$B어른이 되면 돌아오세요"
rows["228:322665529"]="우리 사람들은 그런 길을 걷지 못하지만, 당신은 운이 좋군요. 타우렌 여성이 적어도, 저는 그것이 여성이라고 믿습니다."
rows["228:576100622"]="혼란을 위해 존재하고, 그 소소한 속삭이는 전체 세계의 파괴를 의미했습니다!$B$B하지만 여전히 이 정신이 없는 존재를 숭배하려는 사람들이 있었고, 심지어 더 미친 사람도 있었습니다."
rows["228:601883924"]="전투가 치열해지고, 우리 선장과 적의 선장이 모두 죽습니다!$B$B드렉'타르가 이제 프로스트울프 킨에서 우리를 이끌고 있고, 왜성 반나더 스톰파이크는 던 발다르의 깊은 곳에 숨어 있습니다. 반나더를 물리치고 호드의 승리를 주장합니다!"
rows["228:715261711"]="홍수를 막기 위해 모래 봉투를 스톰윈드 주변에 배치하십시오!$B$B도시 주변에서 있는 모래봉자 집합에서 모래봉자를 가져오세요$B$B그리고 빨간색 화살표로 표시된 곳에 놓습니다. |TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t."
rows["228:767735677"]=" ⁇ 도파의 끊임없는 노력만이 이 땅이 만티드 무리가 파괴하지 않도록 하는 유일한 것 입니다. 우리는 그 이유에 대해 감사하지는 않지만, 이제 우리는 더 이상 혼자 이 일을 할 수 없는 시점에 직면하고 있습니다."
rows["228:809178600"]="전설에 따르면  ⁇ 은은 세기에 걸쳐 자신의 대회에서 싸우지 않았다고 합니다.$b$b그는 우리가 싸울 기회를 갖고 싶어서라고 말합니다. 저는 그가 늙어가고 있다고 생각합니다."
rows["228:998332456"]="나도 농부 숙주가 될 수 있다는 걸 보여줄 거야$B$B이 농장을 밸리의 가장 부유한 농장으로 만들겠다!$B$B한 판다렌이 너무 많은 일이야"
rows["229:1036410759"]="여기서 왜니의 연기를 냄새가 안 안 맡아?  ⁇ 은강을 배우고 싶다면 테룸 딥포르지를 찾아야 해."
rows["229:1044606164"]="컨트롤러를 이용해 연결된 프로토론 가속기를 활성화할 수 있어 바시르의 선보인 중 하나를 불러일으킬 수도 있고,$B$B기기를 활성화할 가속기 모듈이 없으니 아쉽습니다."
rows["229:1189501514"]="이 사람은 다라란의 마법사 아니었고, 그의 옷은 낯선 것 같았고, 그의 억양은 낯설고, 그는 이 시간, 그 시간만을  ⁇ 어들었을 뿐이었죠."
rows["229:1333414984"]="슬픈 소식이 있습니다. 만약 우리가 여기서 패배를 당한다면 이 얼어붙은 황무지에서 그 영향이 느껴질 것입니다. 낙스라마스."
rows["229:1336806675"]="우리 엄마를 복수해야 돼!\010그녀를 죽인 괴물을 방해해 이 구석에서 우리를 해방시켜, 우리는 네 옆에 싸워줄 거야\010적의 피해를 줄일 수 있는 우리의 능력은 원시 베헤모트의 불타는 숨을 살아남는 데 도움이 될 것입니다."
rows["229:1351021961"]="이 신호등을 스노프폴 묘지로 가져가서 보호해 내 기리폰이 잠겨 있을 때까지$B$B제 기리폰이 공격 위치를 알면 무얼프와 그의 승무원이 굴욕당할 거야"
rows["229:1365557166"]="니비로 왔는데 지옥의 종을 몰아내는 비밀을 알아내려고요$B$B니비가 모든 걸 알고 있어$B$B니비는 그런 지식을 빨리 받아들이지 않아 먼저 니비에게 중요한 일을 도와줘야 해"
rows["229:1377790029"]="지혜로운 사람 은 즉시 빚 을 갚아 주지만, 지혜로운 사람 은 언제 속이는지 알 수 있다.$b$b지나는 하루 종일 시장을 다니며 돈을 계산하고 난 외로운 길을 걷고"
rows["229:1455260535"]="스톤플로우를 방어하는 것은 당신이 생각하는 것보다 더 중요합니다.$b$b만약 이  ⁇ 이 돌을 잡으면, 그들은 이 모든 계곡을 빼앗을 수도 있습니다. 이 벽 너머에는"
rows["229:1580556325"]="매일 가죽을  ⁇ 고 살면서 스스로 좋은 가죽을 만들 수 있는 선생보다 더 나은 교사가 있을까요? 썬더 블러프의 우나는 내가 더 많은 것을 보여줄 수 있습니다."
rows["229:1616519770"]="|TInterface\\Icons\\ability_shaman_astralshift.blp:20|t당신의 영혼은 실제 세계에서 자신의 몸에 돌아갈 만큼 치유되었습니다! 당신의 |cFFFF0000|Hspell:120715|h[재생된 영]|h|r 액션 버튼을 사용하여 당신의 영혼을 구하십시오!"
rows["229:1632129802"]="2년마다 경쟁의 영들이 더욱 열렬해지고... 이제 그 때가 되었습니다! 얼라이언스와 호드 모두 이 태블드를 전투장에 착용하여 영들을 기리기 위해 모든 적들을 물리치고 그들의 호의를 얻으려고 합니다."
rows["229:1945644116"]="이 룬스톤은 모가 야만주의에 대해 이야기합니다. 그들은 전사 klan으로 분해졌습니다. 하지만 한 왕은 다른 사람들보다 더 야심찬했습니다. 레이  ⁇ . 천둥왕. 타이탄 경호자가 침묵했을 때, 레이  ⁇ 은 그를 대신하기로 결정했습니다."
rows["229:1993947697"]="박사님께서는 전신이 거의 다 바르굴인 살덩이 거인 네르겔드를 만드는 계획을 내게 맡기셨다! 네르겔드는 네 한심한 병력을 끝장내도록 만들어질 피조물 군단과 살덩이 거인 무리 전체를 통틀어 가장 강력한 존재일 것이다!"
rows["229:291412880"]="리치 왕을 물리칠 순 없네. 여기선 말이지. 그냥 덤비는 건 바보짓이야. 리치 왕은 그대를 따르는 자들을 죽여, 강력한 스컬지 병사로 일으킬 걸세. 그렇지만, 실바나스... 그대에게는 지난번보다 더 끔찍한 일이 닥칠 걸세."
rows["229:397905787"]="하지만 제가 여러분들이 이 계곡에서 돌아온 날, 문이 열릴 때 여기 서 있는 것을 상상해 보세요. 그때에 우리 황제는 순수한 빛의 존재였죠. 의심도 없고 두려움도 증오도 없었어요."
rows["229:473024698"]="래티온은 마지막 살아있는 검은 용이라고 주장하고 있어$b$b그는 세상에서 가장 호기심한 시각을 가지고 있습니다. 나는 그가 인간의 생명을 소중하거나 낭비할 수 있다고 생각하는지 결정할 수 없습니다! 그러나 나는 그와 대화를 즐깁니다."
