rows["230:1133526133"]="우리의 오래된 불화와 결속을 뒤로하고 왕국과 백성들이 한데 모일 시간이다. 절대 이길 수 없을 것 같은 전쟁이 다가왔고 저 높은 곳에서 피난처를 찾아야 한다. 그렇지 않으면 우린 어둠의 홍수에 모두 휩쓸릴 것이다."
rows["230:1184687702"]="나는 상상한 적이 있소이다... 이 축복 받은 수정을 이용해 우리가 무기를 만드는 걸 말이오. 그 무기 속에는 우리 각자의 조그만 힘들이 살아 숨 쉴 것이오... 언데드와 싸울 때 그 무기를 사용하면 언데드가 쓰러질 것이며 싸움이 끝나면 파멸만이 남게 될 것이니..."
rows["230:1263410314"]="일부 랜저들은 스스로 그들의 야생적인 기세를 돌볼 수 없는 것처럼 보입니다. 만약 당신이 단순히 도시에서 어딘가에 이런 것을 보관해야 한다면, 아나토스는 당신의 손에서 그것을 빼앗을 것입니다. 그녀는 호네 밖에서 팔콘윙 스퀘어에서 기다리고 일하고 있습니다."
rows["230:14090953"]="어쨌든, 저는 좀 그림자 속으로 빠져들었어요.$B$B윈저가 너무 우아하지 않았는데, 이미 너무 짜증났기 때문에 "
rows["230:1553760630"]="이 위험하고 예측 불가능 한 직업 은 재앙 이 없을 것 없이 우리 의 순수 한 숲 가운데도 믿을 만한 면 에서 행할 수 없다. 하지만 실버문 시티 자체 를 시도 할 수 있다. 그 벽 은 폭발 을 견딜 만큼 강력 하다."
rows["230:1601106408"]="아나라는 이름이 있어, 그녀가 마땅히 존중하는 걸 잘 해$B$B얼마나 많은 번이나 그녀와 자매들이 죽음을 당한 뒤 다시 데려왔어?"
rows["230:1657615398"]="네 머리는 잘 흔들어야 돼, 내 생각엔 레이 라인이 뇌를 흐리게 해주는 것 같아."
rows["230:1671668932"]="네, 아니, 내가 목격한 자애가 내 마음을 깨끗하게 해줬어 네 주인과의 거래는 끝났어"
rows["230:1798863998"]="반나르 스톰파이크는 알테락에 있는 얼라이언스 군대의 장군이며,  ⁇  발다르에서 그의 군대를 지휘한다.$B$B만약 그가 패배한다면 얼라이언스은 확실히 알터랙의 전투를 잃게 될 것입니다.$B$B반나더는 현재 알테락밸리에는 없습니다."
rows["230:1808236144"]="이 이국적인 도시를 방문한 후, 아마도 여러분도 우리와 함께 축하하는 데 관심이 있을 것입니다. 무롱라데에서 달 축제가 진행되고 있으며, 다른 도시들은 축제에 교통을 가지고 있습니다. 오셔서 다른 축제 참가자들과 함께하세요."
rows["230:1813142474"]="알라니는 가장 큰 번개의 반짝을 볼 수 있고, 가장 큰雷의 반향을 들을 수도 있다고 합니다. 그녀의 관심을 끌고 싶다면, 그녀를 낳은 하늘의 본질을 활용해야 합니다."
rows["230:1816776320"]="제 초등 수업은 항상 밝은 눈의 젊은 소년들로 가득 차 있습니다. 하지만 첫 시험에서 잘 통과하는 사람은 거의 없습니다.$B$B'내가 소리칠 때 사라져라'라는 소리에서 포기했지. 그들은 결코 듣지 않는다. 이제 시험은 단순히 무능한 사람을 죽인다."
rows["230:1853757613"]="나도 마찬가지지만 아직 해야 할 일이 있어 악이 다시 돌아와면 헛되이 될 거야 아제로스 더 오래 참아야 돼 다나스한테 믿어"
rows["230:2053067200"]="공포의 폐허에 발을 디딘다는 것은 지형을 아는 것과 적들의 움직임을 이해하는 것의 소중함을 가르쳐 주었습니다. 목표가 승리이든 생존이든, 가장 좋은 길은 항상 상대보다 두 발자국 앞서 가는 것입니다."
rows["230:2082563651"]="로즐레스가 옷이나 모자를 가져갈 때마다 날 쳐다보는 걸 봤어?$B$B한 번만, 저는 스톰윈드의 모든 고급 타버나를 그리워합니다."
rows["230:2128061045"]="용사들이여, 잘 해내셨군요! 이 방 안에 우리 기지를 세워야겠어요. 곧 마법사들이 스컬지 이동 수단을 준비할 거예요. 다음 임무를 수행할 준비가 되면 그 안으로 들어가세요. 다른 쪽에서 만나도록 하지요."
rows["230:235651638"]="내가 도와줄 수 있을지도 몰라, 사타이르, 이  ⁇ 은 가슴을 되찾고 괴라룩 애브릭크랙을 죽여서"
rows["230:259969215"]="코덱스의 무더운 페이지들은 마법처럼 자기 자신을 돌리고, 어떤 필사적 눈도 결코 감지하지 말아야 할 끔찍한 과거를 특정 장으로 당신의 관심을 유도하는 것 같습니다.$B$B책에서 어떤 면에서는 '옳은' 것처럼 느껴지는 페이지가 열립니다. 하지만, 매우 잘못된 페이지입니다."
rows["230:522956635"]="자연을 지키기 위해 항상 경계하고 있는 드루이드는 센아리온 앙클라브에 거주하는 아르크 드루이드 판드랄 스태겔름이 지도한다. 당신은 그와 다른 드루이드 트레이너들을 다르나서스 북부 섹션에서 찾을 수 있습니다."
rows["230:533524307"]="아주 잘, 나는 블랙 테플로 돌아가 이리던 부왕에게 그의 뜻을 이행하지 않음을 알려줄게"
rows["230:551273896"]="힘든 전투였어 친구들을 잃는 것이 너무 슬프네\010하지만 전 그들이 전투장에서 신선함을 주는 기기를 만들게 되어 기쁘다.\010그 없이, 그리고 내 강렬한  ⁇ 의 힘 없이는, 누가 더 많은 사람들이 잃었을지 모른다..."
rows["230:721873295"]="가젯잔의 랩포르지 엔지니어의 도움으로 토슬리 역에서 강력한  ⁇ 어 운반기를 만들었습니다."
rows["230:734146589"]="난 자네의 조언을 빌어야지 내 친구 내가 가로쉬 옆에 서서 전쟁으로 인해 우리 사람들을 서로 대적하는 동안 호드... 내 사람들을 데려다 줄 수 있는 거"
rows["230:96149912"]="마지막 죽음의 기사인 대영주 모그레인은 죽음의 기사 중에서도 가장 뛰어난 전사였다. 하지만 아제로스에서 일어난 사건 이후로 그는 종적을 감췄지. 켈투자드가 그 자리에 누구를 임명했는지는 아직 밝혀지지 않았다."
rows["230:964489949"]="<프라사부대사를 펄볼어로 인사할 때, 그는 미소 짓는다.>$B$B당신께선 예언이 말한 사람이어야 합니다. 당신을 만나게 되어 영광입니다.$B$B저는 프라사부 대사입니다. 피보시에서 스틸파인 대장의 대표입니다."
rows["231:1152868603"]="내 아들한테, 디온에게 비가 오면 야크를 들판으로 데려가지 말라고 말했어$B$B이제 병든 야크들이 있다는 것은 놀라운 일이 아닙니다!$B$B어이야, 어떻게 그런 멍청한 아들을 키웠어?"
rows["231:125437403"]="지금껏 모두 즐겁게 지내세요? 멋지네요! 아웃랜드 최고의 공연인 다크문 페어에 오신 것을 환영합니다."
rows["231:1309123338"]="내가 에비세라이트를 가르쳐야 돼, 배미가 총을 쏘는 훈련 도마뱀에 가서 악성 공격으로 공격해"
rows["231:1360728234"]="용감한 군인 호드\"내가 당신을 환영합니다! 우리는 확실히 얼라이언스 만약 당신과 당신의 동맹국들이 없었다면$B$B우리가 성곽의 상부 부분에 대한 공격을 시작하기 전에 잠시 쉬십시오."
rows["231:1385469362"]=" ⁇  발다르는 알테락 계곡에서 가장 강한 얼라이언스 권력 지점이다.  ⁇  발다르는 계곡의 북쪽 끝에 자리 잡고 있으며 남쪽으로 모든 진출을 위한 무대지입니다.$B$B ⁇  발다르는 파괴됐고 재건중입니다"
rows["231:1418338594"]="아제로스 최고의 쇼, 다크문 축제에 오신 것을 환영합니다! 지금까지 모두 재미있는 시간 보내고 있다면 좋겠습니다! 네블기어의 다크문 별난 동물원도 들러 보시고 여기 있는 예브와 그의 친구들도 꼭 만나 보세요!"
rows["231:1425809788"]="이 통신사는 북부 스트랭글스톤의 그롬골로 데려다 줄 겁니다.$B$B보통은$B$B가끔은 그냥 망가뜨리거나, 혹은 온몸을 녹지하고 냄새가 나지만, 대부분 안전합니다!$B$B...대부분은"
rows["231:1432615622"]="모든 사람 의 이익을 위해 자기 목숨을 희생 시키려는 분 들 에게는 어떤 말 이도 정의 를 베풀 수 없습니다. 여러분 각 사람 과 함께 싸웠다는 것 은 영광 을 느낀다고만 말할 수 있을 것 입니다. 이제 나가서 축하 하십시오."
rows["231:1520673273"]="내겐 광산 훈련자가 있다고 들었어요 썬더 블러프 북쪽으로 가서 마을을 벗어날 수 있는 길을 따라 올라가면 엘리베이터를 타고 승강장 꼭대기에 올라갈 수 있습니다."
rows["231:1541595279"]="아이언포지의 성벽을 강화하여 도시 붕괴를 막아라!$B$B도시 곳곳에 있는 상자에 벽 장벽을 쌓아$B$B그리고 빨간색 화살표 |TInterface\\Icons\\ABILITY_HUNTER_MARKEDFORDEATH.blp:32|t로 표시된 위치에 배치한다."
rows["231:1584671352"]="10 레벨에서 당신은 클래스 전문성을 선택할 것입니다.\010나중에 다른 클래스 전문성을 선택하기로 결정하면, 당신은 가격에 이전 선택을 다시 설정할 수 있습니다.\010이렇게 하면 추가로 더 비싸게 될 것입니다."
rows["231:1717844171"]="자, 이제 과일을 판매할 때야. 하지만 과일은 먹을 수 없을 겁니다. 금지합니다. 아무도 우리의 과일을 먹지 않을 것입니다."
rows["231:1773731865"]="새 적들을 지켜보고 있어요$b$b직전 트롤들은 모구와 동맹을 맺지만 다른 침략자들은 그들과 싸우고 있습니다.$b$b난 상관없어 그들의 전투는 우리에게 새로운 시체를 가져왔고 스 ⁇ 블레이드는 더 강해졌지"
rows["231:1811939512"]="안녕하세요, 저는 Kwee Q. Peddlefeet입니다. 저는 아제로스의 영웅 중 가장 인기 있는 사람이 누구인지 알아내기 위해 왔습니다!$B$B많은 팬들이 리더를 환영하는 것을 보고 마음이 따뜻해졌지만... 더 따뜻하게 느껴지는 건 뭘지 아세요?$B$B키스!"
rows["231:1911877"]="이건 매력적이지만 무슨 의미일까요?$B$B그 스프리트에서 수집한 자이드는 다음 패널을 채워줄 것이지만, 전체 프레스코를 완성하려면 더 많은 것이 필요할 것입니다.$B$B보석이 다시 작동하도록 수장님께 도움을 주세요"
rows["231:227766560"]="트레사 파르마운틴은 나쁜 날씨를 겪었지만 생존 능력을 알고 있어 정신이 고조해졌어요  \010그녀가 아이언포지의 문 남쪽에 있는 군단에서, 만약 당신이 그녀와 이야기 하고 싶다면."
rows["231:331157206"]="그 이상한 소녀 쇼는 산에서 걸려있어요$B$B아무도 그녀가 어디서 왔는지 모르지만 암살자의 예술에 훈련되어 있습니다.$B$B하루가 되어서야 우리 똥 문제 해결을 위해 왔어"
rows["231:342733"]="야생! 이제 그건 놀라움입니다! 할아버지는 야생 작물을 굴복으로 싸워야 한다는 이야기를 들려주곤 했습니다.$B$B\"Yoonie, 그는 항상 말했다, \"당신의  ⁇ 을 때려 두려워하지 마십시오\".$B$B항상 그가 더러운 사람이라고 생각했어요"
rows["231:354101472"]="그래도 지금 상황이, 여명의 설원 빙하 아래 아서스의 '사촌' 유골이 묻혀 있다는 소리를 들었다고 레톨이 말하던 그때보다 더 어이없진 않네요. 그거 때문이라도 난 당신을 용서할 수가 없어요, 레톨. 진심이라고요... 아서스의 사촌이 어쩌고저쩌고라고요?"
rows["231:444783972"]="또 다른 방해. 어떻게 이런 일을 해낼 수 있을까? 대답하지 마, 내가 당신이 말하는 것을 신경쓰는 것처럼 보이십니까? 우리가 이 곳을 깨끗하게 하고 우리 제국을 확장하려면 절대적인 침묵이 필요합니다!"
rows["231:640392538"]="영혼 착취자 고딕이다. 강령술과 주술의 전문가인 고딕은 눈 깜짝할 사이에 언데드 군단을 불러낼 수 있다고 한다. 그가 인도하면 가장 약한 죽음의 기사조차도 시체를 일으킬 수 있지."
rows["231:715289487"]="\"순례자의 보너스\". Hrm. 나는 Tauren의 그들의 감사의 감각을 표현하고 공감대를 이해할 수 있습니다 호드의 전쟁 대장, 하지만 포세이큰?$B$B저는 그들이 이런 감성적인 전통을 오래 전에 포기했을 것이라고 상상했습니다."
rows["231:741622570"]="호드와 얼라이언스 두 선장은 모두 현장에 나섰다. 우리 선장은 얼음혈 군에서 얼음 늑대를 지휘하고, 그의 라이벌인 발린다 스톤헤어트 선장은 스톤헤어트 전지대에 숨어있다.$B$B전투가 시작됐어!"
rows["231:844518577"]="당신이 물어본 것에 반갑습니다. $3233w 우리의 예측의 %입니다.$B$B배틀메이지 아리나와 하빈거 인우루가 당신의 도움이 필요하다는 걸 알고 있습니다."
rows["232:1034626849"]="나 나블리아, 카즈고로스의 연습생이자 언고로 크레이터의 파견자.$b$b저는 이제 제 주인 대신 서 있습니다. 아제로스그는 한때 그의 많은 창조물을 형성할 때 바로 이 자리에 서 있었습니다."
rows["232:1090680079"]="파손된 놈의 시체가 여기 있고, 신비롭게도, 그 사망 원인은 변종된 나비들 중 한 명일 것 같지 않다.$B$B아마도 그 이상한 물체가 그 팔 옆에서 서 있는 것과 관련이 있을지도 모릅니다."
rows["232:138536661"]="저는 그녀의 여주인 고야의 \"복귀 전문가\"입니다. 이 길에서 여행의 흐름을 이끌어내는 것은 그녀의 의지입니다.$b$b제가 맡은 일은 덜 신중한 사람들이 그녀의 호평을 이용하지 않도록 하는 것입니다."
rows["232:1452666819"]="크론톤 입자의 흔적을 찾아보고 있습니다. 만약 우리가 역 단계 인도서를 사용한다면, 우리 자신의 시간대 구도를 뒤집어 놓을 때"
rows["232:1469948823"]="매트릭스 펀코그래프 기술  ⁇ 리스트 오 미터는 엔지니어링에 대한 당신의 능력을 검출했습니다. 이제 다음 옵션 중 하나를 선택할 수 있습니다.\01001000111 01101111 00100000 01100111 01101111 00100000 01100111 01101111 00100001 00100001"
rows["232:1501493589"]="<모티스는 하늘을 바라보고 있다.>$B$B어떤 면에서는, 저는 루크와 코르바크스가 누리는 자유를 부러워합니다. 지구적인 책임에서 자유로워지는 것은 정말 큰 축복입니다.$B$B미래는 날개를 다시 볼 것입니다. 하지만 먼저 제가 해야 할 일이 있습니다."
rows["232:2008846667"]="싸움이 죽이고 죽이는 것이 전쟁으로 이어지는 것은 거의 모든 고객들의 종말이었습니다.$B$B이제, 사람들이 싸우고 나면, 여기서 벌어지고, 여기서 끝나는 거죠."
rows["232:2098765218"]="강 위로, 물론!$b$b강 위로... 블루스카이 로그그인드에서 셔더를 만들고 있는 걸 알 수 있어$b$b만약 그가 더 많은 반작을 보내면 강에 떨어질 거라고 말해줘!"
rows["232:2143333993"]="맥스나는 오래전에 노스렌드의 깊은 산 속에서 태어났다. 그녀는 공포의 요새 낙스라마스로 잡혀가 거기서 새끼를 낳아 기르고 있다. 무모하게 낙스라마스에 침입한 자들의 시체를 먹이면서 말이지."
rows["232:289247724"]="다르나서스에서는 오랜 기간 동안 훈련과 헌신으로 자신의 선택된 수업의 기술을 완성한 숙련된 트레이너들을 찾을 수 있습니다."
rows["232:305112273"]="일리단은 날 찾아내서 잿빛혓바닥 결사단의 비밀을 모두 캐내겠지. 배신자의 능력이란 그런 거니까! 이제 한 가지 방법밖엔 없어. 이번 일에서 내 몫은 여기까지네. 난 영혼의 세계로 떠나야 해."
rows["232:429236387"]="크루사드들의 핑클을 점령하는 것은 길고 위험한 여행의 첫 단계일 뿐이야. 아이스크로운 성곽을 공격하기 전에 해야 할 일이 많이 남아있다.$B$B당신과 같은 다른 사람들의 도움만 가능해지죠, 영웅"
rows["232:4369530"]="이 이야기는 전설의 이야기이고, 전 시간도 없고, 재고할 의향도 없습니다. 메디브가 후자의 경호자였다는 것을 알고 있습니다. 아티쉬의 대장들은 그의 힘의 중심점과 부패의 중심점이었다."
rows["232:465885741"]="이 기구들은 훌륭한 기계장치입니다. 저는 실제로 그 기구와 꽤나 친해졌습니다. 심지어 브루스라는 별명을 붙여줬습니다.$b$b항상 제대로 작동하지 않습니다. 약간 뚫어져 있습니다. 그리고 10마일 이내에 있는 사람들에게는 위험할 수도 있습니다."
rows["232:541518388"]="네, 네!$b$b나를 보고 이 만남을 소중히 여기라 곧 세상은 윌프레드 피즐뱅의 이름과 엄한 얼굴을 알게 되고 두려워하게 될 것이다! 나의 위대한 소환이 완료되면, 아무도 내 능력에 의심을 갖지 않을 것이다!"
rows["232:564940853"]="지아오 죽고 시야 죽고 류 죽었어\010수나는 진정하라고 조언하지만 명예는 다른 것을 요구한다.\010타란 주가 수도원에서 안전해 우리 혼자 수로를 방어하는 동안 왜 우리를 막아주지?\010이런 질문들은 저를 괴롭히고 있습니다."
rows["232:619738835"]="지금, 우린 전투에 걸려있어요$b$b난 당신이  ⁇ 마시 공학의 놀라운 것들을 배울 수 있는 열정을 사랑하지만, 아이언포지."
rows["232:793442581"]="브리즈트!$B$B보안 레벨 베타 터미널인 매트릭스 펀코그래프 3005 스트로크 B에 오신 것을 환영합니다.$B$B터미널 기능에 접근하기 위해 노란색 펀치 카드를 가져야 합니다.\01001000111 01101110 01101111 01101101 01100101 01110010 01100011 01111001 00100001"
rows["232:816658512"]="달라란의 멸망과  ⁇ 탈라스의 파괴 이후 이런 상품은 찾아보기 힘들었지만 루칸 코델과 다른 상인이 우리의 주문을 질 높은 상품으로 채우는 데 훌륭한 일을 해왔습니다."
rows["232:833754559"]="아직도 모르겠나, 젊은이? 넌 네 아버지가 맞서 싸우던 적이 되었다! 저 겁쟁이 아서스처럼, 너도 어둠에, 분노에 무릎 꿇고 말았구나. 고문당하고 죽임당한 사람들의 고통을 먹고 사는 괴물이 되었어!"
rows["233:1067272462"]="드렉타르는 얼스트울프 클랜의 군사적, 영적 지도자이며 얼스트울프 킵에서 형제들을 이끌고 있습니다.$B$B만약 그가 패배한다면 알테락의 호드 세력은 붕괴될 것입니다.$B$B드렉타르는 현재 알터랙밸리 안 있어"
rows["233:1140117292"]="예, 예, 저는 하이갈이나 실리투스나 레지온의 행진을 잊지 않았죠. 아니면 7번째 레지온이 직면한 다른 모든 악의적 대립을요."
rows["233:1365120022"]="<대장사의 이미지는 당신을 바라보는 것보다는 당신을 바라보는 것 같습니다.>$B$B이 곳에는 신비한 에너지의 리본과 흐름이 흐르고 있습니다. 마치 마법의 바다에 침투한 것처럼."
rows["233:1502429586"]="이 호드 많은 배반을 저장하고 있습니다. $2079w 이 중 $2080w 울타리 붕대가 수집되었습니다. $2085w 이 중 $2086w 마그 웨이브 붕대가 만들어졌습니다. $2089w 이 중 $2090w 룬복 붕대가 수집되었습니다."
rows["233:1507319219"]="잠시만요, 여기 기억해야 할 숫자가 많아요. $2066w 이 중 $2067w 그리고 우리는 $2070w 이 중 $2071w 두꺼운 가죽, 그리고 $2073w 이 중 $2074w 가죽이 쌓여있으니"
rows["233:1510591388"]="네가 옳다고 생각하는 걸 해야지 마커스, 우린 투랄리온 밑에서 함께 일했고 그는 우리 둘을 지금의 사람으로 만들었다 얼라이언스영웅들을 부끄럽게 만들까?"
rows["233:1796583168"]="용의 종류가 아닌 한 사람 이 장려 된 승천 봉인을 획득하고 보호된 장벽을 통과할 수 있습니다. 그러한 장품이 있으면 저를 확실히 파괴할 것이지만, 아마도 당신은 그것을 활용하여 장벽을 낮추는 것이 좋을 것입니다.\010"
rows["233:1988962385"]="전에 샘플링한 꿈의  ⁇ 은 당신의 의식을 확장시키고, 전국의 현상을 보여 줄 수 있습니다.$b$b하지만 먼저 새로운 배치를 만들도록 도와줘"
rows["233:2094354780"]="앞에는 알려지지 않은 기기의 큰 장치가  ⁇ 니다.\010|TInterface\\Icons\\inv_gizmo_02:20|t |cFFDD2222[고블린-티탄 제어 모듈]|r\010음성 인식 모듈이 보호하고 있는 것 같습니다."
rows["233:211203791"]="우린 산을 가로지르는 모든 길을 알고 있습니다.$b$b우리는 대부분 동쪽의 큰 성벽으로 물품을 가져오고 있습니다.$b$b하지만 지금은 어두운 시간이고, 거무는 우리 길에서 큰 위험에 직면합니다."
rows["233:400160681"]="방문자, 모험가야, 이쪽으로 관광객이 많이 오지 않는데, 의자와 술을 잡아서 편안하게 지내세요. 마치 뼈에 고기가 있는 것처럼 보이시죠."
rows["233:533948746"]="불가 가라앉았을 때, 호수 중심에 구름 뱀이 날고 있는 것을 볼 수 있었습니다. 그 척추는 폭풍과 불로 발발했고, 날아간 곳에는 하늘에는 큰 구름이 형성되었습니다."
rows["233:654338533"]="왕자님께서 노하실 줄은 알았지만, 난... 제정신이 아니었어. 그들을 풀어줄 수밖에 없었다고! 봐, 위대한 분께서 말씀하시잖아! 잠깐... 캘타스 왕자님께서 보낸 자들이 아니잖아! 좋았어... 네놈들이 죄수를 풀어줬다고 일러바치면 되겠군!"
rows["233:867518907"]="<만장사자는 당신을 바라보고 있는 것처럼 당신을 바라보고 있습니다.>$B$B어쩌면 다른 방법이 있을지도 몰라... 내가 요구하는 대로만 하면...$B$B여러분의 도움으로 우리는 서로를 크게 도울 수 있을지도 모릅니다.\010"
rows["234:1022831073"]="당신들은 나보다 더 잘 알고 있습니다. 그건 확실합니다. 뭐라도 해봐요. 나와 이야기 해 주세요. 그는 당신들을 증명하기를 원할 것입니다. 하지만 그는 정말 훌륭한 교사입니다. 그의 이름은 로트가트, 당신은 그를 발견 할 것입니다."
rows["234:1160726417"]="당신 눈에서 볼 수 있듯이, 스트라톨렘의 비극은 여러분도 모르는 일이 아닙니다. 만약 당신이 그 안에 갇힌 가난한 영혼들의 불행한 존재를 끝내고 싶다면"
rows["234:1258248877"]="그들은 날 피하고, 내가 그들의 방어선을 볼 수 없습니다. 그들은 발견을 방지하기 위해 방지를 설치했습니다.$B$B<다른 지점은 서쪽으로>$B$B그들은 우리를 두려워합니다. 왜냐하면 그들은 우리가 아무것도 두려워하지 않는다는 것을 알고 있기 때문입니다. 그러한 힘의 비용은 매우 크며 많은 희생을 합니다. "
rows["234:1705618689"]="내가 칭찬을 받았지만, 정말 관심이 없어요... 마법을 어디서 배울 수 있는지 알고 싶으세요? 어, 어색한 것 같아요."
rows["234:171368465"]="스톰윈드 에서 술 을 마실 수 있는 많은 곳 이 있지만, 그 중 한 곳 만 에만 밤 을 보낼 수 있습니다. 무역 구역 에 있는 골든드 로즈 로 이동 하십시오. "
rows["234:1755183950"]="이 모든 호드오크들, 특히 워싱글에서 전투가 많을 거 같아"
rows["234:1822707637"]="디자이너가 어떻게 직물을 묶는지에 대해 많은 것을 알 수 있습니다. 당신의 것은 자부심을 넘어서 기능적인 모습을 가지고 있습니다.$b$b마나로 단단히 봉착되어 직물 안에 삽입되어 있습니다. 예술적인 손으로 인해 이득이 될 수 있지만 인상적입니다."
rows["234:1888812372"]="제 아버님께서는 부대 모두 운이 다했다고 생각하셨지요... 그런데 제 아버님 뒤에서 격렬한 고함이 눈밭 전체에 걸쳐 들리더니 돌과 같은 조직으로 자신의 피부를 바꾸고는 손에 일어난 번개가 뜨겁게 타오르며 몸 크기가 커진 산악 드워프의 모습을 보게 되셨답니다."
rows["234:2051730192"]="이 단위는 정상적인 운영 프로토콜 이외에 활성화되었습니다. 새로운 운영 매개 변수를 다운로드 합니다. 다운로드 완료. 전체 단위 자 방어 루틴이 현재 활성화됩니다. 시스템 내 외국 단위의 파괴는 이제 시작됩니다."
rows["234:2055360831"]="며칠 전 웰거에서 죽은 맹수들의 뼈에서 타이탄 유물을 해방시키려고 했는데,  \010그는 죽은 사람이 아니니까 살아있지 않겠지만, 존재하군"
rows["234:2061332156"]="불! 그것은 가장 마법의 요소입니다. 우리를 따뜻하게 하고, 우리의 음식을 요리합니다. 가옥을 가정으로 만드는 화소입니다. 오른손으로는 불은 칼이나 벼룩으로 철을 형성 할 수 있습니다. 통제되지 않으면 불은 도시를 파괴 할 수 있습니다."
rows["234:240566389"]="자몽, 나는 물고기-어머니를 수집 호드그들은 사막에서 큰 전쟁에 준비하고 있습니다. $2103w 하지만 지금 우리는 단지 ' $2102w- 도와줄게?"
rows["234:303479584"]="인생은 투쟁이고, 당신을 죽이지 않는 것이 당신을 강하게 해주는 말이 항상 사실이 아닙니다. 때로는 상처가 느리게 작용하는 것이 있습니다. 그래서 우리는 붕대를 가지고 있습니다."
rows["234:679436532"]="오그리마의 무기 마스터인 사요크와 한아시는 던진 무기의 진정한 공예가 된다. 그들은 명예의 계곡에서 기꺼이 학생들을 훈련한다. 예술의 순수한 미련을 위해, 그러나 실버문의 이레다는 파스트라이더 광장에서 이길 수 없다."
rows["234:749527612"]="여기 있는 나에 놀랐나? 모든 사람이 깨끗한 빨래를 필요로 하고,$B$B그냥 세탁물을 가져와 명목적인 수수료를 지불하고, 그리고 당신이 그것을 깨닫지 전에, 모든 것이 신선하고 깨끗하게 될 것입니다!"
rows["234:785243950"]="우리 부족의 유물을 되찾고, 고대 적인 블래데스파이어 오그스와 그론 마스터들과 싸우며,"
rows["234:807637158"]="우리는 그들을 시야에 있었다 호드 배들... 그리고 아무 곳에서도, 템팩클은 손을 잡고 우리의 배를 잡았다...$b$b생존자들은 물에 닿자마자 나가에게 잡혔습니다.$b$b거의 일주일 전이었죠"
rows["234:869787633"]="아무도 말해주지 마, 스컬지는 패배한군.$b$b내가 싸울 수밖에 없어 마지막 숨까지 싸울 거야"
rows["234:934802603"]="뭐 물어볼게 있어? 그는 원숭이야 미친 바보야. 어쨌든, 예, 원숭이는 브랜의 얼굴에 먼저 떨어지는 것을 보고 광기에 빠졌어. 밤 elf가 할 수 있는 것은 Glibb이 여기에서 그녀의 noggin에 가파른 것을 막는 것이 아니었다."
rows["235:1309616521"]="당신은 스스로 잘 해냈다고 볼 수 있지만 천상의 토너먼트에 참가하려면 리더로서 자신을 증명해야 합니다. 15개의 전투 애완 동물을 최대 수준으로 데려가면,"
rows["235:1326908221"]="요즘은 개들은 가까이 오지 않아요. 전 짐승을 좋아한다는 걸 알게 되면서 정말 실망했어요.$B$B하지만 파급호우들은 좋은 대용품이니까 눈에는 그리 편하지 않지만, 나도 그렇지"
rows["235:1534605520"]="내가 무슨 말을 하겠냐? 그녀는 곧바로 대목으로 달려갔고, 더 미친 건 뭐지 알겠어? 한 개도 걸리지 않았거나, 그녀를 막으려고 하지 않았어."
rows["235:1588860633"]="넌 잘 배워왔어 내 아들아, 언더시티에 가서 제임스 반 브런트라는 도자기들을 찾아라. 저한테는 못 할 많은 것을 가르쳐 줄 수 있을거야."
rows["235:1685240551"]="우리는 빨리 움직여야 합니다! 티리고사와 그녀의 경호가 쓰러져 성전을 무방비하게 남겨두고 있습니다. 죽음의 날개의 세력은 용 영혼에 도달해서는 안 됩니다. 아니면 모든 것이 손실됩니다."
rows["235:1746924039"]="지시어. 고대 신. 고대 신들은 동화 작업을 용이하게 할 목적으로, 토석인을 포함한 모든 생명체에 무력화 작업을 수행했습니다. 이 모형 불안정화 작업을 \"육체의 저주\"라고 부릅니다. 불안정화 작업의 효과는 시간이 지날수록 증대되었습니다."
rows["235:1921721909"]="행운의 사람이나 장소가거나 행운의 물건이 되는 이유$b$b불쌍한 사람이라고 부르는 것은 거꾸로 칭찬을 하는 것입니다.$b$b보통 운의 냄새가 나기 때문에 운은 향으로 찾아볼 수 있습니다."
rows["235:1942689813"]="|cff6600aa 희귀 도전자:|r\010  에피쿠스 막시마스: $7385w-$7386w\010  디스프로트론: $7417w-$7418w\010  밀하우스 마나폭풍: $7401w-$7402w\010  젠샤르: $7409w-$7410w\010  조카 그럼플플로트: $8040w-$8039w\010  마스터 붐 붐: $8044w-$8043w\010  타이타르: $8046w-$8045w"
rows["235:1944800284"]="근처의 농부들은 밀을 가져오고, 우리는 곡물을 여기로 깎고 분류합니다.$B$B곡물 중 일부는 먹거리로 만들어지고, 일부는 거래되고 있지만 대부분은..."
rows["235:2015614852"]="운명이 저주받은 것 같지?$B$B때로는 좋은 분위기를 유지하려고 노력하는 것뿐이고, 어쩌면 운의 변동적인 전환을 경감하는 것만으로도 가능하죠."
rows["235:2082253176"]="|cff6600aa 희귀 도전자:|r\010  에피쿠스 막시마스: $7385w-$7386w\010  디스프로트론: $7417w-$7418w\010  밀하우스 마나폭풍: $7401w-$7402w\010  젠샤르: $7409w-$7410w\010  조카 그럼플플로트: $8080w-$8079w\010  마스터 붐 붐: $8084w-$8083w\010  타이타르: $8086w-$8085w"
rows["235:2133186765"]="<클라리스는 시체를 쳐다보고 눈은 비어있어요>$B$B뉴스가 도착하자마자 테라모어에서 왔어요$B$B존과 저는 분쟁이 가라앉을 때 항상 평화롭게 살 수 있다는 이야기를 했습니다.$B$B난 싸움은 끝나지 않을 것 같아"
rows["235:2138416560"]="어리석은 짓으로 자기 자신의 죽음을 추구하고, 무모하게 자기 이해가 넘치는 힘을 무시하고, 포수자의 영역을 침략하기 위해 열심히 싸웠고, 이제 유일한 길은 저주받은 사람들의 외로운 길을 걷기 위해서다."
rows["235:621421946"]="빨리 배우는 사람이나, 잘 할 수 있는 수리자라면, 일상의 어느 날에도 이 일을 할 수 있겠지만, 아직 배울 수 있는 부분이 있다고 생각합니다."
rows["235:972286451"]="네 개의 사원을 지키면, 당신은 오전 천성들과 큰 지위를 얻게 될 것입니다.$B$B게다가, 당신은 이 땅을 우리의 가장 큰 적들로부터 방어하는데 도움을 줄 것입니다."
rows["236:1196689245"]="많이 놀랐나? 고대 신의 힘이 꿈속까지 미칠 것이라고 믿기 어렵겠지? 하지만 사실이다. 꿈의 폭군 에라니쿠스는 우리 모두를 상대로 싸움을 걸고 있느니, 그가 파괴하고 지나간 곳에는 악몽이 뒤따른다."
rows["236:1484874975"]="안심하세요, 사병님, 제가 네더가르드에 보낸 마지막 사신이 못 왔어요. 몇 시간 전에 그의 내장들이 뼈로 흩어져있었거든요. 호드..."
rows["236:1496290952"]="실리더스를 향한 첫 번째 침공을 지휘한 자는 라작스 장군으로 알려진 강력한 퀴라지였습니다. 이들의 진군을 막아선 유일한 인물이 있었으니 그는 바로 스태그헬름이라고 하는 나이트 엘프였지요. 퀴라지들은 그를 카르시스 또는 자신들의 언어로 '대지의 손'를 뜻하는 이름으로 불렀습니다."
rows["236:1588914842"]="카라잔의 멸망 후 키린 톨은 마법을 파견하여 탑을 조사하고 \"연구\"를 위해 수입된 모든 물건을 압수했다."
rows["236:1702050345"]="이 로봇들은 내가 발명한 것에 대해 역사 속으로 기록할 것입니다.$b$b물론 몇 가지 부작용이 있지만, 적어도 이것은 거미를 다루는 방식보다 더 좋은 해결책입니다.$b$b잠시 동안 집을 태워버린 후 실용적이지 않은 것 같네요!"
rows["236:2018129796"]="얼음주인 아후네는 막아야 합니다.\010지금도 그는 형상을 취하고 있습니다. Twilight's Hammer의 미친 신파들에 의해 그의 기본 감옥에서 소환되었습니다.\010만약 그가 우리 세상에 완전히 들어갈 수 있다면, 그는 영원한 겨울에 우리를 묻어 버릴 것입니다."
rows["236:2091840455"]="우리 중 한 사람이 아니라 그들 중 한 명일 뿐이야$b$b내가 널 따라다니며 지켜보고 있어 우리 사람들을 죽이는 건데, 모고를 죽이는 것도 마찬가지야$b$b누가 죽인지는 신경쓰지 않아서 고기를 가져가야 돼"
rows["236:276099709"]="우리 모두 함께 일하면서 큰 일을 해냈고, 이제 더 큰 일이 직면해 있습니다. 우리는 단지 호드의 모집 노력이 완료될 때까지 기다립니다. 그리고 나서 우리는 모두 함께 실리티드와 그들의 주인들을 마주하게 될 것입니다."
rows["236:29934621"]="내가 마법사처럼 보이시나요? 케인 파이어송이 남동쪽의 겔로우스 엔드 타버너의 상층 상륙에 걸렸다고 들었는데"
rows["236:360269828"]="창조자들은 창조자들이야$B$B그들은 이 세상을 자기 자신 의 계획 으로 심어 그 를 형성 한 존재 들 이다. 그들은 이 세상 과 다른 많은 세상 의 존재 의 이유 이다. 그들은 아제로스의 샘물 이다."
rows["236:450520236"]="진정한 십자군은 악과의 싸움에서 영웅이 아닌데... 그는 모범이며, 이 일에 동참하는 자이며, 그의 모든 사람들의 눈에는 챔피언입니다.$B$B십자군으로서, 이런 남녀에게 가치 있는 임무를 맡기는 것이 제 의무입니다."
rows["236:545819864"]="내가 쉽게 인정하지 않지만, 넌 나보다 훨씬 더 좋은 수匠이야. 스톰윈드왜니들 구역에서 찾을 수 있어요"
rows["236:641188657"]="스팀위들 전투 회장은 아직 순위 경기에 참가할 수 있는 아레나 팀의 자격증을 판매하지 않습니다.\010아레나 배틀마스터를 찾아 연습을 할 수 있어 훈련하기엔 너무 일찍이 안 돼"
rows["236:715722694"]="\"우리 의 허리 는 모구 의 지팡이에 굳어 있다. 우리 의 팔 은 그 들 의 요새 를 짓는 데 힘 이 있다. 우리 의 마음 은 적 과 함께 일 하기 에 능하다. 당신 은 모구 가 더 강하다고 생각 합니까? 우리 는 그 들 의 힘 이라고 말 한다!\""
rows["236:882010943"]="이 포스터는 위험 활동에 대한 다양한 알림과 보상이 있습니다. 하지만, 아직은 특별히 당신이 잘 맞았다고 느끼는 것은 없습니다.$B$B나중에 다시 확인해 볼까요?"
rows["237:1074991987"]="정말 뭐가 뭔지 모르겠군요. 지금 이 상황은, 레톨 당신이 우리는 사실 어떤 상상의 존재이며, 우리가 단지 그들의 즐거움을 위해 존재한다고 말하던 그때보다 더 화가 나지는 않아요. 가족과 함께 식사를 하는 동안엔 잘 넘어갔지만 말입니다."
rows["237:336392297"]="급여 징수에 대해 알고 싶으세요? 호드 준비했었지 $2095w 이 중 $2096w 얇은 늑대 스테이크도 준비했어요 $2102w 이 중 $2103w 얼룩진 노란색 꼬리 $2105w 이 중 $2106w  ⁇ 은 살몬이 필요했습니다."
rows["237:433071456"]="일리던의 악마들이 나를 다시 노예로 만들지 않으면, 장갈마르쉬의 나가도 그럴 것이다.$B$B이리던과 그의 동맹군들과 함께하는 것은 대부분의 깰 부족들에게 노예제도를 의미하지 않는 것으로 밝혀졌습니다."
rows["237:476523471"]="그 남자는 바보야!$b$b명예, 부자, 이 곳은 죽음의 함정일 뿐이야$b$b전 전 시대에는 온갖 트롤을 봤지만, 이들은 다른 사람들이죠.$b$b그들이 우리가 올 줄 알았던 것 같았어요\010"
rows["237:554118130"]="브론크가 계속  ⁇ 어왔던 모든  ⁇ 이 있긴 하지만, 저한테도  ⁇ 어줄 수 있어."
rows["237:812468872"]="\"전쟁에 필요한 자원을 수집하는 좋은 일\" 라고 말했고 \" 승진을 받으세요\" 라고 말했어요. 그들이 정말로 의미하는 것은 \"당신은  ⁇ 스에서 땀이 나는 왜쟁이들과 함께  ⁇ 스에서  ⁇ 스 앞에 서 있습니다!\"$B$B승진해줘서 고마워요, 캡틴!"
rows["237:863246585"]="그 위장이 가능해지는 마법은 몇 분만 지속될 거야 내가 널 블랙마우 홀드의 중심으로 이동시켜"
rows["237:902118843"]="내가 쓰러질 수도 있지만, 다시 일어서게 될거야 여기 와서 내가 가진 것을 봐라. 가장 희귀하고 멋진 Amulet, 바로 여기! 나는 심지어 몇 조각을 더 많이 가져왔어!"
rows["238:1084327188"]="스피네브레이커 포스트는 기소하기 좋은 곳이야! 피하는 홀로의 변칙은 너무 가까이 있어 그들의 불쾌한 피를 냄새가 맡을 수 있어! 포세이큰 그들의 형제들과 사탄과 계약을 맺었느뇨"
rows["238:1098807948"]="와일드햄어, 그래폰 라이더, 만약 당신이 어떤 지각을 가지고 있다면! 그림자 달은 에리 픽이 아닙니다, 하지만 우리는 여전히 좋은 물량을 가지고 있습니다. 네, 좋은 물량을 가지고 있습니다. 내 아름다움을 살펴보고 그들 중 하나가 당신의 눈을 사로 잡을 수 있는지 확인하십시오!"
rows["238:1210334173"]="선워커, 난 네 사람들을 존중해. 넌 샤와 번둥왕에 대한 캠페인에서 우리를 도와줬어. 그렇지 않으면 나는 이미 Shado-Pan에게 이 신전을 깨끗하게 해소하라고 명령했을거야. 하지만 내 인내는 끝났습니다. 호드은 떠나야 합니다."
rows["238:1321905240"]="놀라운 Amulet, 믿을 수 없는 호기심, 신규 주얼리 세술가들은 새로운 이주된 그리파의 시도와 진정한 신비한 방법들에 대해 아무것도 알지 못해"
rows["238:1326348811"]="오그레들은 내 목까지 묻고 다시 돌아오는 것을 잊어 버립니다.$B$B웃기게, 무신한 유령 머리가 있어$B$B물론, 당신이 도와주고 싶다면, 내가 당신의 시간을 보아야 할 것입니다.$B$B하지만 웃지 마세요"
rows["238:1382779597"]="나가 사냥을 하려면, 당신이 얻을 수 있는 모든 도움 이 필요할 것입니다. 물 속 깊은 곳 에는 거품 있는 균열이 발견 될 수 있습니다. 거품 을 사용할 수 있도록 물 아래에서 숨을 쉬는 충분한 공기 거품 을 생성 할 수 있습니다."
rows["238:1695487374"]="로드모어와 그의 사람들과 함께 떠나서 지금까지 이렇게 좋은 칼을 본 적이 없어요. 더 많은 것을 가르쳐 줄 수는 없지만, 보르고스 스틸핸드를 찾아내면"
rows["238:1857564617"]="새 챔피언들에게 호로라! 당신은 당신의 내면의 힘을 보여주었고, 그것은 당신이 키운 사람들에게 반영됩니다. 그들은 그렇게 강한 지도자를 가지고 운이 좋았습니다."
rows["238:1864858140"]="아르크마지 알바레우스는 한때 흥미로운 이론을 탐구하는 논문을 썼습니다. 그는 카라잔의 정확한 복사본이 우리 세상 이외의 세계에서 존재한다는 것을 제안했습니다. 그리고 둘 다 어떻게든 같은 공간을 공유했습니다.$B$B곧 미쳤어"
rows["238:1884268790"]="당신은 매우 호기심이 많지만, 그러한 호기심이 일반적인 이해 부족을 부정하지만, 제가 이렇게 말하는 이유는 여러분이 여기에 있는 데 확실한 목적이 있다면, 여러분이 묻는 질문은 무의미한 것처럼 보일 것이기 때문입니다. $B$B그 덕분에 좋은 하루를 보내고 있습니다."
rows["238:1923877673"]="우리가 이 일을 하고 있다는 걸 믿을 수 없어 캘린더의 존재가 우리 모두를 위협하고 있다는 걸 알고 있지만, 정말?$b$b왜 토리움 형제단들이 항상 날 구해야 하는 거야?"
rows["238:2037434051"]="그들은 피로 얼룩진 눈밭을 헤치며, 그들이 이해할 수 없는 방언으로 얘기하며 방랑하는 한 드워프를 찾고자 흔적을 따라갔습니다. 그 드워프는 당신네 종족을 싫어하는 우리 같은 드워프가 아닌, 우리 동족이 전에는 보지 못한 산악 드워프였지요."
rows["238:2041385755"]="이 의식이 끝나면 다시 시작될 수 없고 부패가 계속 될 것입니다. 여러분의 용기는 존경할 만한 것이지만, 실패하면 우리 모두 멸망당합니다."
rows["238:2097832029"]="난 토끼발 형제, 상인, 여행자 그리고 거무는 행운의 친구$b$b평화의 시대를 $p 제 상품을 구매하는 것이 좋겠지만 운은 오늘 만나게 해줬습니다.$b$b우린 함께 할 일이 많아요"
rows["238:381865427"]="왜, 그래, 크로미가 이걸 필요로 하는가?$b$b네, 그럴 수도 있습니다. 그 페이지들을 자유롭게 읽어보세요. 그 안에 여러분은 다로우셔의 역사를 발견할 수 있고, 많은 사람들의 죽음을 초래한 사건들의 세부사항들을 찾을 수 있습니다."
rows["238:411833233"]="이곳에는 강한 괴물들이 많습니다, 여행자님. 살아남으려면 충분한 탄약이 필요할 겁니다. 제 가게에는 좋은 화살, 총알, 그리고 투척용 무기들이 잔뜩 구비되어 있으니 손님께선 운이 좋으시군요. 주위 환경을 고려한다면 이 가격도 싼 편이랍니다."
rows["238:566439"]="제이드 숲에서 일어난 일은 끔찍한 비극이었습니다. 저는 우리의 실수를 반복하지 않는 유일한 방법은 그것으로부터 배우는 것이라고 굳게 믿습니다.$B$B이 도서관에는 많은 지식들이 있고, 이미 저는 샤에 대해 많이 배웠어요."
rows["238:604114640"]="잠깐만요, 난... 너 정말 좋은 친구였어 그리고 내가 좋아하는 고양이인 루나를 선물하고 싶어"
rows["238:625962207"]="하지만 얼마 후 샤트라스는 또다시 공격을 받았습니다. 이번에는 일리단의 군대였지요. 일리단의 동맹인 캘타스 선스트라이더가 수많은 블러드 엘프들을 보내 샤트라스를 파괴했습니다."
rows["238:648201167"]="난 당신과 렉스사르를 지켜봤어 호드 오그르들이 굴복하고 그들의 주인인 드래곤 킬러 그루를 죽이면만 당신의 사람들은 안전할 수 있습니다."
rows["238:718160505"]="왕은 안두인 왕자가 회복될 때까지 계곡에 머물러 있기를 원했지만 왕자는 사람들에게 이야기하며 돌아다니기를 주장합니다.$b$b가까이 있어서 곤경에서 벗어나면 좋겠어"
rows["239:1220094573"]="만나서 반갑습니다. 저는 지지입니다. 스 ⁇ 트라트에서 현직 마법사  ⁇  전문가가에요. 경쟁이 없죠. 하지만 만약 당신이  ⁇ 사  ⁇ 사가 되고 싶지만 전문적인 일을 하지 않은다면, 저는 도움을 줄 수 있습니다."
rows["239:1229957752"]="많은 것을 배웠지만, 영들이 더 많은 것을 가르쳐 줄 수 있다고 느낀다. 나는 당신의 발을 길 위에 놓을 수 있지만 당신의 발걸음을 인도할 수 없습니다. 오그리마에 가서 사루 스틸푸리를 찾아라, 당신의 여정의 다음 부분은 거기서 시작됩니다."
rows["239:1282360657"]="호네? 아, 당신은 최고의 알루를 던질 수 있습니다 아이언포지 스톤파이어 타버너가 당신이 가고 싶은 곳이야  $B$B너희가 오는 경우, 아이언포지의 왼쪽 입구에서, 또는 오른쪽으로 가면,"
rows["239:1445564188"]="호드와 얼라이언스 두 선장은 모두 현장에 나섰다. 우리 선장은 발린다 스톤헤어트가 스톤헤어트 포스트에서 스톰파이크군을 지휘하고, 적은 갈반가르 선장은 아이스블러드 가리소에서 명령을 짖는다.$B$B전투로!"
rows["239:1463045048"]="이 전쟁의 부담으로 내 마음이 무겁고 내 백성들을 죽게 해 주지만 지금 라그나로스를 견디지 못한다면$B$B우리가 가진 모든 것을 가지고 싸워야 합니다. 아니면 우리 세상이 파괴되는 것을 목격해야 합니다."
rows["239:1482869427"]="낚시를 시작한다고 비난하지 마십시오. 멀고어은 남부에서 가장 좋은 낚시 장소를 가지고 있습니다 칼림도어 그리고 높은 상승에서 Mountaintop Bait & Tackle는 당신이 그것을 활용할 필요가 모든 장비를 가지고 있습니다.\010카 미스트런러한테 내가 보낸다고 말해!"
rows["239:1552847634"]="도자기 생활은 쉬운 일이 아닙니다. 하지만 그것은 당신의 뼈에 철강을 넣고 당신의 심장에 불을 붙여줍니다. 아버지는 도자였고, 저의 할아버지는 그 전에 그림 바톨 아래의 도자기에서 있었습니다. 그리고 이제 제 아들은 우리의 발자취를 따라가고 있습니다. 그 소년은 저를 자랑스럽게 만듭니다."
rows["239:1679097072"]="이 녀석은 내가 생각했던 것보다 조금 더 커서$b$b맥주 너무 많이 마시는 게 너한테 비만해 줄 거 알아, 첸 삼촌처럼$b$b어쨌든, 혼자 이 남자를 견딜 수 없다고 생각해요."
rows["239:1938435630"]="이러한 사건에 적절히 대응하면 힘이 됩니다.$B덤블라이저 5000의 과잉수력 탱크 안에$B\010|TInterface\\Icons\\INV_Misc_EngGizmos_04.blp:32|t |TInterface\\Icons\\INV_Misc_EngGizmos_12.blp:32|t |TInterface\\Icons\\INV_Misc_EngGizmos_13.blp:32|t\010"
rows["239:2032924346"]="우리는 이 지지를 얻기 위해 많은 것을 포기했고, 계속 싸워야 합니다. 우리의 방어력이 약하긴 하지만, 계속 추진하는 노력은 앞으로 더 강력한 동맹을 모집하는데 도움이 될 것입니다.$B$B용기가 필요한 시간이야 챔피언"
rows["239:2108122262"]="아니, 저는 지적자이고, 제가 가볍게 받아들여서는 안되요. 저는 요금과 백두사리에서 치유의 약물을 만들 수 있습니다.$b$b어쨌든, 구매를 하고 싶다면 패트리샤와 얘기해 주세요."
rows["239:325662707"]="구름 뱀 라이더의 길은 길고 힘든 것이지만, 당신은 당신의 구름 뱀 동반자와 함께 여행을 할 것입니다.$B$B함께 길을 끝낼 수 있다면, 당신의 마지막까지 당신을 견인할 충성스러운 친구가 있을 것입니다."
rows["239:46821746"]="저는 부끄러워요, 오래된 친구. 더 이상 제가 무엇을 하는지 모르겠어요. 전설의 영웅들을 수치스럽게 만들지 않는 것은 당신만이 아닙니다. 저나 이 부패한 정치인들이다. 그들은 우리의 삶을 빈 약속과 끝없는 거짓말로 채우고 있습니다."
rows["239:593066814"]="그리고 당신의 허약한 몸이  ⁇ 에 걸려있는 동안, 저는 미친 사람이 죽임을 당했다는 것을 알고 즐거워할 것입니다. 결국, 당신은 어떤 증거가 있습니까? "
rows["239:685951742"]="내 외조녀 지가 맥주공사가 되는 꿈을 이루는데 도움을 준다고 들었어요$b$b저는 그녀에 대해 매우 자랑스럽고, 여러분께 많은 도움을 주셔서 감사합니다."
rows["239:77359682"]="더 많은 이야기가 없습니다. 다라란은 아르키몬데에 의해 거의 완전히 파괴되었습니다.$B$B아키몬데의 복수사건의 원인이 직원이라고 믿는 사람들도 있습니다."
rows["23:1001727179"]="이제 네 피가 내 거야"
rows["23:100922384"]="도둑놈! 감히 신성한 이곳을 더럽히다니!"
rows["23:1010386014"]="얼마나 더 가야 되는 거예요?"
rows["23:1013684165"]="하이질은 길을 잃었어 포기해"
rows["23:1018309470"]="노래는 무슨 이야기야?"
rows["23:1021991695"]="여기 거의 다 끝났어"
rows["23:1024347553"]="쭈그러든 용의 발톱!"
rows["23:102493864"]="시행령!"
rows["23:1026606322"]="당신의 개는 당신에게 미소를 짓습니다."
rows["23:1027664722"]="퍼져라!"
rows["23:1028013862"]="그리고 당신의 이야기는 이렇게 끝납니다."
rows["23:1029375033"]="수고했다, 헨더스."
rows["23:1029928026"]="나... 뒤로... 마스터..."
rows["23:1030310442"]=" ⁇ 이 필요해"
rows["23:1031470650"]="%s 자극적인 숨쉬는 것"
rows["23:1033497315"]="곧 알 수 있을 거야"
rows["23:1034124478"]="수작 부리지 마라!"
rows["23:1037713565"]="비행이 불가능한 멍청아들!"
rows["23:1048801904"]="어서, 느린 똥구리!"
rows["23:1051178891"]="어떡해!"
rows["23:1057011207"]="개도 널 사랑해!"
rows["23:1060885456"]="당신한테서 사고 싶어요."
rows["23:107305218"]="이번엔 절대로 돌아오지 마!"
rows["23:1073342793"]="내 팀은 널  ⁇ 을 거야"
rows["23:1073489007"]="더 많은 놈들이 있어!"
rows["23:1074237633"]="네가 승리했다고 생각하지 마"
