rows["23:943544251"]="한 번만 잘라내면 되죠"
rows["23:9465673"]="난 너의 버섯을  ⁇ 다!"
rows["23:950537901"]="민주 트롤들이 싸우고 싶어?"
rows["23:955116839"]="너무 많았어!"
rows["23:957630110"]="좋아, 남자들이!"
rows["23:964040126"]="엘뉴, 내 화살을 안내해!"
rows["23:964081134"]="눈을 크게 열고"
rows["23:965036516"]="이 치명적인 모욕을 끝낼 수 있어!"
rows["23:971127987"]="마그마토스?!"
rows["23:972238195"]="토큰, 토큰!"
rows["23:974121654"]="다음엔 더 강하게 치게!"
rows["23:974179756"]="저녁 식사는 일찍 올까요?"
rows["23:974326592"]="난 널 망칠 거야!"
rows["23:975010853"]="미안해, 딸..."
rows["23:977235153"]="오크들, 영광으로 나아!"
rows["23:979278761"]="누가 그랬어요?"
rows["23:980167233"]="- 그래, 그렇게 생각하네"
rows["23:982677862"]="고마워요, 어떻게 도와드릴까요?"
rows["23:984604381"]="난 더 힘든 거였어"
rows["23:987382039"]="절대 막을 수 없어!"
rows["23:987863018"]="앰버 레지로 데려다줘"
rows["23:988285658"]="내 사람들이 다 죽었나?"
rows["23:988665424"]="가치 없는 희생..."
rows["23:988701431"]="적은 이 안에 있다!"
rows["23:994785301"]="어둠의 포털을 통해"
rows["23:999450641"]="우리 모두를 막을 수 없어!"
rows["240:1156659508"]="월드 오브 워크래프트와 코카콜라 (R) 는 iCoke-World of Warcraft 여름 프로모션을 함께 진행했습니다. 코카콜라의 특별히 표시된 병의 캡 아래에 코드를 찾아보세요. 그리고 다시 여기에 와서 가상 아이템을 획득하기 위해 코드를 입력하세요."
rows["240:1224526166"]="이 곳 은 썬더 블러프 로 가야 합니다. 블러드하프 마을 에서 북쪽으로 가는 길 을 따라 올라가는 등단 을 엘리베이터 로 타고 올라갈 수 있습니다."
rows["240:1334641560"]="날 구해줘서 고마워요$B$B저는 요리사이자 스톰윈드의 화학자입니다. 저는 이  ⁇ 보가 저를 잡았을 때, 아구스 삼촌의 지역 약초와 요리법을 찾고 있었습니다. 만약 당신이 여기 오지 않았다면, 저는 그들의  ⁇  냄비에 말했을 것이라고 확신합니다."
rows["240:1551221290"]="약속받은 자, 우리 기억나? 쿠르츠의 예언을 기억나? 이 순간은 미리 정해져 있었습니다.$B$B<고위장 스틸파인 씨가 당신 앞에 엎드려요>$B$B드레네이는 항상 내 사람들 사이에서 환영받습니다."
rows["240:1594450977"]="알케미스트들이 어떤 보석을 변조할 수 있다는 걸 아세요?$B$B저는 그녀의 실력을 고려해 본 연구소가 완성되면, 우리는 시간과 함께 사라진 보석을 만들 수 있을 것이라고 확신합니다."
rows["240:1875904417"]="- 넌 이미 죽였어!$B$B콰그미란을 연구하고 대화할 수 있었는데 이제 그의 시체만 공부할 거야$B$B♪ 숨쉬는 것$B$B이 문에서 내보내줘요, 내가 그를 보고 나가는 거 알아"
rows["240:196695072"]="전 평생 군대에 있었고, 여러 전쟁에서 싸웠지만, 다른 사람들의 전투였죠.$B$B이번엔 안돼, 매번 포세이큰 여기 보시는 군인은 한 가지 이유만으로 왔어요."
rows["240:2094045586"]="포세이큰 무기 마스터 아치발드는 폴아임을 잘 알고 있다. 그는 언더시티 전쟁 구역에서 다른 사람들을 훈련한다. 실버문 Farstrider 광장에서 혈액 엘프 무기 마스터 인 Ileda, 또한 적절한 기술을 보여줄 수 있습니다."
rows["240:2142212615"]="숲에서 살아남기 위해 도움이 필요하다면, 도시의 벽으로부터 멀지 않은 곳에 떨어져서는 안되지만, 만약 길을 떠나려고 한다면,"
rows["240:216735422"]="난 Farstrider Enclave의 도움이 곧 여기에있을거야 나를 도와 이 쓸모없는 중위 안전에 도착. 당신은 주변에 머물고 싶지 않을 수도 있습니다;"
rows["240:249399217"]="사랑 표지판은 사랑스러운 도시와 도시 사람들에게 줄 수 있는 작은 애정 메시지입니다. 그러한 사람들은 당신을 숭배 선물로 보상합니다.$B$B아니면, 다른 사람이 이미 당신을 숭배한다면, 적어도 그들은 당신에게 우정을 선물할 것입니다."
rows["240:655691274"]="다시 말하지만... 제 정신을 진정시키는 당신의 행동에 너무 많은 믿음을 두지 않았으면 좋겠습니다.$B$B더 많은 혐오스러운 살인자들을 죽일 준비가 되셨습니까?"
rows["241:1201916197"]="안녕하세요, 환영합니다, 내 상실은 열리지 않은 것 같아요.$B$B하지만 여전히 네 얼굴에 미소를 짓는 혈통의 맹세를 해야 돼."
rows["241:1338629347"]="안녕하세요 여행자!$b$b오늘 밤 방랑자 축제에 오실 건가요? 방랑자들은 자몰 직후 이 해수욕장에서 모여들게 될 겁니다.$b$b다음 시간 안에 축제가 시작될 겁니다."
rows["241:1347942589"]="|cff0000ff급 3:|r\010  방트: $7435w-$7436w\010  산오리아크: $7445w-$7446w\010  Ixx: $7447w-$7448w\010  마자리언: $7459w-$7460w\010|cff0000ff급 4:|r\010  분쇄: $7451w-$7452w\010  레오나 지구풍: $7487w-$7488w\010  도미니카 일러시оні스트: $7455w-$7456w\010  디켄: $7469w-$7470w"
rows["241:138558443"]="테론이 장갑을 만드는 능력은 비교할 수 없을 정도다. 그는 다른 사람들에게 전달하는 지식에 대해 더 많은 요금을 부과하지 않는다는 것에 감사해야 합니다. 이제 가서 다르나서스의 북동부 부분의 공예인 테라스에서 그를 찾아보세요."
rows["241:1411864346"]="풍광 펀치의 예술은 어두운 시절부터 우리 가족에서 세대대로 전해져 왔습니다.$b$b이 펀치는 모가 제국의 어두운 시절에 처음 시도된 것으로 전해지며 판다렌에게 자유를 주게 된 것이라고 한다."
rows["241:1489153779"]="제 지식의 한계에 도달했으나 아직 배울 것이 더 많습니다. 바다 건너편의 마지크 Quarter에서 스톰윈드 시티의 위대한  ⁇ 匠이 살고 있습니다. 그의 이름은 Georgio Bolero, 그리고 그는 당신을 훈련 할 것 같습니다. 가서 그와 이야기하십시오."
rows["241:1545417319"]="전염병을 일으키는 사람들은 보통의 약사보다 조금 더 실용적이죠. 결국 전염병을 배치하는 물적 요건을 처리합니다.$B$B그렇다고 이론적인 배경이 안 좋아진다고는 하지 않습니다. 우리는 단지..."
rows["241:1597500321"]="자라잔은 오래전부터 우두마법을 하고 있어 그가 죽은다고 사람들을 설득하고 고대 암흑 의식들을 수행하고 있어$B$B우리가 올 거라는 걸 알고 있어 준비해야 해"
rows["241:1616888978"]="우리가 원하더라도 우리 사람들을 조직해서 움직일 수 있을지는 모르겠지만, 우리는 적대적인 요소들이 무작위로 땅 곳곳에 나타나고 있다는 소식도 들었습니다. 때로는 마을에서, 때로는 시골에서 말이죠."
rows["241:188797869"]="제 놀라움을 상상해 보세요. 천재인 포세이큰, 칼더 그레이가 저를 찾아왔고 전 세계 챔피언들의 최고의 특징을 가진 전투기로 기획됐습니다."
rows["241:2059300846"]="탐험가 동맹의 대표자로서 브론윈과 저는 이 산들을 연구하기 위해 얼라이언스의 명령에 따라 여기 있습니다.$B$B하지만 우리 둘 사이로 실리투스에서 긴 기간 머물면서 휴가를 필요로 했습니다."
rows["241:2109232702"]="시내 밖으로 남동으로 가는 길에서 셰레네 로바트를 찾아서 동쪽으로 갈 때,"
rows["241:2111339876"]="이 남자가 날 미치게 해 줄거라고!$B$B그들은 그저 물건을 터뜨리는 것 뿐이고, 절반 정도는 그 일을 하는 것만으로도 나간다!"
rows["241:2142651824"]="당신 말이 옳소. 우리는 스컬지에게만 온 신경을 쏟아야 하지. 트롤과 마을은 무시하고 데솔름에 병력을 집중해야 해! 다르칸을 해치우면 '우두머리'가 없어진 나머지 스컬지 군대는 급속도로 무너질 거야."
rows["241:221202247"]="지금 저들에게 건 마법은 그들의 머릿속에서 우리에 대한 기억과 조금 전까지 있었던 일에 대한 기억을 지워버릴 것입니다. 그들은 우리가 시간을 거슬러 오지 않았던 현실만 기억하게 될 겁니다. 수고하셨습니다. 이제 스랄은 자신의 운명을 찾기 위해 모험을 떠날 것입니다... 그리고 타레사는..."
rows["241:397664901"]="카펫 폭탄 테러는 지역에 매우 많은 양의 폭탄을 떨어뜨리는 것을 의미하며, 기본적으로 지역을 폭탄으로 덮는다.$B$B폭격자들은 종종 여러 가지 가벼운 폭탄을 한 지역에 사용하고 그 다음 무거운 폭탄을 사용하여 여전히 서있는 것을 청소합니다."
rows["241:411287967"]="당신은 전문적으로 가죽공업자예요.$B$B아버지는 몇 세기 전에 사우스윈드 빌리지에 살았던 유명한 공예가 있었다는 이야기를 했습니다."
rows["241:526071024"]="식물학은 야생에서 자원을 찾아서 수집할 수 있습니다. 이 약물은 경매장에서 판매되거나 알케미나 글씨술 전문직을 지원하는 데 사용될 수 있습니다.\010숙련 된 식물 의학 들 은 또한 땅 에 대한 자신 의 지식 을 자신 을 치유 하기 위해 사용할 수 있습니다."
rows["241:620435175"]="만약 당신이 스플린터 트리 포스트에 있는 카라반과 상인들의 출퇴근에 대해 알고 싶다면, 나는 당신이 찾고 있는 오크가 다행스럽습니다.$B$B뭔가 원하면 빨리 해"
rows["241:684198885"]="토프린 스톤스킬드는 사냥에 대한 그의 전문성을 가져오기 위해 아이언포지에서 온 것입니다. 만약 당신이 왜곡동의 연기로 가득한 공기를 숨쉬는 것을 방해하지 않는다면 당신은 그 지역의 북동부 지역에서 그의 집에서 찾을 것입니다."
rows["241:921553449"]="네, 그는 불가능하다고 생각했던 일을 했습니다.$B$B내 관점에서 보아도 고귀가 구신의 대리인과 대화를 나누는 것을 볼 수 있었습니다"
rows["241:958529567"]="|cff0000ff급 3:|r\010  방트: $7371w-$7372w\010  산오리아크: $7381w-$7382w\010  Ixx: $7383w-$7384w\010  마자리언: $7395w-$7396w\010|cff0000ff급 4:|r\010  분쇄: $7387w-$7388w\010  레오나 지구풍: $7423w-$7424w\010  도미니카 일러시оні스트: $7391w-$7392w\010  디켄: $7405w-$7406w"
rows["242:1024845133"]="우리는 기사들을 파견하여, 다음 재판의 도전으로 봉사하기 위해 아르타스 스컬지 의 두 부대 중 한 명을 잡았습니다. 기사들은 아직 먹이를 가지고 돌아가지 않았기 때문에, 다음 단계의 재판은 대기중입니다. 다음 주에 다시 확인하세요."
rows["242:1126064041"]="오래된 신의 힘으로 만들어진 유물이 있는데 정확히는 알 수 없지만, 쇼갈이 완성하기 전에 찾아봐야 합니다.$B$B다른 모든 것은 차원적이고, 우리 모두 포함해서"
rows["242:1135257213"]="녀석들은 소모품일 뿐이다. 자, 봐라! 살게라스가 해내지 못한 일을 내가 해낼 것이다! 이 보잘것없는 세상을 갈가리 찢어발기고 불타는 군단의 진정한 주인으로 우뚝 서리라! 종말이 다가왔다! 어디 한번 세계를 구해 봐라!"
rows["242:1183823550"]="이 숲에 악마가 있는 것은 내 종류의 잘못이라고 볼 수 있다는 것을 잘 알고 있습니다.$B$B또한 이 일을 보완하려는 첫 번째 고등병은 아니죠. 그리고 제 도움을 허락할 만큼 실용적인 에메랄드 서클을 감사드리죠."
rows["242:1624319254"]="드래곤 해조가 있는 것 보다 더 좋은 승마 동반자 는 없을 것 이다. 그 들 의 낮은 자세는  ⁇ 이 가 급하게 구회 할 때에도 도 회귀 나 찌르는 것을 경험 하지 않는다는 의미 이다. 만약 당신이 하나를 구입하는 데 관심이 있다면, 당신은 Tushui에 자신감을 증명해야 한다."
rows["242:1693743192"]="'L'ghorek의 목소리는 당신의 마음 속에 울고 있습니다.'$B$B난 거의 죽었어, 넌 도와야 해$B$B그들은 내 에너지를 내  ⁇ 을 만들고 그들의 상승자를 창조합니다 그들은 임박한 전쟁에 심각한 위협입니다"
rows["242:1807452909"]="우리가 데려온 고아들은 전쟁으로 찢어진 쇼라자르盆地에서 왔어요. 당신은 고아 오라클  ⁇ 아 또는 Frenzyheart 강아지를 돌볼 수 있습니다."
rows["242:1812142158"]="3차 대전쟁에서 패했을 당시 그 뼈저린 고통은 절대 잊을 수 없다. 오랫동안 복수의 이날을 기다려 왔노라. 이제 불타는 군단의 그림자가 세계 곳곳에 드리워질지니, 너희 같은 하등 종족이 멸망하는 건... 시간문제일 뿐이다."
rows["242:1823473837"]="내가 가진 모든 것이 한때 명예와 부자, 최고의 성투자 장비를 가지고 있었고,$B$B카르텔이 날 잡았을 때 난이도를 조작하고 거래 승부를 벌였어$B$B이제 이 램프와 간이  ⁇ 은 것 외에는 아무것도 없어요"
rows["242:1949653873"]="이제 울음 외에는 모든 전쟁 재물이 실리투스 센라리온 포크로 운반되고 있고, $2113w일도 채 안 돼야 군관이 집착되고 전쟁이 시작될 때까지는 오래 걸리지 않을 것이다."
rows["242:2097930535"]="바람이 강렬히 이 돌을 가로지르고, 대부분의 생명체는 오래전부터 이 아이스크라운의 한 구석에서 도망쳤지만, 다시 돌아오기 위해서는 약간의 설득이 필요합니다. 그래서 저는 이 지지를 걷습니다. 어느 날 이 나무들은 우리 모두를 넘어서게 될 것입니다."
rows["242:2133113741"]="땅은 내가 상상했던 것보다 더 나쁜 상태입니다. 만약 피해가 이 속도로 계속된다면, 파라홀론, 네더스톰은 곧 우주 진흙일 뿐일 겁니다.$B$B그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그 때, 그, 그 때, 그 때, 그, 그 때, 그, 그 때, 그 때, 그, 그 때, 그, 그 때, 그, 그, 그, 그, 그, 그, 그, 그, 그,에, 그, 그,에, 그, 그,에,에, 그, 그,에, 그, 그,에, 그, 그, 그, 그"
rows["242:226023576"]="파다렌들은 우리 민족을 학살하고 수천 명의 파다레인을 사살함으로써, 세대를 거쳐서 생명의 소중함을 가르쳐 왔습니다. 소중한 선물이지만 간략한 선물입니다."
rows["242:34093252"]="내가 보여준 것 이상으로 훈련이 더 나아질 수 있다면 그 멋진 옷을 훼손해야 합니다."
rows["242:890956284"]="이 모든 공격이 시계처럼 진행되도록 하는 것이 제 임무입니다.$B$B높은 기술공 메카토르크는 현장에서 있지만, 그는 지금 당장 더 많은 병력을 불러올 예정입니다.  $B$B그는 결코 늦지 않아, 그냥 여기 있어, 그는 여기있을 것입니다."
rows["242:950973308"]="'무엇 을 행하 는 것'은 어떤 태도 로서도, 그 방법 은 어떤 행동 이 아니라 어떤 태도 로서든 일 수 있습니다.$b$b만나면 모든게 이야기이고, 가는 곳이 모험이고, 마시는 술은 맛본 최고의 것입니다.$b$b이건 나쁜 인생이 아니죠?"
rows["243:1249154639"]="가로쉬에게 알려 주란 말이십니까? 대모님, 가로쉬의 아버지는 우리 모두를 피의 저주에서 벗어나게 하려고 목숨을 잃었습니다. 저는 아무 말도 하지 않을 겁니다. 대신 헬스크림 님의 의지를 의심하는 모든 이들과 가로쉬에게 그롬 헬스크림이라는 영웅이 모든 오크들을 위해 어떻게 생을 마감했는지 보여 주겠습니다!"
rows["243:1321628692"]="그래, 훨씬 더 좋아졌어요$B$B미쉬카와 보드 카라시가 날 알렸어, 네 도착과 화이트 파운의 검색 그리고 내 구출이$B$B상황이 이상적이지 않고, 우리가 해야 할 일은 많아요."
rows["243:1411314099"]="빌그워터 카르텔의 이름으로, 저를 이 구석에서 해방시키는 첫 사람에게 매우 관대한 보상을 제안해 주세요. 물론 표준 계약 조항이 적용됩니다. 하지만 미세한 글씨에 대해 걱정하지 마세요."
rows["243:1481746610"]="나라인 사우스판시, 은퇴한 엔지니어이자 마이너스 마이너스,$B$B만약 당신이 여기 와서 재학에 대한 기술을 배우려고 한다면, 저 책으로...$B$B<나라인은 \"두미들을 위한 예언\"을 지적한다."
rows["243:1499288556"]="탐욕이 널 내게로 데려왔어$B$B<마트레디스는 웃는다>$B$B지혜로운 드레네이 한 사람이 제게 말했죠. 탐욕은 이 세상의 모든 인종들이 공유하는 유일한 특성이라고.$B$B리브람에 있는 구성요소를 수집하셨나요?"
rows["243:1648905227"]="두 가지 큰 학문들이 우리 민족에 있습니다. 투슈이족은 인내하고, 생각만 하고, 신중합니다. 후오진족은 격렬하고, 앞장서고, 적극적입니다. 두 학문 모두 우리에게 각기 다른 방식으로 봉사하며, 둘 중 어느 것도 다른 것 없이 효과적으로 존재할 수 없습니다."
rows["243:1788000764"]="당신은 무장 스승 하란의 |cFFFF0000|Hspell:|h[빛의 블레드]|h|r 능력으로 죽었습니다. 무장 스승 할란은 이 능력을 사용할 때 여행하는 두 가지 방향 중 하나를 선택합니다. 그래서 그가 가는 방향으로 반응하려고 노력하십시오."
rows["243:2042126732"]="에너지의 원인은 저렴하고 재생 가능하며 모든 것을 폭발시킬 수 있습니다.$B$B물론, 당신은 시간과 공간 너머의 상상할 수 없는 공포에 당신의 영원한 의지를 잃게 될 위험을 감수하지만, 예, 보상과 위험을 감수합니다!$B$B왜 날 보고 싶었어?"
rows["243:330603428"]="우리는 그가 자이드 숲에서 의심을 제거하고 크라사랑 야생에서 절망으로부터 자신을 깨끗하게 하고 타운롱 스텝에서 두려움을 극복하고"
rows["243:399210184"]="안녕하세요! 우리는 해상에서 그 쓸모없는 해적들에 의해 봉쇄되고 있습니다! 당신은 그들에게 몇 개의 폭탄을 던지면서 우리를 도울 수 있다고 생각합니까?!$B$B훔친 제펠린은 약 $3078w분 거리에 있어"
rows["243:499796442"]="크로스의 이상에 헌신한 삶을 살아라, 싸우지 말며 성장하지 말아라. 매일 그보다 더 강해진다.$b$b고통과 고통을 겪어, 모든 사람이 네 적이다.$b$b총을 들고 죽고, 몸도 이갈루크에게 넘겨주"
rows["243:573685982"]="세이지를 방문해 운명을 알 수 있도록 추천해줘요$B$B그리고 우리는 끊임없이 다양한 새로운 볼거리로 페어를 확장하고 있습니다!"
rows["243:665504487"]="저는 제 사람들이 이 파괴에 어느 정도 책임이 있다고 생각합니다. 불타는 군단이 비극은 우리의 마지막 대피의 결과입니다. 우리 배가 추락했습니다."
rows["243:696537934"]="날카로운 치아, 근육은 케이블처럼 그리고 정신은 철도 함정처럼 이 녀석은 내가 본 최고의 애완동물 중 하나예요"
rows["243:71080563"]="짝 친구, 나쁜 소식이 있어 매일 와서 채소를 심어 채우지만, 날 도와줄 때 더 많은 경험이 필요하지만"
rows["243:995017327"]="맥주 좀 찾고 있어요? 두 명의 맥주를 파는 술집들이 도시 곳곳에서 돌아다니고 있습니다.$B$B만약 당신이 그들을 만나지 못한다면, 나이트링글 라운지에서 하라 알벨리나 호네의 사리아 차꽃이 바로 당신을 고칠 수 있습니다."
rows["244:1054099521"]="로켓 장군, 보모의 지휘관, 궤도 운영 및 기계의 뇌신뢰$B$B모든 시스템이 작동하고 있습니까?! X-52 Nether-Rocket은 여전히 많은 작업이 필요해 보입니다!$B$B어서, 우리들은 T-미нус 절대 여기 있지!"
rows["244:1063830520"]="피 기사들의 주부인 리아드린 여신, 파스트라이더스 광장에서 기사들의 본부를 두고 있습니다."
rows["244:10737703"]="나 여기 있노라. 작은 날벌레가 구름을 이뤄 문 없는 출입구를 자유로이 드나드는 이곳, 축축한 진흙투성이 땅에 선 투박한 돌탑 안에, 상스럽고 비위생적인 육중한 녹색 생명체 사이에! 내 평생 이보다 더 행복했던 적은 없어."
rows["244:1177929406"]="저는 떠나버렸어요. 블랙록과 함께 남아있지 않겠습니다. 아니요, 제 자녀들의 죽음은 헛되지 않을 것입니다. 저는 랜드 같은 무능하고 권력 갈망한 마니아가 하에 봉사하지 않을 것입니다.$B$B로데론년] 숲에서 피난처를 구했고, 헤어트글렌 근처에서 방랑자 생활을 했습니다."
rows["244:1216566096"]="참석한 모든 신부님들이 지금 떠나야 합니다. 왜냐하면 진짜 남녀만이 이 끔찍한 시선을 감당할 수 있기 때문입니다."
rows["244:1427982137"]="사실, 우리 거주지인 롤로케임은 그의 장비들을 가지고 왔어요. 당신은 익숙한 것과 약간 다를 수도 있습니다. 그는 아라코아입니다. 하지만 그것은 당신의 필요를 충족시켜야 합니다. 그는 하위 도시의 북서부 부분에서 서식합니다."
rows["244:1576722856"]="내 신발 아래의 작은 벌레일 뿐이야. 하지만, 밑바탕을 취해서 수미와 튜미에게 더 매력적일 수 있어."
rows["244:1718819721"]="담배와  ⁇ 한 여자 손길이 필요해요$B$B난 몇 달 동안 그 물건 속에 갇혀있었어 무슨 날인지?$B$B와우 와우"
rows["244:1963308896"]="시야나 여동생은 숲의 위험에 순진하지만 좋아하든 싫든 이 차가 탄 즉시 도시 벽에 들어갑니다 $b$b내가 필요한 것보다 더 많은 가방이 있는 것 같네요\010"
rows["244:2063257557"]="그 원 밖의 모든 것은 당신을 볼 수 없을 것입니다. 하지만 공격하거나 피해를 입으면 환상이 사라질 것입니다.\010$b내가 다르게 말 할 때까지 숨어서 가라고 제안합니다. 이 악마들은 완전히 힘을 발휘할 수 없을 정도로 강력합니다."
rows["244:2094641326"]="아우리페러스 부인, 이건 전쟁이오. 어떤 전쟁이든 희생은 따르게 마련이지! 지구라트 두 곳만 지키면 되잖아. 우리는 저주받은 자의 탑으로 쳐들어가서 그곳의 주인을 붙잡을 거요. 그러면 쿠엘탈라스는 다시 당신 것이지."
rows["244:304611694"]="\"거림들을 극복하고자 하는 사람들에게는 기술\"라고 말했어요. \010만약 당신이 그녀가 믿는 것처럼 믿으면 다르나서스의 북부 부분에서 있는 Cenarion Enclave로 가는 길을 찾아라"
rows["244:321492763"]="오레보르 항구에 오신 것을 환영합니다. 여기 두려워할 것이 없습니다. 우리는 깨졌지만, 우리는 당신의 적이 아닙니다.$B$B난 쿠레나이족의 이쿠티입니다. 다레나이 형제들과 그들의 새로운 동맹국들과의 관계를 회복하고자 하는 분해된 사람들입니다."
rows["244:489585052"]="이제 십자군 재판을 마쳤으니, 그랜드 십자군 재판에 참가하기 위해 다시 돌아가는 것을 고려해야 합니다. 가장 강한 모험가들만이 재판을 마칠 수 있기를 희망할 수 있지만, 당신은 당신의 노력에 대해 좋은 보상을 받을 것입니다."
rows["244:55175516"]="리치 킹이 없어서 걱정이 안되는데, 많은 큰 샷이 올리고 다닐 때 항상 뭔가 엉망이 되는 걸 봤는데, 한 군대가 지나가면서,"
rows["244:728051265"]=" ⁇ 고로 크레이터 남쪽에서 멀리 떨어져 있습니다 칼림도어천개의 바늘 너머에 있는 타나리스에서 큰 떠있는 돌을 찾아라 그 돌들은 크레이터 입구로 표시되지만 조심해"
rows["244:771704629"]="당신을 만나서 반갑습니다. 너무 많은 일이 일어나고 있습니다. 나 같은 로어워커는 따라가기 힘들어요. 저는 제 꿈의  ⁇ 을 통해 많은 것을 보았습니다. 하지만 우리 역사의 다음 장을 쓰는데 도움이 될만한 당신 같은 영웅이 필요합니다."
rows["244:84668990"]="그들은 밸리의 힘을 사용했고, 그들의 자신의 육신 변형 마법을 이용해, 잔인한 도마뱀의 종족을 생무기로 만들고, 군대를 만들어냈죠. 사우로크의 군대가요."
rows["244:930238945"]="그럼 삼위일체에 설치된 악마의 방지를 통과하기 위해 필요한 악기를 만드는 긴 과제를 겪는 것처럼 보이도록 합시다.$B$B로라무스는 웃는다.\010"
rows["245:1071553822"]="이상한 건... 나가들이 우리를 살려줄 줄은 몰랐어요$b$b그들은 이 진주 거품들을 만들어서... 한 사람당...$b$b매일 그들은 어떤 곳으로 죄수들을 파견합니다.$b$b다시는 못 볼 거야"
rows["245:1086995397"]="이건 그냥 행운의 날일 뿐이야. 내가 슈퍼셀러를 완성한 지 얼마 되지 않았어 680고작 저하 가격에 판매되는 물건들이 많아요. 직접 보세요... 1000 내 로봇을 팔아먹게 될 거야"
rows["245:125678488"]="당신은 젊은 고흐 마스터를 떠올리게 해$b$B그는 처음으로 나에게 가죽을 입고 농부 소년으로 왔지만 그의 모습에 스타일리쉬한 발걸음을 가지고 있었습니다.$B$b우리는 적어도 2년 동안 동부에서 화제를 모은 의류 라인을 만들었습니다."
rows["245:1299532723"]="타워 포인트 이스트는 남쪽에서 전투장과 호드 영토 사이의 경로를 지킨다.$B$B이 기관은 호드동부 프로스트울프 타워는 프로스트울프는 마을과 프로스트울프를 보호한다.$B$B호드에 의해 통제됩니다."
rows["245:1380972626"]="명심해라. 에라니쿠스가 원하는 것은 오직 꿈속에서 빠져 나와 아제로스로 가는 것이다. 그가 꿈에서 나오면 내 현신을 파괴하기 위해 수단과 방법을 가리지 않을 것이나, 그대가 홀 파편을 되찾으려면 이 방법 밖에 없다."
rows["245:1447815141"]="저는 낙스라마스에서 잃어버린 일부 불성스러운 마법의 장갑과 조각을 결합하여 매우 가볍고 매우 치명적인 장갑을 만들 수 있습니다."
rows["245:1758255466"]="내 백성에게는 네가 잘 알려지지 않는다. 코도 는 강력한 양떼이고, 내 백성의 사랑과 보살핌의 결과물이다. 이 같은 양떼는 낯선 사람에게 주어지지 않는다. 썬더 블러프의 장로들이 너를 높이 평가할 때까지, 나는 너에게 코도 판매를 제안할 수 없다."
rows["245:2133823396"]="야생 뱀 가운데 가장 드문 것 은 오닉스 뱀 이다. 이 희박 한 검은 구름 뱀 들 은 북동쪽 에 있는 윈드워드 섬 에서 알 을 낳는 것으로 알려져 있다.$B$B만약 어떤 오닉스 계란을 발견한다면, 내게 가져오세요."
rows["245:22487097"]="너무 오래전부터 내가 떠나서, 아제로스 내 과거를 다시 발견하고 왕위를 되찾기 위해 얼라이언스 내가 없는 동안, 당신 같은 영웅들이 우리 연합을 지키고 있는 것을 보고 마음이 따뜻해집니다."
rows["245:225227141"]="훈련 좀 하고 싶군요? 스톰윈드 하지만 경비관들은 금지하고 있습니다. 당신은 노인시의 돼지와 휘파람 타버너에서"
rows["245:278348340"]="지휘관, 이 세상으로 나가지 않을거예요. 수 천 명의 다른 세계인들로 부터 포로로 끌려가야 합니다."
rows["245:541495846"]="몇 개의 금속 바를 말씀드렸나요? 호드 수집한 $2018w 구리 바퀴 $1998w 필요하고, $2005w 소재로 된 $2006w 그리고 $2009w 미트릴 바를 찾은 $2008w 모집된 것입니다."
rows["245:635473972"]="예, 내가 마실 수 있는 때부터 맥주를 만들고 있어요.$b$b어떤 사람들은 내가 시간을 낭비하고 있다고 말하지만, 저쪽에 있는 큰 맥주 공장에서 나오는 맥주를 사면 좋다고 말하지만..."
rows["245:773651281"]="아니 이건 또 뭡니까? 이 지역은 이제 안전하다고 말하지 않았었나요? 이번이 벌써 세 번째 공격이던가요? 여기서 빠져나가면 그만큼 당신 보상에서 공제하겠습니다. 자, 거기 그냥 그렇게 서 있지 말고 저 황천 수집 장치에 접근할 수 있도록 길을 터주십시오."
rows["245:786424336"]="우핑 마스터는 거의 모든 무기를 숙달해 왔고, 특히 검 기술을 통해 치명적인 무기를 가지고 있습니다."
rows["245:819567842"]="이 새끼는 분노를 잘 다스렸다고 증명해줬어요. 어린 새끼의 말과 영웅의 행동 사이에, 저는 이해한다고 생각합니다. 안개가 너머에 있는 사람들은 전투로 굳어지고 있습니다. 그들은 흉터로  ⁇ 어져 있지만 많은 것을 배웠어요. 나는 그들을 신뢰합니다."
rows["245:918831454"]="자연과 소통하는 것 같은 건 없어요. 적어도 밤 엘프들은 그렇게 말하죠. 나는 꽃과 나무와 대화하는 게 별로 좋아하지 않지만,"
rows["246:1042100236"]="너, 나 그리고 나무 사이에  ⁇ 이들이 펄브로우를 죽였어 네, 내 두 눈으로 봤는데"
rows["246:1064275200"]="어떻게 그들은 우리의 방어선 뒤에 있는 밸리 관리자를 공격할 용기를!$B$B왜 우리가 당신의 도움이 필요하는지 이제 이해가 되었나요?$B$B샤오티엔 모가 계곡으로 들어가는 방법을 찾았어 통제되지 않으면 우리 평화로운 집으로 엄청난 파괴를 가져올 것입니다"
rows["246:1248265069"]="물론, 그 말로는, 여러 개의 작은 공기 구멍이 동굴에서 더 깊게 같은 방식으로 행동하는 것을 발견할 수 있습니다. 시간이 지남에 따라, 당신은 그들을 더 효율적으로 동굴 안에서 이동하기 위해 사용하도록 배울 수 있습니다."
rows["246:1255494081"]="썬더 블러프의 장로들이 당신을 친구로 여기지 않는 한, 나는 당신에게 코도 판매를 제안 할 수 없습니다."
rows["246:1270459611"]="테일드라시લના 최고의 공예가 만든 칼림도어 이 아제로스 성장하는 것을 알 수 있나니 얼라이언스 대나무의 백성들과 이 땅의 백성들 사이에 너희가 원하는 것은 물어보는 것 외에는 없노라"
rows["246:129798368"]="안녕하세요 여행자!$b$b오늘 밤 방랑자 축제에 오실 건가요? 방랑자들은 자몰 직후 이 해수욕장에서 모여들게 될 겁니다.$b$b그 사건이 다가오면서 내게 말해주세요. 얼마나 기다려야 하는지 알려드리겠습니다."
rows["246:1315960635"]=" ⁇ 匠 키렌은 항상 더 호기심이 많은 학생들을 찾고 있습니다. 그의 섬세한 공예를 가르치기 위해. 그의 가게는 처음에는 발견하기 다소 어렵습니다. 하지만 그것은 바자르의 경매 집 북쪽에 있습니다. 당신은 건물의 하층에서 그를 찾을 것입니다."
rows["246:1486184610"]="바쉬지르에 갇혀있다는 건 무슨 느낌인지 모르겠어요.$b$b자그마한 자그마한 거리가 미친다"
rows["246:156355264"]="이 거대한 힘을 주신 분들에게 순수한 희생물인 피는 더 순수합니다. 그리고 무고한 피는 더욱 순수합니다. 우리 적들의 생명 유동으로, 우리는 포털을 열고 영광스러운 새로운 세계에 진입할 것입니다. 호드의 역사에서 새로운 페이지!"
rows["246:1805262485"]="안녕하세요 여행자!$b$b오늘 밤 방랑자 축제에 오실 건가요? 방랑자들은 자몰 직후 이 해수욕장에서 모여들게 될 겁니다.$b$b축제는 3시간도 안 지나면 시작됩니다."
rows["246:1854354809"]="카레고스는 블루 드래곤 비행의 새로운 측면으로 선정되었습니다.$b$b너희들 중 한 명은 아리고스의 배신을 죽음 날개로 방해하는데 중요한 역할을 했으며,$b$b우리는 그들의 영웅적 행사를 축하하는 데 참여하기 위해 여기에 왔습니다."
rows["246:430432268"]="제 임무는 창조자들에 대한 정보에 대한 접근을 제공하고, 허용될 경우 아제로스저는 이 정보를 여러분들과 공유할 준비가 되어 있습니다."
rows["246:526794486"]="아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨, 아가씨"
rows["246:876081321"]="대사인 타이란데는 이 임무에 동의하지 않으려 했습니다.$b$b그녀는 펠드린의 연구의 원천이 두 가지 날개 있는 검이라고 믿었던 것 같았다.$b$b그 화산적인 오포세트에서 며칠을 보낸 후, 그녀는 틀리지 않았을까 생각하기 시작했습니다."
rows["246:934283334"]="기억하게. 공포는 이 저주받은 전당에서 가장 위험한 적이네. 마음을 굳게 하면 그대들의 영혼은 천 개의 태양보다 더 밝게 빛날 걸세. 적들은 그대들 앞에 기가 꺾이겠지. 정의의 빛이 감쌀 때 모두 쓰러질 걸세!"
rows["246:988219081"]="그게 정신이야!$B$B이번 작은 회의가 있어서 다행이야 공격에 대해 기분이 좋아졌어$B$B이제 루안 웰드에 돌아가서 이 일을 해봐!"
rows["247:1076198542"]="전설은 이 계곡에서 벌어진 위대한 전투에 대해 이야기 합니다. 많은 용감한 수도사의 피로 황금밭을 붉은색으로 바꾸었습니다."
rows["247:1199438373"]="네, 방금 그 부분에 대한 정보를 받았습니다. $2067w 무거운 가죽이 필요, 호드 수집한 $2066w- 또한 $2070w 이 중 $2071w 두꺼운 가죽과 $2073w 이 중 $2074w 고약한 가죽이 모였습니다."
rows["247:1209391039"]="하지만 불행히도 나이트 엘프군의 방어는 지속될 수 없었으며 라작스는 그런 나이트 엘프들이 얼마 버티지 못할 것임을 알고 있었습니다. 그러나 그들은 결코 굴하지 않고 싸웠기에 라작스에게 참담한 기분을 안겨줄 수 있었지요. 그리고 그보다 더 크게 실망하고 불만스러워했던 것은 그의 왕이었습니다. 잠깐, 왕이라고요? 정말 놀라운 사실이 아닐 수 없군요..."
rows["247:1251490210"]="저랑 당신 사이엔 이 차이가 있어요 Vol'jin, 난 내 백성들이 사막에서 굶어죽지 않을거야. 오크들과 우리와 함께 서기 용기를 가진 모든 사람들에게 자랑스럽고 영광스러운 미래를 보장하기 위해 아무것도 하지 않을 거야"
rows["247:1305267278"]="피드백은 항상 다 필요해요. 특히 다른 사람들과 일하면서요.$B$B재료를 나눠주거나 가난한 자사자를 죽게 만들 때, 저는 대부분 도움을 주죠."
rows["247:1315634892"]="예, 고왕 모그라인: 붉은십자군무진히 믿음과 순결의 기사인 모그라인은 자신의 아들로부터 배신받아  ⁇ 토즈드의 세력으로부터 죽임을 당할 것입니다."
rows["247:142041832"]="트윈이라고 불러라.$B$B아니, 우린 닮았어. 빛우린 같은 행동을 하고 있어요. 특히 싸우고 있는 때요.$B$B내 이름처럼, 유명한 와일드햄어 브루어스를 들어본 적 있으신가요?"
rows["247:1437132717"]="이 곳에는 오크들이 절실히 발견하고 있는 신비들이 있습니다. 우리 과거의 신비, 미래의 신비, 그리고 우리 안에 있는 신비들이$B$B이 미스터리를 깨우쳐내길 희망하니까... 저랑 함께 갈래?"
rows["247:1621006355"]="마브렌. 말 돌리지 마시오. 난 방도를 찾아야 해! 원정순찰대는 동원할 수 없고 실버문에서는 이미 나올 만큼 나온 상태요. 그림자소나무 트롤과 줄아만을 무시할 수도 없지. 놈들이 우리 동쪽 국경에 부대를 배치해 놓았단 말이오!"
rows["247:1641764431"]="낚시는 정말 즐거운 일이고, 내 멘토, 세계 최고의 어업자, 나트 파글에게 행복의 빚을 지고 있어요.$B$B깨달음을 찾고 있다면 네트 파글이 길을 알려줄 거야 "
rows["247:1820989307"]="그림 배톨의 멸망 이후 우리는 와일드햄어들이 단결된 적이 없습니다. 이 고산지대에, 다른 세계로부터 잊혀진,$B$B다시 함께 하는 것은 쉽지 않을 겁니다. "
rows["247:1945876543"]="정당한 질문입니다$b$b서쪽 으로 있는 절벽 에서 신호 불 을 찾아 볼 수도 있습니다. 마지막으로, 북쪽 으로 멀리 있는 시리투스 로 가는 길 은 종종 위험 으로 만들어진다.$b$b저곳은 내가 체크하는 곳이야"
rows["247:2106834392"]="이 운명은 유래했나? 만약 당신이 죽음으로 왔다면, 예언이 성취되었으니, 당신의 의식은 뒤틀린 황천에서 부패해지길 바랍니다."
rows["247:213983313"]="먼저 칼은 적을 섬기는 사람들의 영혼으로 먹여야 하고, 칼이 힘을 끌어내기 전에, 나는 그것을 그림자 Frost에 묶어야 합니다. "
rows["247:2145812787"]="저는 모든 부패한 형제들을 깨끗하게 하고 싶지만, 부패하지 않은 우리들 중 지도자가 없는 사람이 될 수 없습니다.\010우리는 이 비참한 영향의 확산을 막아야 합니다. 그러면 저는 순수해 있는 우리들을 자유로 이끌게 될 것입니다."
rows["247:299674183"]="그리먼너는 어미 이야기들을 많이 들려줬어, 그리먼은 어느거인지 기억이 안 나"
rows["247:811240844"]="마그니 왕이 이 축제에 대해 제게 다가왔을 때 저는 흥분했습니다. 저는 거미들의 약간의 도움으로 우리가 이것을 기억할 수 있는 폭발로 만들 수 있다는 것을 설명하기 시작했습니다."
rows["248:1202571128"]="많은 것을 알고...$b$b어떤 사람들은 그저 관찰하고 있다고 말하고, 어떤 사람들은 그들이 우리의 해양생물을 변화시키고 있다고 생각하고, 다른 사람들은 그들이 여기 와서 아제로스를 점령하고 있다고 생각합니다!$b$b내 로켓 추진탄으로 하나를 격추하면 답을 얻을 수 있어"
rows["248:1486958646"]="모든 거룩한 것, 사랑하는 것, 제발 우리에게 이로부터 구출하러 왔다고 말해줘 포세이큰 내가 해군 탐험대에 있긴 하지만, 이 곳을 떠나기 위해 배낭에 올라갈 수 있는 금빨을 내 입에서 줄게"
rows["248:1594369521"]="지옥의 비치는 볼진이 죽은 줄 알았고, 볼진이 센진 마을에 나타나기 전까지. 데워치프가 반란을 진압하려고 했지만 우리는 그를 기다리고 있었다."
rows["248:1723496942"]="해적 친구들, 들어봐요. 저는 이 시인지 캐릭터와 함께 있지 않습니다. 제가 이 구석에서 빠져나갈 수 있다면, 저는 여러분들이 가진 최고의 엔지니어가 될 것이라고 확신합니다. 정말, 당신은 당신의 상기의 정확성을 보았습니까? 너무 가까이, 하지만 아주 멀리!"
rows["248:1796185610"]="이제 마력의 눈을 조종하면서 우리를 방해하는 것은 지맥 수호자 에레고스뿐이리라. 에레고스는 마력의 눈 가장 꼭대기에 있는 정렬의 고리 위를 날아다닌다. 에레고스는 믿을 수 없을 만큼 강한 놈이니, 싸움은 내게 맡기고 뒤에 숨어 있거라."
rows["248:182338487"]="엄밀히 말하면, 그건 사실이 아닙니다. 카자로 산과 같은 화산에서 날아오는 바위는 발폭이라고 불립니다. 그것은 하늘이 아닙니다. 그것은 녹은 바위, 또는 테프라입니다."
rows["248:1835776789"]="노인 틸은 작은 토지 소유 한 '땅 그 언덕에.$B$B어느 날 그는 파고 파고, 그 언덕 아래에서 온 동굴을 발견하지 못했던 만큼 깊이 파고 갔습니다!$B$B그 동굴에서 뭘 찾았다고 생각하십니까?"
rows["248:1913113472"]="어렸을 때, 우리는 당신이 읽으려면 전 세계의 기적을 수집했습니다. 그리고 당신은 더 작은 암흑 달 카드 세트를 수집 할 수 있다면 알려주세요."
rows["248:2030207055"]="친구여, 당신 덕분에 이번 일을 할 수 있었소. 고맙소이다. 오늘 일은 절대 잊을 수 없을 것이오! 난 잠시 여기서 우서 경께서 하신 말씀을 마음에 새기겠소. 당신은 서리바람 야영지의 대여사제 맥도널에게 돌아가시오. 그녀는 여기서 일어난 일들에 대해 매우 궁금해할 것이오."
rows["248:2137872383"]="막투르, 나는 잃어버린 드레나이를 위기에서 구할 방법이 있다고 믿습니다. 그들을 연구하면 그들을 파괴하고 있는 사악한 힘을 치료할 방법을 찾을 겁니다. 또한 그 과정에서 뒤틀린 드레나이들이 입은 피해도 복구할 수 있을 것이라 믿습니다."
rows["248:241949578"]="안녕, 친구!$B$B러셀의 이름은 음악이 내 사업이야 옛날의 위대한 와일드햄어 영웅들은 노래로 살아있어요$B$B잠깐만 기다려봐!"
rows["248:470541422"]="요리사가 되길 원하십니까? 언더시티 도시 남쪽에서 훈련하기 위해 엘리베이터를 잡을 수 있습니다 로데론나무를 짓는 놈들한테 얘기해 언더시티 도착하면 더 많은 도움을 요청할 수 있는 보호자"
rows["248:492451815"]="숲은 변화의 씨앗과 함께 노래하지만 고통으로 울고 있습니다.$B$B새 친구들인 드레네이들은 우리와 같이 우리를 도와야 합니다. 잿빛 골짜기 더 이상 안 돼"
rows["248:53336215"]="크림슨 홀에 들어가는 걸 막는 장벽이 무너졌어 피 왕자와 여왕은 우리의 도착을 기다리고 있어$B$B마지막 장벽은 $4939W일 내에 철거될 것입니다."
rows["248:625697253"]="가끔은 저 유독한 피 엘프들이 와서 미련한 반응물이나 독을 요구합니다.$B$B<  ⁇ 푸스는 열심히 삼키고 있다. >$B$B우린 그런 걸 원하지..."
rows["248:716715209"]="어, 그 귀여운 소녀는 북쪽 항구에 살고 있어요$B$B그 소녀는 어릴 때부터 알고 있어요$B$B그녀는 항상 진흙에 파고, 호수에서 수영하거나 나무에서 뛰어내리는 걸 알고 있어요. 부모님은 그녀를 옳다고 불렀어요."
rows["248:779620185"]="리치 왕의 잔인한 통치는 노스렌드의 모든 주민들, 특히 어린이들에게 큰 고통을 초래했습니다. 만약 여러분이 오라클스나  ⁇ 지하트 부족의 친구라면, 아마도 한 주 동안 고아를 돌보는 것을 고려할 수도 있습니다."
rows["248:816411985"]="레이  ⁇ 의 추락 후 며칠 동안 계곡은 가장 깊은 검은 구름으로 감싸여 있었다. 레이  ⁇ 이 그의 마지막 순간에 불러온 다른 세계 폭풍은 계곡을 비로 덮었고, 산에 번개의 날카로운 창을 때렸다."
rows["248:924287248"]="친구여, 나는 사태가 악화될까 두렵네. 에메랄드의 꿈속에서 우리는 고대의 악마로 태어난 새로운 적과 싸우고 있네. 이세라의 고귀한용군단은 고대의 속삭임에 희생되었네. 마치 악몽이 차원의 경계를 뚫고 아제로스에서 새로운 숙주를 찾고 있는 것 같네."
rows["248:956696513"]="새매가 까마귀석의 위치 추적에 성공한 이후로, 엘라이라가 무척 먼 거리에 내 목소리를 전하기 위해 다른 새매 녀석을 훈련시키고 있답니다. 그가 당신이 서판에서 밝혀진 새 영혼을 조사하면서 우리와 교신하는데 도움을 줄 겁니다."
rows["249:1022630886"]="바디지 수집은 일정에 따라 진행되고 있습니다. 천장 바디지에 관해서는 우리는 $2077w의 $2076w을 수집했습니다. 실크 바디지에는 $2083w에서 $2082w가 수록되었으며, 우리는 $2090w의 룬 셔츠 바디지 중 $2088w가 필요합니다."
rows["249:1165491114"]="< 로켓을 보고 긴장한 미소를 깜빡이는 것>$b$b좋아, 그래, 그래서 내가 몇 명에게 로켓을 만들었을지도 몰라 금이 좋고, 내 일 때문에 돈을 받았지"
rows["249:1341830829"]="크리스탈 레이크 옆에 아델 필더라는 여자가 살고 있습니다. 그녀는 지역 경비자들을 위해 지역 스킨러 헬렌으로부터 extra 가죽을 만들어 냅니다. 아마 그 여자만이 직업에 관심이 있는지 확인 할 것입니다."
rows["249:134340859"]="그래서, 우리는 이렇게 되었습니다. 우리는 함께 배우고 성장했습니다. 수년 동안, 그리고 지금 우리는 전투장에서 직접 만나게 됩니다. 호드우리 둘 다"
rows["249:1396872675"]="눈 안의 피가 붉은 분수, 스컬지눈은 당신의 마음에 들어가서 본능적으로 뒤로 물러나도록 자극합니다. 이 물체의 존재에 매우 불편함을 느끼죠."
rows["249:1637275589"]="이제 브리쿨에게 첫 번째 명령을 내리겠노라! 브리쿨의 어버이가 낳은 모든 기형아는 태어나는 즉시 제거한다! 우리의 피를 반드시 순수하게 보존해야 한다! 이미론의 명령을 어기는 자는 샬레르브론으로 보내 처형할 것이다!"
rows["249:167013388"]="아센 판결과 당신 같은 영웅들의 지속적인 희생은 우리 모두를 최종 승리에 더 가까이 데려옵니다. 이제 저는 아이스크라운 성원에 와서 스컬지에 맞서 싸우는 사람들에게 도움을 줄 것입니다. 함께 우리는 리치 왕의 독재를 끝낼 것입니다!"
rows["249:1671061848"]="만약 당신의 파티가 준비되면, 나는 뒤로 물러서서 당신이 여기서 방어하는 것을 계속할 준비가 되어 있습니다."
rows["249:1729261778"]="배신당했어요. 우리는 매주 이곳을 찾아왔어요. 그들은 단순한 상인들이던 것 같았죠. \010이 어부들은 한 손으로 우리를 환영하고, 다른 손은 뒤에서  ⁇ 어 칼을 들고, 우리가 돌아서서 그들을 몰아넣기 위해 기다리고 있습니다."
rows["249:1788186652"]="이 축제는 전형적인 인간행동과 매우 대조적이죠. 이토록 불쌍한 독자적인 사람들이$B$B다르나서스은 지원하고 격려하기 위해 최선을 다해야 합니다."
rows["249:1789514088"]="티란데여, 나는 그대의 기도를 받을 가치가 없는 자라오. 그대는 진실로 빛의 천사로군. 부디 내가 지하굴로 돌아가서 꿈속으로 되돌아갈 수 있도록 도와주시오. 나 또한 말퓨리온처럼 날 기다리고 있는 사랑하는 이가 있소... 그녀에게 돌아가야 하오... 그녀를 지키러..."
rows["249:1849682576"]="저는 그렇지 않습니다. 리મ્બ라트는 이미 새로운 생명체가 분해된 땅에서 성장할 수 있다는 것을 증명했습니다. 이제 우리는 번식을 할 수 있는 방법을 찾아야 하고, 더 중요한 것은 성장을 지속해야 한다는 것입니다.$B$B제가 여기 있는 동안, 저는 또한 낙스라마스에 들어오는 모험가들에게 제 서비스를 제공하고 있습니다."
rows["249:1934028983"]="|cff0000ff급 5:|r\010  밀리 와트: $7457w-$7458w\010  피올: $7463w-$7464w\010  $7485w-$7486w\010  레퍼  ⁇ 오메 쿼티트: $7437w-$7438w\010|cff0000ff급 6:|r\010  이칸 이즈: $7467w-$7468w\010  아카마: $7461w-$7462w\010  스마시 후프스트롬: $7471w-$7472w\010  앵글루xx: $7483w-$7484w"
rows["249:2112807441"]="드래곤은 별로 모르겠지만, 큰 무서운 놈이 어느 날 나타났어요."
rows["249:2137561918"]="울트리스 관리, 물론!$B$B이 망자장은 과부하되어 거대한 폭발을 일으켰습니다. 현실에서 눈물을 흘리며 이제 공허한 생물들이 그 안에서 쏟아져 들어오고 있습니다."
rows["249:270804220"]="에코는 초자연의 무중심한 형태이고, 주주는 집중된 본질입니다. 스톤 매력을 사용하여, 저는 에코를 주주로 변환할 수 있습니다."
rows["249:347684977"]="|cff0000ff급 5:|r\010  밀리 와트: $7393w-$7394w\010  피올: $7399w-$7400w\010  $7421w-$7422w\010  레퍼  ⁇ 오메 쿼티트: $7373w-$7374w\010|cff0000ff급 6:|r\010  이칸 이즈: $7403w-$7404w\010  아카마: $7397w-$7398w\010  스마시 후프스트롬: $7407w-$7408w\010  앵글루xx: $7419w-$7420w"
rows["249:417919130"]="분석 결과, 전방에서 투기장으로 접근한 후 두 번째 부대를 지상 측면 통로로 분리하는 전략이 도출되었습니다. 이로써 외부 존재의 정신 지배가 완료되기 전에 토림의 관람석에 도착할 확률을 극대화합니다."
rows["249:565132244"]="<출육아들은 실망한 얼굴로 당신을 쳐다보고, 다른 출육아와 놀고 있다는 것을 보게 됩니다.>$B$B< 한 번에 한 번만  ⁇ 아들 놀 수 있습니다. 이 애를 가지고 캐치!을 하기 전에 현재  ⁇ 아들 돌려달라고 안리 장에게 말해주세요.>"
rows["249:672764203"]="토리움 포인트에 오신 것을 환영합니다. 감독으로서, 토리움 형제단의 모든 활동에 대해 책임지고 있습니다. 주로 광산, 수석, 그리고 약간의 경비 의무가 포함되지만, 우리는 최근 더 많은 군단 조직이 되었습니다."
rows["249:697669488"]="로봇은 속도와 맞먹을 속도를 조정할 것입니다. 저는 여러분이 속도를 높이기 위해 설치하는 것을 제안합니다. 그건 그렇고, 로봇은 아웃랜드에서 내게 배달된 금속 쓰레기 덩어리로부터 구출된 부품으로 조립되었습니다."
rows["249:726884251"]="이런 상황에서 아주 용감한 결정이야 솔직함은 신나는 거야$b$bKirin Tor의 리더, 호드 친구들을 죽였어, 가족을 죽였어, 모든 것을 파괴했지 $p?"
rows["249:803745463"]="어떻게 광석에 대해 알게 되었죠?$B$B저 망할 물건은 모두 불행을 가져왔어$B$B랜덴 목 뒤쪽에서 낮은 울음소리가 나오기 시작했어요"
rows["249:806821430"]="죽은 자들의 날 동안 사람들은 무덤에 모여서 죽은 사람의 영혼을 축하하고 소중히 여기는 것입니다.$B$B여러분은 어떤 주요 도시의 묘지에 축제를 찾을 수 있습니다. 요리, 춤, 드론 복장 등을 할 수 있습니다."
rows["249:955437699"]="저 같은 워겐은 훌륭한 스테이크를 요리하는 법을 모르죠.$B$B그냥 내가 생을 좋아하는데 비행을 하면서 숨을 쉬는 거야$B$B무슨 얘기였지? 그래, 길네아스에서 맛집이 좋았어요."
rows["24:1000058812"]="다 잘 처리해"
rows["24:1000086989"]="너희 피가 강을 이루리라!"
rows["24:1000435478"]="뭔가 보인 것 같아."
rows["24:1002726244"]="이제 가셔도 됩니다, 아가씨."
rows["24:1002869192"]="잘 죽었다, 식은 죽 먹기로군."
